export const ROZDZIALY = [
  {"nr":"1","tytul":"Makietka w skrócie","czesc":"Podstawy","ikona":"ksiazka","sekcje":[{"id":"1.1","tytul":"Co zrobisz w Makietce","html":"<p>Makietka to edytor publikacji do druku: książek, kalendarzy, planerów, notesów, zaproszeń, etykiet — strona po stronie, jak na makiecie. Na koniec dostajesz plik PDF gotowy dla drukarni. Ma to, czego potrzebuje publikacja wielostronicowa:</p><ul class=\"punkty\"><li><b>sekcje</b> o różnych formatach — np. okładka z grzbietem liczonym samym z liczby stron i papieru (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>) i środek (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>),</li><li><b>rozkładówki</b> z lustrzanymi marginesami, jak w książce (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Rozkładówki</a>),</li><li><b>wzorce</b> — tła, stopki i numery stron rysowane raz dla wielu stron (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12\">Wzorce stron</a>),</li><li><b>style tekstu</b> — jeden wygląd dla wszystkich tytułów czy podpisów (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>),</li><li><b>plik dla drukarni</b> ze spadem, znakami cięcia i osadzonymi czcionkami, także PDF/X-4 w CMYK (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22\">Eksport do PDF i PNG</a>).</li></ul><p>Mocną stroną Makietki są <b>dane</b>. Stronę możesz powielić dla każdego wiersza tabeli i wstawić do niej wartości z tego wiersza: tak powstaje kalendarz na 365 dni, planer na cały rok albo sto imiennych zaproszeń z jednego wzoru (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a> – <a href=\"#\" data-cel=\"18\">Wygląd z danych</a>).</p><figure><img src=\"img/instrukcja/projekty.png\" alt=\"Twoje projekty\" loading=\"lazy\"><figcaption>Twoje projekty</figcaption></figure>"},{"id":"1.2","tytul":"Jak zbudowany jest projekt","html":"<p>Jeden <b>projekt</b> to jedna publikacja. Projekt składa się z:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Część</th><th>Co to jest</th></tr></thead><tbody><tr><td><b>Sekcje</b></td><td>Części publikacji z własnym formatem, marginesami i numeracją, np. „Okładka” i „Środek”.</td></tr><tr><td><b>Strony</b></td><td>Strony każdej sekcji, w kolejności druku. Na stronach stoją elementy.</td></tr><tr><td><b>Elementy</b></td><td>Teksty, kształty, linie, obrazy, tabele i grupy.</td></tr><tr><td><b>Wzorce</b></td><td>Elementy wspólne dla wielu stron — leżą pod treścią strony albo nad nią.</td></tr><tr><td><b>Style</b></td><td>Zapisane wyglądy tekstu.</td></tr><tr><td><b>Tabele danych</b></td><td>Arkusze z danymi do pól w tekście i do powielania stron.</td></tr><tr><td><b>Obrazy</b></td><td>Wszystkie zdjęcia i grafiki projektu, w jednym oknie.</td></tr></tbody></table></div><p>Projekt zapisuje się sam, na Twoim koncie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Zapis</a>).</p>"}]},
  {"nr":"2","tytul":"Konto","czesc":"Podstawy","ikona":"ksiazka","wstep":"Konto przechowuje Twoje projekty, czcionki i elementy, więc masz je na każdym urządzeniu.","sekcje":[{"id":"2.1","tytul":"Zakładanie konta","html":"<p>Na ekranie logowania wybierz <span class=\"ui\">Nowe konto</span> i wpisz:</p><ul class=\"punkty\"><li><b>Nazwę użytkownika</b> — 3–30 znaków: litery, cyfry, <code>_</code>, <code>.</code> i <code>-</code>. Po tej nazwie inni zaproszą Cię do projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.1\">Zapraszanie</a>).</li><li><b>E-mail</b>.</li><li><b>Hasło</b> — co najmniej 8 znaków, mała i wielka litera, cyfra i znak specjalny.</li></ul><p>Jeśli przyjdzie e-mail „Potwierdź swoje konto”, kliknij w nim przycisk — dopiero wtedy się zalogujesz.</p><div class=\"galeria\"><figure><img src=\"img/instrukcja/rejestracja.png\" alt=\"Nowe konto\" loading=\"lazy\"><figcaption>Nowe konto</figcaption></figure><figure><img src=\"img/instrukcja/rejestracja-wyslano.png\" alt=\"Sprawdź skrzynkę\" loading=\"lazy\"><figcaption>Sprawdź skrzynkę</figcaption></figure></div>"},{"id":"2.2","tytul":"Logowanie i hasło","html":"<p><span class=\"ui\">Nie pamiętasz hasła?</span> wysyła link do ustawienia nowego hasła. Link działa jeden raz; gdy wygaśnie, poproś o nowy.</p><figure><img src=\"img/instrukcja/logowanie.png\" alt=\"Logowanie\" loading=\"lazy\"><figcaption>Logowanie</figcaption></figure>"},{"id":"2.3","tytul":"Ustawienia konta","html":"<p>Kliknij kółko z inicjałem w prawym górnym rogu listy projektów i wybierz <span class=\"ui\">Ustawienia konta</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-konta.png\" alt=\"Menu konta\" loading=\"lazy\"><figcaption>Menu konta</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Wiersz</th><th>Co zmienisz</th></tr></thead><tbody><tr><td><b>Nazwa użytkownika</b></td><td>Nazwę, po której inni zapraszają Cię do projektów.</td></tr><tr><td><b>E-mail</b></td><td>Adres konta. <span class=\"ui\">Zmień adres</span> wysyła link potwierdzający na nowy adres; do jego kliknięcia logujesz się dotychczasowym. <span class=\"ui\">Wpisz inny adres</span> zastępuje oczekujący adres nowym.</td></tr><tr><td><b>Hasło</b></td><td><span class=\"ui\">Zmień hasło</span>.</td></tr><tr><td><b>Motyw</b></td><td>Wygląd aplikacji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.4\">Motyw</a>).</td></tr><tr><td><b>Powiadomienia</b></td><td>Powiadomienia na tym urządzeniu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.6\">Powiadomienia</a>).</td></tr><tr><td><b>Dostęp dla AI</b></td><td>Klucze dla asystentów AI (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"26.2\">Klucz dla AI</a>).</td></tr><tr><td><b>Zestaw marki</b></td><td>Kolory, czcionki i logo marki — dostępne w każdym projekcie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>).</td></tr><tr><td><b>Miejsce</b></td><td>Ile zajmują Twoje pliki i projekty (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.5\">Miejsce i limity</a>).</td></tr><tr><td><b>Usuń konto</b></td><td>Usunięcie konta (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.7\">Usuwanie konta</a>).</td></tr></tbody></table></div><p><span class=\"ui\">Wyloguj wszędzie</span> (w widoku <b>Logowanie</b>) wylogowuje wszystkie urządzenia naraz — np. po pracy na cudzym komputerze.</p><figure><img src=\"img/instrukcja/konto.png\" alt=\"Ustawienia konta\" loading=\"lazy\"><figcaption>Ustawienia konta</figcaption></figure>"},{"id":"2.4","tytul":"Motyw","html":"<p><span class=\"ui\">Ustawienia konta</span> → <b>Motyw</b>: <b>Jak w systemie</b>, <b>Jasny</b> albo <b>Ciemny</b>. Szybki przełącznik (ikona półkola) jest też na liście projektów i w menu <span class=\"ui\">⋯</span> edytora. Motyw zmienia tylko wygląd aplikacji — strony publikacji zawsze są na białym papierze.</p><figure><img src=\"img/instrukcja/motyw.png\" alt=\"Ciemny motyw\" loading=\"lazy\"><figcaption>Ciemny motyw</figcaption></figure>"},{"id":"2.5","tytul":"Miejsce i limity","html":"<p><span class=\"ui\">Ustawienia konta</span> → <b>Miejsce</b> pokazuje paski limitów konta:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Limit</th><th>Ile</th></tr></thead><tbody><tr><td>Pliki konta (obrazy, czcionki, podglądy linków)</td><td>2 GB</td></tr><tr><td>Jeden plik</td><td>50 MB</td></tr><tr><td>Projekty</td><td>100</td></tr><tr><td>Obrazy w jednym projekcie</td><td>1000</td></tr></tbody></table></div><p>Niżej jest lista Twoich projektów: ile zajmuje każdy, ile ma obrazów i stron, kiedy go zmieniano. <span class=\"ui\">Otwórz</span> otwiera projekt, <span class=\"ui\">Pokaż obrazy</span> — jego okno obrazów (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Okno Obrazy projektu</a>). Projekty innych osób, do których masz dostęp, są osobno i nie liczą się do Twoich limitów.</p><p>Od 80% limitu aplikacja ostrzega — tutaj i przy wgrywaniu obrazów. <span class=\"ui\">Posprzątaj…</span> pokazuje, ile miejsca zwolni, i usuwa tylko pliki, których żaden projekt już nie używa: stare wersje podmienionych zdjęć, pliki usuniętych projektów i wyłączonych linków. Pliki z ostatnich dwóch dni zostają.</p>"},{"id":"2.6","tytul":"Powiadomienia","html":"<p>Powiadomienia mówią od razu o zaproszeniach i komentarzach — także przy zamkniętej aplikacji. W <span class=\"ui\">Ustawienia konta</span> → <b>Powiadomienia</b> włącz <b>Na tym urządzeniu</b> (przeglądarka zapyta o zgodę) i wybierz, o czym chcesz wiedzieć: zaproszenia, odpowiedzi na Twoje zaproszenia, zmiany roli i dostępu, komentarze i wzmianki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">Komentarze</a>). Kliknięcie powiadomienia otwiera właściwy projekt albo wątek.</p><p>Powiadomienia włącza się osobno na każdym urządzeniu. Na iPhonie i iPadzie działają tylko w zainstalowanej aplikacji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Instalacja aplikacji</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-powiadomienia.png\" alt=\"Powiadomienia w ustawieniach konta\" loading=\"lazy\"><figcaption>Powiadomienia w ustawieniach konta</figcaption></figure>"},{"id":"2.7","tytul":"Usuwanie konta","html":"<p><span class=\"ui\">Ustawienia konta</span> → <b>Usuń konto</b> usuwa konto i wszystkie Twoje projekty. Zanim to zrobisz, wyeksportuj projekty, które chcesz zachować (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Plik projektu</a>).</p><p class=\"ramka-instrukcji uwaga\"><b>Uwaga.</b> Usunięcia konta nie da się cofnąć.</p>"},{"id":"2.8","tytul":"Kontakt","html":"<p>Pytanie, pomysł albo błąd? <span class=\"ui\">Kontakt</span> jest w menu konta i pod formularzem logowania. <span class=\"ui\">Załącz pliki</span> dodaje zrzut ekranu, plik projektu albo PDF (do 5 plików, razem 10 MB). Możesz też pisać na kontakt@makietka.app.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kontakt.png\" alt=\"Formularz kontaktowy z załącznikiem\" loading=\"lazy\"><figcaption>Formularz kontaktowy z załącznikiem</figcaption></figure>"},{"id":"2.9","tytul":"Zestaw marki","html":"<p>Kolory, czcionki i logo firmy (albo szkoły, parafii, klubu) zapisujesz raz — na koncie — i masz je w każdym projekcie: <span class=\"ui\">Ustawienia konta</span> → <b>Zestaw marki</b> → <span class=\"ui\">Edytuj zestaw marki…</span> (albo Biblioteka → <b>Marka</b>).</p><ul class=\"punkty\"><li><b>Kolory marki</b> — z nazwą, np. „Granat marki”. Przełącznik <b>Pantone / CMYK</b> robi z koloru kolor dodatkowy, drukowany osobną farbą (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.1\">Kolory dodatkowe</a>).</li><li><b>Czcionki marki</b> — jedna do nagłówków, jedna do tekstu.</li><li><b>Logo</b> — PNG, JPG, WebP albo SVG; wstawisz je z Biblioteki.</li></ul><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka.png\" alt=\"Zestaw marki\" loading=\"lazy\"><figcaption>Zestaw marki</figcaption></figure><p>Marka jest pod ręką w oknie koloru (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.7\">Wybór koloru</a>), na górze listy czcionek (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.8\">Czcionki</a>) i w Bibliotece (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>).</p><p><b>Zastosuj markę do projektu</b> (<span class=\"ui\">⋯</span> w edytorze) zamienia kolory i czcionki całego projektu na markowe: każdy kolor dostaje najbliższy kolor marki (czerń, biel i szarości zostają), najczęstsza czcionka — czcionkę tekstu, pozostałe — nagłówków. Przed <span class=\"ui\">Zastosuj</span> zmienisz każdą propozycję albo wybierzesz „bez zmian”.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka-zastosuj.png\" alt=\"Zastosuj markę do projektu\" loading=\"lazy\"><figcaption>Zastosuj markę do projektu</figcaption></figure>"}]},
  {"nr":"3","tytul":"Projekty","czesc":"Podstawy","ikona":"ksiazka","wstep":"Projekt to jedna publikacja: tu zakładasz, otwierasz, kopiujesz i zapisujesz projekty.","sekcje":[{"id":"3.1","tytul":"Lista projektów","html":"<p>Kliknięcie karty otwiera projekt w edytorze — na stronie, którą ostatnio edytowałeś na tym urządzeniu.</p><ul class=\"punkty\"><li><b>Chmurka</b> przy nazwie mówi, czy zmiany są na koncie: z ptaszkiem — zapisano, z zegarem — czekają na wysłanie, przekreślona — brak internetu (zmiany są na urządzeniu i wyślą się same).</li><li>Plakietka <b>Udostępniony</b> — projekt ma link do podglądu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"24\">Udostępnianie linkiem</a>). Kliknięcie plakietki otwiera okno linku.</li><li>Projekty udostępnione Ci przez innych mają plakietkę z nazwą właściciela i dopisek „Możesz edytować” albo „Możesz oglądać”. Filtry <span class=\"ui\">Wszystkie</span>, <span class=\"ui\">Moje</span> i <span class=\"ui\">Udostępnione mi</span> pojawiają się, gdy masz takie projekty.</li><li><span class=\"ui\">Zaproszenia</span> z liczbą — zaproszenia do cudzych projektów czekające na odpowiedź (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.3\">Przyjmowanie zaproszenia</a>).</li></ul><figure><img src=\"img/instrukcja/projekty.png\" alt=\"Lista projektów\" loading=\"lazy\"><figcaption>Lista projektów</figcaption></figure>"},{"id":"3.2","tytul":"Nowy projekt","html":"<p><span class=\"ui\">Nowy projekt</span> pyta o nazwę, format strony (A4, A5, A6, B5, kwadrat albo <b>Własny</b> w mm), orientację i:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Pole</th><th>Co ustawia</th></tr></thead><tbody><tr><td><b>Spad</b></td><td>Pas za krawędzią strony, który drukarnia odcina — zwykle 3 mm (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.1\">Linie na stronie</a>).</td></tr><tr><td><b>Marginesy</b></td><td>Bezpieczny obszar na teksty, w mm.</td></tr><tr><td><b>Układ stron</b></td><td><b>Pojedyncze strony</b> albo <b>Rozkładówki (lewa + prawa)</b>, jak w książce.</td></tr></tbody></table></div><p>Wszystko zmienisz później w ustawieniach sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>).</p><p><b>Zacznij od</b>: <b>Pustej strony</b> albo <b>Gotowego szablonu</b> — wtedy po utworzeniu projektu otworzy się galeria gotowych sekcji (kalendarz, planer, zaproszenie…), a wybrany szablon zastąpi pustą stronę (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.10\">Gotowe sekcje (szablony dokumentów)</a>).</p><figure><img src=\"img/instrukcja/nowy-projekt.png\" alt=\"Nowy projekt\" loading=\"lazy\"><figcaption>Nowy projekt</figcaption></figure>"},{"id":"3.3","tytul":"Menu projektu","html":"<p><span class=\"ui\">⋯</span> na karcie projektu: <span class=\"ui\">Podgląd</span> (od razu, bez edytora, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Podgląd</a>), <span class=\"ui\">Zmień nazwę</span>, <span class=\"ui\">Duplikuj</span> (np. kalendarz na kolejny rok), <span class=\"ui\">Eksportuj do pliku (.makietka)</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.6\">Plik projektu</a>), <span class=\"ui\">Współpraca…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25\">Współpraca</a>) i <span class=\"ui\">Usuń projekt</span>. W projekcie innej osoby zamiast duplikowania i usuwania są <span class=\"ui\">Zrób własną kopię</span> i <span class=\"ui\">Opuść projekt</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.6\">Opuszczanie projektu i kopia</a>).</p><figure><img src=\"img/instrukcja/menu.png\" alt=\"Menu projektu\" loading=\"lazy\"><figcaption>Menu projektu</figcaption></figure>"},{"id":"3.4","tytul":"Zapis","html":"<p>Nie ma przycisku „Zapisz” — każda zmiana zapisuje się sama, najpierw na urządzeniu, a po chwili na koncie. Bez internetu zmiany czekają na urządzeniu i wyślą się same po powrocie sieci. Stan zapisu pokazuje chmurka obok nazwy projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.1\">Lista projektów</a>).</p>"},{"id":"3.5","tytul":"Kilka urządzeń i cofanie","html":"<p>Ten sam projekt możesz mieć otwarty na kilku urządzeniach albo w kilku kartach. Zmiana zrobiona na jednym pojawia się na drugim po chwili, bez odświeżania.</p><p>Gdy projekt zmieniono w dwóch miejscach naraz, aplikacja <b>łączy zmiany element po elemencie</b>: gdy na jednym urządzeniu przesuniesz zdjęcie, a na drugim poprawisz tytuł, zostaną obie zmiany. Pyta tylko wtedy, gdy ten sam element zmieniono w obu miejscach — przy każdym wybierasz <span class=\"ui\">z tego urządzenia</span> albo <span class=\"ui\">z konta</span>.</p><p><span class=\"ui\">Cofnij</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>) i <span class=\"ui\">Ponów</span> (<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd>) obejmują cały projekt: elementy, strony, sekcje, wzorce, style, dane i serie. Historia sięga 80 kroków i zostaje po zamknięciu projektu — na tym samym urządzeniu. Cofanie zdejmuje tylko zmiany zrobione na tym urządzeniu; zmiany innych osób i AI zostają.</p>"},{"id":"3.6","tytul":"Plik projektu","html":"<ul class=\"punkty\"><li><span class=\"ui\">Eksportuj do pliku (.makietka)</span> (menu <span class=\"ui\">⋯</span> na karcie) zapisuje cały projekt, z obrazami i czcionkami, do pliku <code>.makietka</code> — to kopia zapasowa albo sposób na przekazanie projektu.</li><li>Przycisk ze strzałką obok <span class=\"ui\">Nowy projekt</span> wczytuje projekt z pliku <code>.makietka</code>.</li><li>Zainstalowana aplikacja na komputerze otwiera pliki <code>.makietka</code> dwuklikiem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Instalacja aplikacji</a>).</li></ul>"}]},
  {"nr":"4","tytul":"Ekran edytora","czesc":"Edytor","ikona":"olowek","wstep":"Gdzie co jest w edytorze — paski, panele i menu.","sekcje":[{"id":"4.1","tytul":"Układ ekranu","html":"<p>Projekt otwiera się w edytorze. Ekran ma pięć części:</p><ul class=\"punkty\"><li><b>górny pasek</b> — nawigacja, cofanie, okna projektu i menu <span class=\"ui\">⋯</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.2\">Górny pasek</a>, <a href=\"#\" data-cel=\"4.3\">Menu ⋯</a>),</li><li><b>panel stron</b> z lewej — miniatury stron pogrupowane w sekcje (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.1\">Panel stron</a>),</li><li><b>strona</b> pośrodku, a nad nią pasek wstawiania (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.4\">Pasek wstawiania</a>),</li><li><b>prawa kolumna</b> — właściwości, a pod nimi warstwy (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.5\">Właściwości i warstwy</a>, <a href=\"#\" data-cel=\"10\">Warstwy</a>),</li><li><b>prawy dolny róg</b> — linie pomocnicze, siatka i powiększenie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>).</li></ul><p>Najechanie myszą na przycisk pokazuje jego nazwę i skrót klawiszowy.</p><figure><img src=\"img/instrukcja/edytor.png\" alt=\"Edytor\" loading=\"lazy\"><figcaption>Edytor</figcaption></figure>"},{"id":"4.2","tytul":"Górny pasek","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-pasek-gorny.png\" alt=\"Górny pasek\" loading=\"lazy\"><figcaption>Górny pasek</figcaption></figure><p>Od lewej: <span class=\"ui\">← Projekty</span>, <b>nazwa projektu</b> (kliknij, żeby ją zmienić) ze stanem zapisu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.4\">Zapis</a>), <span class=\"ui\">Cofnij</span> i <span class=\"ui\">Ponów</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.5\">Kilka urządzeń i cofanie</a>), <span class=\"ui\">Wzorce</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12\">Wzorce stron</a>), <span class=\"ui\">Dane</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a>), <span class=\"ui\">Podgląd</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Podgląd</a>), <b>format</b> sekcji, np. „A5” — otwiera ustawienia sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>), <span class=\"ui\">Komentarze</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">Komentarze</a>), lupa <span class=\"ui\">Znajdź i zamień</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.15\">Znajdź i zamień</a>) i <span class=\"ui\">⋯</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.3\">Menu ⋯</a>).</p><p>Napisy obok ikon pojawiają się, gdy jest na nie miejsce — zmienisz to w menu widoku: <b>Napisy na górnym pasku</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>). Na wąskim telefonie <span class=\"ui\">Wzorce</span>, <span class=\"ui\">Dane</span>, <span class=\"ui\">Komentarze</span> i lupa są w menu <span class=\"ui\">⋯</span>.</p>"},{"id":"4.3","tytul":"Menu ⋯","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-wiecej.png\" alt=\"Menu ⋯\" loading=\"lazy\"><figcaption>Menu ⋯</figcaption></figure><p>Pozycje są w grupach:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Grupa</th><th>Pozycje</th></tr></thead><tbody><tr><td>Szukanie i uwagi</td><td><span class=\"ui\">Znajdź i zamień…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.15\">Znajdź i zamień</a>), <span class=\"ui\">Komentarze</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">Komentarze</a>).</td></tr><tr><td>Zasoby projektu</td><td><span class=\"ui\">Obrazy projektu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Okno Obrazy projektu</a>), <span class=\"ui\">Czcionki projektu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.8\">Czcionki</a>), <span class=\"ui\">Kolory do druku…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.1\">Kolory dodatkowe</a>, <a href=\"#\" data-cel=\"23.5\">Tryb kolorów projektu</a>); na telefonie też <span class=\"ui\">Wzorce…</span> i <span class=\"ui\">Dane…</span>.</td></tr><tr><td>Format i marka</td><td><span class=\"ui\">Zmień format projektu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.9\">Zmiana formatu ze skalowaniem</a>), <span class=\"ui\">Zastosuj markę do projektu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>).</td></tr><tr><td>Druk i eksport</td><td><span class=\"ui\">Sprawdź przed drukiem</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>), <span class=\"ui\">Eksportuj do PDF…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22\">Eksport do PDF i PNG</a>), <span class=\"ui\">Drukuj w domu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.8\">Drukuj w domu</a>), <span class=\"ui\">Pobierz bieżącą stronę jako PNG</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.5\">Strona jako PNG</a>).</td></tr><tr><td>Pozostałe</td><td><span class=\"ui\">Współpraca…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25\">Współpraca</a>) i przełącznik motywu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.4\">Motyw</a>).</td></tr></tbody></table></div>"},{"id":"4.4","tytul":"Pasek wstawiania","html":"<p>Pasek nad stroną wstawia nowe elementy (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.1\">Wstawianie</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wstaw.png\" alt=\"Pasek wstawiania\" loading=\"lazy\"><figcaption>Pasek wstawiania</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Przycisk</th><th>Klawisz</th><th>Co wstawia</th></tr></thead><tbody><tr><td><span class=\"ui\">Tekst</span></td><td><kbd>T</kbd></td><td>Ramkę tekstu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6\">Tekst</a>).</td></tr><tr><td><span class=\"ui\">Prostokąt</span></td><td><kbd>R</kbd></td><td>Prostokąt (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.1\">Prostokąt, elipsa i wielokąt</a>).</td></tr><tr><td><span class=\"ui\">Elipsa</span></td><td><kbd>E</kbd></td><td>Elipsę albo koło (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.1\">Prostokąt, elipsa i wielokąt</a>).</td></tr><tr><td><span class=\"ui\">Wielokąt</span></td><td><kbd>P</kbd></td><td>Wielokąt albo gwiazdę — najpierw wybór kształtu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.1\">Prostokąt, elipsa i wielokąt</a>).</td></tr><tr><td><span class=\"ui\">Linia</span></td><td><kbd>L</kbd></td><td>Odcinek (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.2\">Linia</a>).</td></tr><tr><td><span class=\"ui\">Obraz</span></td><td>—</td><td>Zdjęcie albo grafikę (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.1\">Wstawianie obrazu</a>).</td></tr><tr><td><span class=\"ui\">Rysuj</span></td><td><kbd>B</kbd></td><td>Linię rysowaną odręcznie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.3\">Rysowanie odręczne</a>).</td></tr><tr><td><span class=\"ui\">Pióro</span></td><td><kbd>N</kbd></td><td>Kształt z punktów i łuków (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.4\">Pióro i edycja punktów</a>).</td></tr><tr><td><span class=\"ui\">Tabela</span></td><td>—</td><td>Tabelę z wierszami i kolumnami (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9\">Tabela</a>).</td></tr><tr><td><span class=\"ui\">Biblioteka</span></td><td>—</td><td>Gotowe elementy: kształty, ramki, ozdobniki, planery, kalendarze, wykresy i inne (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>).</td></tr><tr><td><span class=\"ui\">Komentarz</span></td><td>—</td><td>Komentarz przypięty do miejsca na stronie albo do zaznaczonego elementu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">Komentarze</a>).</td></tr></tbody></table></div><p>Podpisy pod ikonami włączysz w menu widoku: <b>Podpisy narzędzi</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>).</p><p><b>Na telefonie</b> pozostałe narzędzia — <span class=\"ui\">Wielokąt albo gwiazda</span>, <span class=\"ui\">Rysowanie odręczne</span>, <span class=\"ui\">Pióro</span>, <span class=\"ui\">Komentarz</span> i <span class=\"ui\">Kopiuj wygląd</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Kopiuj wygląd (malarz formatów)</a>) — są pod <span class=\"ui\">⋯</span> na końcu paska. Gdy jedno z nich działa, <span class=\"ui\">⋯</span> pokazuje jego ikonę; stuknięcie kończy narzędzie.</p><figure class=\"kadr telefon\"><img src=\"img/instrukcja/k-wstaw-telefon.png\" alt=\"Menu ⋯ paska wstawiania na telefonie\" loading=\"lazy\"><figcaption>Menu ⋯ paska wstawiania na telefonie</figcaption></figure>"},{"id":"4.5","tytul":"Właściwości i warstwy","html":"<p>U góry prawej kolumny są <b>właściwości</b>, pod nimi panel <b>Warstwy</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10\">Warstwy</a>). Nagłówek właściwości mówi, czego dotyczą ustawienia:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Nagłówek</th><th>Kiedy</th><th>Co ustawiasz</th></tr></thead><tbody><tr><td><b>Zaznaczony element</b> · rodzaj (np. „Tekst”)</td><td>Jest zaznaczony element.</td><td>Wygląd i położenie tego elementu.</td></tr><tr><td><b>Ustawienia narzędzia</b> · nazwa (np. „Rysowanie”)</td><td>Włączone jest narzędzie, np. <span class=\"ui\">Rysuj</span>. Nagłówek ma wtedy tło w kolorze akcentu.</td><td>Jak będą wyglądać następne elementy — „Tak będą wyglądać następne linie.”</td></tr><tr><td><b>Nic nie jest zaznaczone</b> · „Strona”</td><td>Nic nie jest zaznaczone.</td><td>Ustawienia otwartej strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.3\">Właściwości strony</a>).</td></tr></tbody></table></div><p>Przy zaznaczonym elemencie w nagłówku są <span class=\"ui\">Kopiuj do schowka</span>, <span class=\"ui\">Duplikuj</span>, <span class=\"ui\">Kopiuj wygląd</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Kopiuj wygląd (malarz formatów)</a>), <span class=\"ui\">Zapisz w bibliotece</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>) i <span class=\"ui\">Usuń</span>. Na dole kolumny jest lista <b>Ostrzeżenia</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.2\">Ostrzeżenia</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-rysowanie.png\" alt=\"Ustawienia narzędzia: rysowanie\" loading=\"lazy\"><figcaption>Ustawienia narzędzia: rysowanie</figcaption></figure><p>Na telefonie te panele otwierają przyciski na dole ekranu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.2\">Edytor na telefonie</a>).</p><figure><img src=\"img/instrukcja/wlasciwosci.png\" alt=\"Właściwości zaznaczonego tekstu\" loading=\"lazy\"><figcaption>Właściwości zaznaczonego tekstu</figcaption></figure>"},{"id":"4.6","tytul":"Prawy dolny róg i menu widoku","html":"<figure class=\"kadr\"><img src=\"img/instrukcja/k-widok.png\" alt=\"Prawy dolny róg\" loading=\"lazy\"><figcaption>Prawy dolny róg</figcaption></figure><ul class=\"punkty\"><li><b>dwie kartki</b> — tylko w sekcji z rozkładówkami: cała rozkładówka albo jedna strona (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Rozkładówki</a>),</li><li><span class=\"ui\">Linie pomocnicze</span> (<kbd>W</kbd>) — pokazuje albo chowa marginesy, spad, grzbiet i prowadnice (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.1\">Linie na stronie</a>),</li><li><span class=\"ui\">Widok</span> (ikona kratki) — menu widoku,</li><li><span class=\"ui\">−</span>, procent, <span class=\"ui\">+</span> — powiększenie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.6\">Powiększenie</a>).</li></ul><p>Menu widoku:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Pozycja</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Siatka</b>, <b>Przyciągaj do siatki</b>, <b>Krok siatki</b></td><td>Siatka co zadany krok w mm (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.3\">Siatka</a>).</td></tr><tr><td><b>Siatka linii bazowych</b></td><td>Linie bazowe z ustawień sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.13\">Siatka linii bazowych</a>).</td></tr><tr><td><b>Przyciągaj do elementów i pokazuj odległości</b></td><td>Różowe linie i odległości w mm przy przesuwaniu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.5\">Przyciąganie i odległości</a>).</td></tr><tr><td><b>Linijki</b></td><td>Linijki w mm nad stroną i z lewej (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.4\">Linijki i prowadnice</a>).</td></tr><tr><td><b>Zablokuj prowadnice</b>, <span class=\"ui\">Usuń prowadnice z tej strony</span></td><td>Ochrona i sprzątanie prowadnic (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.4\">Linijki i prowadnice</a>).</td></tr><tr><td><b>W rozkładówkach pokazuj jedną stronę</b></td><td>To samo co przycisk z dwiema kartkami (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Rozkładówki</a>).</td></tr><tr><td><b>Sprawdzaj pisownię</b></td><td>Falista czerwona linia pod słowami spoza słownika i część <b>Pisownia</b> w panelu tekstu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.16\">Sprawdzanie pisowni</a>).</td></tr><tr><td><b>Pokaż uszlachetnienia</b></td><td>Efekt lakieru, folii, tłoczenia i bieli na stronie; wyłączony — zwykły widok (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.3\">Widok uszlachetnień</a>).</td></tr><tr><td><b>Podpisy narzędzi</b></td><td>Podpisy pod ikonami paska wstawiania.</td></tr><tr><td><b>Napisy na górnym pasku</b></td><td><span class=\"ui\">Auto</span> — gdy się mieszczą, <span class=\"ui\">Zawsze</span>, <span class=\"ui\">Nigdy</span>.</td></tr></tbody></table></div><p>Ustawienia widoku dotyczą tylko tego urządzenia.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-widoku.png\" alt=\"Menu widoku\" loading=\"lazy\"><figcaption>Menu widoku</figcaption></figure>"}]},
  {"nr":"5","tytul":"Elementy na stronie","czesc":"Edytor","ikona":"olowek","wstep":"Wszystko, co stoi na stronie, to element: tu jest to, co wspólne dla wszystkich — zaznaczanie, przesuwanie, grupy, gotowe elementy z Biblioteki.","sekcje":[{"id":"5.1","tytul":"Wstawianie","html":"<p>Kliknij narzędzie na pasku wstawiania (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.4\">Pasek wstawiania</a>) — element pojawi się na środku widoku i będzie zaznaczony. Obraz możesz też przeciągnąć z dysku na stronę albo wkleić ze schowka (<kbd>Ctrl</kbd>+<kbd>V</kbd>).</p><p>Elementy wzorców (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12\">Wzorce stron</a>) widać na stronie, ale nie da się ich tu zaznaczyć — zmieniasz je we wzorcu.</p><figure><img src=\"img/instrukcja/wstawianie.png\" alt=\"Wstawiony tekst\" loading=\"lazy\"><figcaption>Wstawiony tekst</figcaption></figure>"},{"id":"5.2","tytul":"Zaznaczanie","html":"<ul class=\"punkty\"><li><b>Kliknięcie</b> zaznacza element.</li><li><kbd>Shift</kbd> + kliknięcie dodaje element do zaznaczenia albo go z niego usuwa.</li><li><b>Przeciągnięcie ramki</b> od pustego miejsca strony zaznacza elementy, których dotknie.</li><li><kbd>Ctrl</kbd>+<kbd>A</kbd> zaznacza wszystkie elementy strony.</li><li>Element leżący pod innym zaznaczysz na liście warstw (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10\">Warstwy</a>).</li><li><b>Kliknięcie dwa razy</b>: w tekście — pisanie, w grupie — wejście do grupy, w komórce tabeli — pisanie w komórce, w kształcie z pióra — edycja punktów, w obrazie — kadrowanie.</li><li><kbd>Esc</kbd> zdejmuje zaznaczenie.</li></ul>"},{"id":"5.3","tytul":"Przesuwanie, rozmiar i obrót","html":"<ul class=\"punkty\"><li><b>Przeciągnij</b> element, żeby go przesunąć. Strzałki przesuwają o 1 mm, z <kbd>Shift</kbd> — o 10 mm.</li><li><b>Kółka w rogach i na bokach</b> zmieniają rozmiar, <b>kółko nad elementem</b> obraca.</li><li><kbd>Shift</kbd> przy przeciąganiu — tylko w poziomie albo w pionie; przy obracaniu — co 15°.</li><li><kbd>Alt</kbd> przy przeciąganiu — przeciągasz kopię.</li></ul><p>Dokładne wartości wpiszesz we właściwościach, w części <b>Położenie i rozmiar (mm)</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Pole</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>X</b>, <b>Y</b></td><td>Lewy górny róg elementu, w mm od lewego górnego rogu strony (bez spadu).</td></tr><tr><td><b>Szerokość</b>, <b>Wysokość</b></td><td>Rozmiar w mm. Kłódka między nimi zachowuje proporcje.</td></tr><tr><td><b>Obrót</b></td><td>Kąt w stopniach.</td></tr></tbody></table></div><p>Przy kilku zaznaczonych elementach liczby dotyczą ich wspólnej ramki.</p>"},{"id":"5.4","tytul":"Wyrównywanie i równe odstępy","html":"<p>Część <b>Wyrównaj</b> we właściwościach:</p><ul class=\"punkty\"><li><b>jeden element</b> — wyrównanie do marginesów strony: do lewej, do środka, do prawej, do góry, do środka w pionie, do dołu,</li><li><b>kilka elementów</b> — wyrównanie do siebie,</li><li><b>trzy i więcej</b> — dodatkowo <span class=\"ui\">Rozłóż równo</span> w poziomie i w pionie: równe odstępy między elementami.</li></ul><p>Przy przesuwaniu element „przykleja się” do krawędzi i środków innych elementów, a strzałki podają odległości w mm (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.5\">Przyciąganie i odległości</a>).</p><figure><img src=\"img/instrukcja/wyrownanie.png\" alt=\"Wyrównywanie kilku elementów\" loading=\"lazy\"><figcaption>Wyrównywanie kilku elementów</figcaption></figure>"},{"id":"5.5","tytul":"Grupy","html":"<p>Zaznacz kilka elementów i wybierz <span class=\"ui\">Zgrupuj</span> (<kbd>Ctrl</kbd>+<kbd>G</kbd>). Grupa przesuwa się, skaluje i obraca jak jeden element. <span class=\"ui\">Rozgrupuj</span> (<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd>) rozdziela ją z powrotem.</p><p><b>Element grupy bez rozgrupowywania:</b> kliknij grupę dwa razy — grupa się otworzy (pomarańczowa przerywana ramka), a element pod kursorem będzie zaznaczony. Możesz go przesunąć, zmienić we właściwościach albo pisać w nim. Kliknięcie innego elementu grupy zaznacza tamten, <kbd>Shift</kbd> dodaje kolejne. <kbd>Esc</kbd>, kliknięcie poza grupą albo <span class=\"ui\">Wróć do całej grupy</span> ją zamyka.</p><ul class=\"punkty\"><li>W otwartej grupie <span class=\"ui\">Duplikuj</span> zostawia kopię w grupie, a <span class=\"ui\">Usuń</span> usuwa tylko zaznaczony element.</li><li>Grupa w grupie otwiera się kolejnym podwójnym kliknięciem; <kbd>Esc</kbd> wraca o poziom wyżej.</li></ul>"},{"id":"5.6","tytul":"Kolejność, blokada i schowek","html":"<ul class=\"punkty\"><li>Część <b>Kolejność</b>: <span class=\"ui\">Na wierzch</span>, <span class=\"ui\">Wyżej</span>, <span class=\"ui\">Niżej</span>, <span class=\"ui\">Na spód</span>. To samo zrobisz przeciąganiem na liście warstw (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"10\">Warstwy</a>).</li><li>Część <b>Inne</b>: - <b>Krycie</b> — przezroczystość elementu w %, - <b>Zablokuj położenie i rozmiar</b> — elementu nie przesuniesz przypadkiem; kolor i tekst zmienisz dalej, - <b>Wycisz ostrzeżenia dla tego obiektu</b> — np. dla tła, które celowo wychodzi na spad, - <b>Nazwa</b> — nazwa elementu na liście warstw.</li><li><span class=\"ui\">Kopiuj do schowka</span> i <kbd>Ctrl</kbd>+<kbd>V</kbd> na innej stronie wklejają element w to samo miejsce. We właściwościach strony jest też <span class=\"ui\">Wklej skopiowane elementy</span>.</li></ul>"},{"id":"5.7","tytul":"Cień","html":"<p>Część <b>Cień</b> działa dla każdego elementu:</p><p><b>Cień pod elementem</b> włącza cień. Ustawisz jego kolor, <b>Siłę</b>, przesunięcie <b>W prawo</b> i <b>W dół</b> w mm (ujemne — w lewo albo w górę) i <b>Rozmycie</b> krawędzi w mm.</p>"},{"id":"5.8","tytul":"Biblioteka","html":"<p>Biblioteka to gotowe elementy do wstawienia: kształty, ramki, ozdobniki, planery, kalendarze, wykresy i Twoje własne elementy. Otwiera ją <span class=\"ui\">Biblioteka</span> na pasku wstawiania.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-biblioteka.png\" alt=\"Biblioteka obok strony\" loading=\"lazy\"><figcaption>Biblioteka obok strony</figcaption></figure><ol class=\"kroki\"><li>Wybierz kategorię u góry albo wpisz słowo w pole <b>Szukaj</b> – szukanie przegląda wszystkie kategorie naraz.</li><li>Kliknij element – stanie na środku bieżącej strony. Na komputerze możesz też przeciągnąć kafelek na stronę: element stanie tam, gdzie go upuścisz.</li><li>Resztę ustawisz w panelu właściwości, jak przy każdym elemencie.</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Kategoria</th><th>Co w niej jest</th></tr></thead><tbody><tr><td><b>Moje elementy</b></td><td>Elementy zapisane przez Ciebie – na koncie, w każdym projekcie (niżej).</td></tr><tr><td><b>Gotowe sekcje</b></td><td>Całe dokumenty: kalendarze, planery, notesy, zaproszenia, dyplomy, wizytówki, ulotki, menu, rozdziały książki… Kafelek otwiera okno gotowych sekcji na tym szablonie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.10\">Gotowe sekcje (szablony dokumentów)</a>).</td></tr><tr><td><b>Kształty</b></td><td>Ponad 200 kształtów w grupach: <b>Podstawowe</b> (koło, kwadrat, owale, trójkąty, łuki, pierścień, sześcian, walec…), <b>Wielokąty</b> (także zaokrąglone, plaster miodu), <b>Gwiazdy i odznaki</b> (gwiazdy, pieczęcie, medal, zębatka, odznaki promocyjne), <b>Serca i natura</b> (serca, kwiaty, liście, chmury, góry, fala, płomień, tęcza, zwierzęta…), <b>Symbole i ikony</b> (dom, telefon, korona, puchar, kłódka, osoba, laptop, klucz, puzzel, mapa…), <b>Okolicznościowe</b> (prezent, balon, choinka, bombka, tort, pisanka, bałwanek…), <b>Znaki</b> (plus, minus, procent, pytajnik, ptaszek, pola wyboru…).</td></tr><tr><td><b>Strzałki i dymki</b></td><td>Strzałki w każdą stronę, na skos, zakręcone, z kolanem, łukiem, faliste, wymiany, rozgałęzione; szewrony; dymki z każdej strony, okrągłe, owalne, myśli, chmurka, krzyku, dwa dymki.</td></tr><tr><td><b>Ramki</b></td><td>Ponad 60 ramek w grupach: <b>Proste</b>, <b>Zaokrąglone</b>, <b>Podwójne i przerywane</b> (przerywana, kropkowana, kreska – kropka – to sam obrys), <b>Ozdobne</b>, <b>Z miejscem na tytuł</b>, <b>W kształcie</b> (serce, owal, koło, chmurka, ośmiokąt, łuk, gwiazda…), <b>Na zdjęcie</b> (pola w kształcie koła, serca, łuku, chmurki… – wstaw do nich obraz, a także odbitka, slajd, klatka filmu), <b>Kartki i notatki</b>, <b>Obramowania stron</b> (wstawiają się od razu na całą stronę).</td></tr><tr><td><b>Ozdobniki</b></td><td>Wstęgi i banery, narożniki (pojedyncze i komplety czterech), rozety i ornamenty (mandala, róża wiatrów, lilia, medalion…).</td></tr><tr><td><b>Linie i separatory</b></td><td>Linia ciągła, cienka, gruba, przerywana, kropkowana, kreska – kropka, podwójna i pionowa; separatory ozdobne (fala, zygzak, z kropką, kółkiem, gwiazdką, kwiatkiem, rombami, zawijasy, pętelki, listki…). Rodzaj i grubość zmienisz potem w części <b>Linia</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.2\">Linia</a>).</td></tr><tr><td><b>Etykiety i plakietki</b></td><td>Etykiety zaokrąglone, ze ściętymi rogami, owalne, z obwódką, faliste, ząbkowane, na słoik, herbowe, cenówka, metka, plakietka, pieczątka, znaczek pocztowy, tabliczka — w środek wstaw tekst.</td></tr><tr><td><b>Kalendarze</b></td><td>Kalendarz miesiąca: zwykły, z miejscem na notatki, z numerami tygodni (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.9\">Kalendarz miesiąca</a>).</td></tr><tr><td><b>Planer</b></td><td>Gotowe tabele do planerów i notesów: lista zadań, tracker nawyków, plan tygodnia, plan dnia (godziny), notatki w linie, siatka dni tygodnia, lista zakupów, cele, budżet, kontakty, plan lekcji; do tego siatki do notatek: kratka, kropki, linie (co 5 mm), papier milimetrowy, siatka izometryczna. Pola wyboru są w <b>Kształtach → Znaki</b>.</td></tr><tr><td><b>Wykresy</b></td><td>Słupkowy, poziomy, liniowy, kołowy i pierścieniowy z tabeli danych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.10\">Wykres</a>).</td></tr><tr><td><b>Kolaże zdjęć</b></td><td>Gotowe układy 2–9 pól na zdjęcia (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.11\">Kolaż zdjęć</a>).</td></tr><tr><td><b>Teksty</b></td><td>Gotowe napisy po łuku, w okręgu (pieczęć), falisty baner, flaga, wypukły tytuł (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.14\">Tekst po łuku, okręgu i ścieżce; wyginanie</a>).</td></tr><tr><td><b>Style tekstu</b></td><td>Style akapitu projektu: kliknięcie nadaje styl zaznaczonemu tekstowi, a bez zaznaczenia wstawia nowy tekst w tym stylu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>).</td></tr><tr><td><b>Marka</b></td><td>Logo z zestawu marki, <span class=\"ui\">Zastosuj markę do projektu…</span> i <span class=\"ui\">Edytuj zestaw marki…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>).</td></tr><tr><td><b>Kody</b></td><td>Kod QR i kod kreskowy EAN / ISBN (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.12\">Kod QR i kod kreskowy</a>).</td></tr></tbody></table></div><p>Kształt z biblioteki to zwykły kształt: zmienisz mu kolor, obrys i punkty (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.4\">Pióro i edycja punktów</a>), a zamknięty kształt może być ramką zdjęcia (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.7\">Obraz w kształcie</a>). Długie kategorie mają nagłówki grup (np. Podstawowe, Wielokąty); przy szukaniu nagłówków nie ma, a wyniki są ze wszystkich kategorii. Szablon z kategorii <b>Planer</b> to zwykła tabela (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9\">Tabela</a>): wpisujesz w komórki, dodajesz wiersze i kolumny, zmieniasz linie i kolory. Żeby planer powtarzał się na wielu stronach, wstaw go we wzorcu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12\">Wzorce stron</a>) albo na stronie serii (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-biblioteka-planer.png\" alt=\"Kategoria Planer w Bibliotece\" loading=\"lazy\"><figcaption>Kategoria Planer w Bibliotece</figcaption></figure><p><b>Moje elementy.</b> Logo, stopkę firmy czy ulubioną ramkę zapiszesz raz i wstawisz w każdym projekcie:</p><ol class=\"kroki\"><li>Zaznacz element albo kilka elementów (np. logo z podpisem).</li><li>Kliknij <span class=\"ui\">Zapisz w bibliotece</span> w nagłówku panelu (przy kilku zaznaczonych — w części <b>Zaznaczenie</b>) albo w <span class=\"ui\">⋯</span> przy elemencie na liście warstw.</li><li>Wpisz nazwę. Element trafi do kategorii <b>Moje elementy</b>.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-moje-elementy.png\" alt=\"Moje elementy w Bibliotece\" loading=\"lazy\"><figcaption>Moje elementy w Bibliotece</figcaption></figure><ul class=\"punkty\"><li>Elementy są na Twoim koncie, więc widać je w każdym projekcie i na każdym urządzeniu.</li><li>Wstawiony element jest kopią — usunięcie go z Biblioteki nie zmienia stron, na których już stoi.</li><li>Ołówek w rogu kafelka zmienia nazwę, kosz usuwa element z Biblioteki.</li><li>Elementów wzorca i tekstu w trakcie pisania nie zapiszesz — najpierw wyjdź z pisania.</li></ul>"},{"id":"5.9","tytul":"Kalendarz miesiąca","html":"<p>Siatka dni jednego miesiąca z nazwą miesiąca i dniami tygodnia. Niedziele i polskie święta – także ruchome: Wielkanoc, Poniedziałek Wielkanocny, Zielone Świątki, Boże Ciało – są wyróżnione kolorem.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kalendarz.png\" alt=\"Kalendarz miesiąca i jego ustawienia\" loading=\"lazy\"><figcaption>Kalendarz miesiąca i jego ustawienia</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co zmienia</th></tr></thead><tbody><tr><td><b>Miesiąc</b>, <b>Rok</b></td><td>Pokazany miesiąc.</td></tr><tr><td><b>Miesiąc z kolumny danych</b></td><td>Na każdej stronie serii inny miesiąc – z kolumny z wartościami typu „2027-03”, „marzec 2027” albo „3” (rok wtedy z <b>Rok z kolumny</b>). Tak powstaje kalendarz na 12 miesięcy z jednej strony-wzoru (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</td></tr><tr><td><b>Tydzień zaczyna się od</b></td><td>Poniedziałku albo niedzieli.</td></tr><tr><td><b>Nazwy dni</b></td><td>Pełne, skrócone albo same litery.</td></tr><tr><td><b>Dni innych miesięcy</b></td><td>Wyszarzone, jak zwykłe dni albo ukryte.</td></tr><tr><td><b>Nazwa miesiąca nad dniami</b>, <b>Numery tygodni</b></td><td>Dodatkowy wiersz i kolumna.</td></tr><tr><td><b>Miejsce na notatki</b></td><td>Data w rogu, wyższe kratki do pisania.</td></tr><tr><td><b>Polskie święta</b>, <b>Nazwa święta pod datą</b></td><td>Wyróżnienie świąt i ich nazwy w kratkach.</td></tr><tr><td><b>Święta z tabeli danych</b></td><td>Własne dni (urodziny, imieniny, terminy) z tabeli: kolumna z datą („2027-05-26”, „26.05.2027” albo „26.05” – co roku) i kolumna z nazwą.</td></tr><tr><td><b>Kolory kalendarza</b></td><td>Dni, nazwy, niedziele, soboty, święta, dni innych miesięcy.</td></tr></tbody></table></div><p>Linie, tła wierszy, czcionkę i wyrównanie zmieniasz jak w tabeli (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9.5\">Linie i tła</a>). Daty układa aplikacja – w kratkach kalendarza się nie pisze.</p>"},{"id":"5.10","tytul":"Wykres","html":"<p>Wykres rysuje liczby z tabeli danych projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a>) i zmienia się sam, gdy zmienisz dane.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wykres.png\" alt=\"Wykres słupkowy i jego ustawienia\" loading=\"lazy\"><figcaption>Wykres słupkowy i jego ustawienia</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co zmienia</th></tr></thead><tbody><tr><td><b>Rodzaj</b></td><td>Słupkowy, poziomy, liniowy, kołowy, pierścieniowy.</td></tr><tr><td><b>Tabela danych</b>, <b>Podpisy z kolumny</b>, <b>Liczby z kolumn</b></td><td>Skąd wykres bierze dane; każda zaznaczona kolumna liczb to osobna seria (osobny kolor).</td></tr><tr><td><b>Wiersze</b></td><td>Wszystkie, wybrane (od–do) albo <b>wiersz strony serii</b> – na każdej powielonej stronie wykres z jej wiersza.</td></tr><tr><td><b>Tytuł</b>, <b>Liczby przy słupkach</b>, <b>Oś</b>, <b>Linie siatki</b>, <b>Legenda</b></td><td>Co widać na wykresie.</td></tr><tr><td><b>Szerokość</b>, <b>Wysokość</b>, <b>Czcionka</b>, <b>Rozmiar pisma</b>, <b>Kolory</b></td><td>Wygląd. Uchwyty zmieniają rozmiar wykresu, nie wielkość pisma.</td></tr></tbody></table></div><p>Liczby w komórkach mogą mieć przecinek, spacje i znak %.</p>"},{"id":"5.11","tytul":"Kolaż zdjęć","html":"<p>Kolaż to gotowy układ pól na zdjęcia. Upuść zdjęcie z komputera na pole – trafi do tego pola. Możesz też kliknąć kolaż dwa razy, wybrać pole i w części <b>Obraz w kształcie</b> wstawić obraz z projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.7\">Obraz w kształcie</a>).</p><p>W panelu kolażu zmienisz <b>Układ</b> (pola przybywają albo ubywają, zdjęcia w pierwszych polach zostają), <b>Odstęp między zdjęciami</b>, <b>Zaokrąglenie rogów</b>, <b>Szerokość</b> i <b>Wysokość</b>.</p>"},{"id":"5.12","tytul":"Kod QR i kod kreskowy","html":"<p>Kod wstawisz z <span class=\"ui\">Biblioteka</span>, kategoria <b>Kody</b>. W części <b>Kod</b> panelu ustawisz resztę:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co znaczy</th></tr></thead><tbody><tr><td><b>Rodzaj</b></td><td><b>Kod QR</b> albo <b>Kod kreskowy EAN-13 / ISBN</b> (np. ISBN na okładce książki).</td></tr><tr><td><b>Co zawiera</b> (QR)</td><td><b>Adres strony</b>, <b>Tekst</b>, <b>E-mail</b>, <b>Telefon</b> albo <b>Sieć Wi-Fi</b>.</td></tr><tr><td><b>Korekcja błędów</b> (QR)</td><td>Ile kodu może być zasłonięte: od <b>Niska (7%)</b> — najmniejszy kod — do <b>Najwyższa (30%)</b>, np. pod logo.</td></tr><tr><td><b>Numer EAN albo ISBN</b></td><td>Cyfra kontrolna dopisze się sama; ISBN możesz wpisać z myślnikami.</td></tr><tr><td><b>Rozmiar</b></td><td><span class=\"ui\">Rozmiar nominalny (100%)</span> ustawia kod EAN na 37,29 × 25,93 mm.</td></tr><tr><td><b>Kolor kodu</b>, <b>Tło</b>, <b>Margines ciszy</b></td><td>Kod musi być ciemny na jasnym tle, z pustym pasem wokół.</td></tr></tbody></table></div><p>Pole z danych w treści — np. <code>{adres}</code> albo <code>{isbn}</code> — daje inny kod na każdej stronie serii (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Pola w tekście</a>).</p><p>Gdy kod będzie za mały, za jasny albo z błędną treścią, przypomni o tym panel i <b>Sprawdź przed drukiem</b>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kod.png\" alt=\"Kod QR i jego ustawienia\" loading=\"lazy\"><figcaption>Kod QR i jego ustawienia</figcaption></figure>"},{"id":"5.13","tytul":"Kopiuj wygląd (malarz formatów)","html":"<p>Wygląd jednego elementu przeniesiesz na inny jednym kliknięciem — bez przepisywania kolorów i grubości.</p><p><span class=\"ui\">Kopiuj wygląd</span> (pędzel) jest w nagłówku panelu właściwości, w <span class=\"ui\">⋯</span> przy elemencie na liście warstw, a na telefonie też pod <span class=\"ui\">⋯</span> paska wstawiania (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.4\">Pasek wstawiania</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-malarz.png\" alt=\"Kopiuj wygląd w nagłówku panelu\" loading=\"lazy\"><figcaption>Kopiuj wygląd w nagłówku panelu</figcaption></figure><ol class=\"kroki\"><li>Zaznacz element, który ma już dobry wygląd.</li><li>Kliknij <span class=\"ui\">Kopiuj wygląd</span> (<kbd>Ctrl</kbd>+<kbd>Alt</kbd>+<kbd>C</kbd>).</li><li>Kliknij element, który ma dostać ten wygląd.</li></ol><ul class=\"punkty\"><li><b>Dwa kliknięcia</b> w <span class=\"ui\">Kopiuj wygląd</span> — tryb ciągły: klikasz kolejne elementy, aż naciśniesz <kbd>Esc</kbd>.</li><li><b>Fragment tekstu:</b> w pisanym tekście zaznacz słowa i kliknij <span class=\"ui\">Kopiuj wygląd</span> — wygląd dostanie tylko zaznaczony fragment. Tak samo skopiujesz wygląd z fragmentu.</li></ul><p>Przechodzi wszystko, co dotyczy wyglądu — kolory, przejścia, obrys, czcionka, odstępy, filtry zdjęcia, krycie, cień, uszlachetnienia — a treść zostaje. Tabele, kody, wykresy i kalendarze mają własne ustawienia i wyglądu nie przejmują.</p>"}]},
  {"nr":"6","tytul":"Tekst","czesc":"Edytor","ikona":"olowek","wstep":"Ramki tekstu, ich wygląd, style i skład — od jednego napisu po tekst książki płynący przez wiele stron.","sekcje":[{"id":"6.1","tytul":"Pisanie","html":"<p>Wstaw tekst przyciskiem <span class=\"ui\">Tekst</span> (<kbd>T</kbd>) i od razu pisz. Istniejący tekst kliknij dwa razy, żeby pisać w nim; <kbd>Esc</kbd> kończy pisanie. <kbd>Enter</kbd> zaczyna nowy akapit.</p><p>Szerokość ramki zmieniasz bocznymi uchwytami — tekst układa się od nowa, litery się nie rozciągają. Wysokość ramki rośnie razem z tekstem, chyba że ustawisz stałą wysokość (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.6\">Ramka tekstu</a>).</p><figure><img src=\"img/instrukcja/wstawianie.png\" alt=\"Tekst na stronie\" loading=\"lazy\"><figcaption>Tekst na stronie</figcaption></figure>"},{"id":"6.2","tytul":"Wygląd tekstu","html":"<p>Właściwości zaznaczonego tekstu:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Styl</b></td><td>Zapisany wygląd tekstu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>).</td></tr><tr><td><b>Czcionka</b></td><td>Krój pisma. Na liście zacznij pisać nazwę, żeby ją znaleźć (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.8\">Czcionki</a>).</td></tr><tr><td><b>Rozmiar</b></td><td>W punktach (pt). Kółko z prawej to <b>kolor tekstu</b>.</td></tr><tr><td><span class=\"ui\">B</span> <span class=\"ui\">I</span> <span class=\"ui\">U</span> <span class=\"ui\">S</span></td><td>Pogrubienie, kursywa, podkreślenie, przekreślenie. Wyszarzone, gdy czcionka nie ma takiej odmiany.</td></tr><tr><td><b>Wyrównanie</b></td><td>Do lewej, do środka, do prawej, wyjustowanie.</td></tr><tr><td><b>Interlinia</b></td><td>Odstęp między wierszami; 1 to pojedynczy.</td></tr><tr><td><b>Odstęp liter</b></td><td>Rozstrzelenie liter; wartość ujemna ściska tekst.</td></tr><tr><td><b>Wielkość liter</b></td><td><span class=\"ui\">AA</span> — wszystkie wielkie, <span class=\"ui\">aa</span> — wszystkie małe, <span class=\"ui\">Aᴀ</span> — kapitaliki: to tylko wygląd, treść zostaje taka, jak ją wpisano. <span class=\"ui\">Aa</span> — „jak w zdaniu”: zmienia samą treść.</td></tr><tr><td><b>Lista</b></td><td>Punkty, kreski albo numery przed każdym akapitem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.5\">Listy</a>).</td></tr><tr><td><b>Obrys liter</b></td><td>Kolor i <b>Grubość obrysu liter</b> — kontur wokół każdej litery.</td></tr></tbody></table></div><figure><img src=\"img/instrukcja/wlasciwosci.png\" alt=\"Właściwości tekstu\" loading=\"lazy\"><figcaption>Właściwości tekstu</figcaption></figure>"},{"id":"6.3","tytul":"Fragment tekstu","html":"<p>Kliknij tekst dwa razy, zaznacz fragment i zmień go tymi samymi ustawieniami — panel pokaże „Zmieniasz tylko zaznaczony fragment”. Tak pogrubisz jedno słowo albo zmienisz kolor jednej linijki. Wygląd fragmentu z polem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Pola w tekście</a>) przechodzi na wstawioną wartość.</p>"},{"id":"6.4","tytul":"Style","html":"<p><b>Styl</b> to zapisany wygląd tekstu, np. „Tytuł”, „Podpis”, „Dymek”. Nadaj go wszystkim tekstom, które mają wyglądać tak samo.</p><ul class=\"punkty\"><li>Lista <b>Styl</b> we właściwościach nadaje styl zaznaczonemu tekstowi.</li><li><span class=\"ui\">Nowy styl</span> zapisuje wygląd zaznaczonego tekstu pod nową nazwą.</li><li>Gdy zmienisz tekst ze stylem, pojawią się <span class=\"ui\">Aktualizuj styl</span> — zmienia wszystkie teksty z tym stylem w całym projekcie — i <span class=\"ui\">Przywróć</span> — wraca do wyglądu ze stylu.</li><li>Styl zapisuje też ustawienia <b>Składu akapitu</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.9\">Skład akapitu</a>) — np. dzielenie wyrazów dla całego tekstu książki.</li></ul><p><b>Styl znakowy</b> to zapisany wygląd fragmentu tekstu, np. „Wyróżnienie” albo „Nazwa własna”.</p><ol class=\"kroki\"><li>Zaznacz fragment tekstu (kliknij tekst dwa razy i zaznacz słowa).</li><li>Ustaw jego wygląd (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.3\">Fragment tekstu</a>), potem w części <b>Styl tekstu</b> wybierz <span class=\"ui\">Nowy styl znakowy z wyglądu zaznaczenia</span>.</li><li>Inne fragmenty zaznacz i wybierz styl z listy <b>Styl znakowy</b>. Bez zaznaczenia styl dostaje cały tekst.</li></ol><p><span class=\"ui\">Aktualizuj styl znakowy</span> przenosi wygląd zaznaczenia do stylu — zmienią się wszystkie fragmenty z tym stylem w projekcie. Usunięty styl znakowy nie zmienia wyglądu fragmentów.</p>"},{"id":"6.5","tytul":"Listy","html":"<p>Lista <b>Lista</b> we właściwościach tekstu: <b>Punkty</b>, <b>Kreski</b> albo <b>Numery</b>. Znak listy stoi przed każdym akapitem, a dalsze wiersze akapitu równo pod pierwszym. W tekście płynącym przez kilka ramek numery liczą się dalej. Skróty: <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>8</kbd> (punkty) i <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>7</kbd> (numery).</p>"},{"id":"6.6","tytul":"Ramka tekstu","html":"<p>Część <b>Ramka tekstu</b> przydaje się, gdy tekst ma zająć stałe miejsce — np. teksty z danych o różnej długości (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18.6\">Tekst o różnej długości</a>):</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Stała wysokość ramki</b></td><td>Ramka nie rośnie z tekstem. Wysokość wpisujesz w mm albo zmieniasz górnym lub dolnym uchwytem.</td></tr><tr><td><b>Tekst w pionie</b></td><td>Do góry, na środku albo do dołu ramki.</td></tr><tr><td><b>Zmniejszaj tekst, gdy się nie mieści</b></td><td>Czcionka maleje, aż tekst się zmieści — nie poniżej <b>najmniejszego rozmiaru</b>.</td></tr></tbody></table></div><p>Tekst, który mimo to się nie mieści, jest ucinany na dole ramki i trafia na listę ostrzeżeń.</p><figure><img src=\"img/instrukcja/ramka-tekstu.png\" alt=\"Ramka o stałej wysokości\" loading=\"lazy\"><figcaption>Ramka o stałej wysokości</figcaption></figure>"},{"id":"6.7","tytul":"Kolumny i tekst przez kilka ramek","html":"<p>Dłuższy tekst może płynąć przez kilka ramek: to, co nie mieści się w pierwszej, przechodzi do następnej. Część <b>Przelewanie tekstu</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Przycisk</th><th>Co robi</th></tr></thead><tbody><tr><td><span class=\"ui\">Podziel na kolumny</span></td><td>Zamienia ramkę na 2, 3 albo 4 kolumny obok siebie.</td></tr><tr><td><span class=\"ui\">Dodaj ramkę z ciągiem dalszym</span></td><td>Nowa ramka obok (albo pod spodem), do której płynie reszta tekstu.</td></tr><tr><td><span class=\"ui\">Ciąg dalszy na następnej stronie</span></td><td>Ramka na następnej stronie — w razie potrzeby razem z nową stroną.</td></tr><tr><td><span class=\"ui\">Połącz ramki tekstu</span></td><td>Łączy dwie zaznaczone ramki.</td></tr><tr><td><span class=\"ui\">Rozłącz ramki</span></td><td>Każda ramka zostaje ze swoją częścią tekstu.</td></tr><tr><td><span class=\"ui\">Poprzednia ramka</span>, <span class=\"ui\">Następna ramka</span></td><td>Przechodzą do sąsiedniej ramki, także na innej stronie.</td></tr></tbody></table></div><p>Piszesz w dowolnej ramce, a tekst przelewa się na bieżąco. Wygląd tekstu (czcionka, rozmiar, lista) jest wspólny dla połączonych ramek. Fioletowa linia pokazuje, dokąd płynie tekst z zaznaczonej ramki.</p><figure><img src=\"img/instrukcja/uklad.png\" alt=\"Kolumny, listy i tabela\" loading=\"lazy\"><figcaption>Kolumny, listy i tabela</figcaption></figure>"},{"id":"6.8","tytul":"Czcionki","html":"<p>Do wyboru są 52 rodziny czcionek z polskimi znakami, które wolno używać w druku komercyjnym: bezszeryfowe do tekstu (np. Inter, Lato, Roboto), wąskie do nagłówków (Oswald, Bebas Neue), szeryfowe (Lora, Merriweather, Playfair Display, EB Garamond), odręczne i ozdobne (Caveat, Pacifico, Dancing Script) oraz maszynowe.</p><p><span class=\"ui\">⋯</span> → <span class=\"ui\">Czcionki projektu…</span> pokazuje próbki, daje pliki czcionek do pobrania (np. dla drukarni) i pozwala wgrać <b>własną czcionkę</b> (TTF, OTF, WOFF, WOFF2; każda odmiana osobno) — także z listy czcionek: <span class=\"ui\">+ Wgraj własną czcionkę…</span>. Wgrana czcionka zostaje na koncie, w „Moich czcionkach”.</p><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Do druku własną czcionkę najlepiej wgrać jako TTF albo OTF, osobny plik dla pogrubienia i kursywy. Inne pliki trafią do PDF jako krzywe — tekst będzie ostry, ale nie da się go zaznaczyć.</p><figure><img src=\"img/instrukcja/czcionki.png\" alt=\"Okno czcionek\" loading=\"lazy\"><figcaption>Okno czcionek</figcaption></figure><p>Na górze listy <b>Czcionka</b> są <b>Użyte w projekcie</b> — czcionki z tekstów wszystkich stron, wzorców i stylów, najczęstsze najpierw, z liczbą użyć (np. „Inter · 5×”). Niżej jest pełna lista.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-czcionki-uzyte.png\" alt=\"Użyte w projekcie na liście czcionek\" loading=\"lazy\"><figcaption>Użyte w projekcie na liście czcionek</figcaption></figure><p>Gdy masz zestaw marki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>), nad nimi jest grupa <b>Marka</b> — czcionka nagłówków i czcionka tekstu marki.</p>"},{"id":"6.9","tytul":"Skład akapitu","html":"<p>Zwijana część <b>Skład akapitu</b> we właściwościach tekstu decyduje o tym, jak tekst łamie się na wiersze. Te same ustawienia zapiszesz w stylu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Dziel wyrazy</b></td><td>Długie wyrazy dzielą się na końcu wiersza według polskich zasad — wyjustowany tekst nie ma wtedy dziur. Obok ustawisz najkrótszy dzielony wyraz i ile liter zostaje przed łącznikiem i po nim.</td></tr><tr><td><b>Spójniki na końcu wiersza</b></td><td>Pojedyncze <b>a, i, o, u, w, z</b> (albo też dwuliterowe: do, na, że…) przechodzą do następnego wiersza razem ze słowem, jak w polskim składzie.</td></tr><tr><td><b>Wdowy i sieroty</b></td><td>Tekst płynący przez kilka ramek (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.7\">Kolumny i tekst przez kilka ramek</a>) nie zostawia samotnego wiersza akapitu na dole ani na górze ramki.</td></tr><tr><td><b>Wyrównaj do siatki linii bazowych</b></td><td>Wiersze stają na liniach siatki sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.13\">Siatka linii bazowych</a>).</td></tr><tr><td><b>Nie opływaj innych elementów</b></td><td>Tekst leży na elementach z oblewaniem, zamiast je opływać (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.12\">Oblewanie tekstem</a>) — np. podpis na zdjęciu.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-sklad-akapitu.png\" alt=\"Skład akapitu we właściwościach tekstu\" loading=\"lazy\"><figcaption>Skład akapitu we właściwościach tekstu</figcaption></figure>"},{"id":"6.10","tytul":"Inicjał","html":"<p>Inicjał to powiększona pierwsza litera akapitu, na kilka wierszy. W części <b>Skład akapitu</b> wybierz <b>Inicjał</b>: <b>na 2 wiersze</b> … <b>na 5 wierszy</b>. Litera rośnie od górnej krawędzi pierwszego wiersza do linii bazowej ostatniego, a tekst ją opływa. <b>Czcionka inicjału</b> i <b>Kolor inicjału</b> mogą być inne niż w tekście.</p><p>Inicjał dostaje pierwszy akapit tekstu. W tekście płynącym przez kilka ramek — tylko w pierwszej ramce.</p><figure><img src=\"img/instrukcja/sklad.png\" alt=\"Inicjał, dzielenie wyrazów, tabulatory z kropkami i tekst opływający koło\" loading=\"lazy\"><figcaption>Inicjał, dzielenie wyrazów, tabulatory z kropkami i tekst opływający koło</figcaption></figure>"},{"id":"6.11","tytul":"Tabulatory","html":"<p>Klawisz <kbd>Tab</kbd> w pisanym tekście wstawia tabulator: tekst za nim przeskakuje do najbliższej pozycji. Bez ustawionych pozycji tabulatory stoją co 12,5 mm.</p><p>W części <b>Skład akapitu</b> <span class=\"ui\">Dodaj tabulator</span> dodaje pozycję. Każda ma:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Pole</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Tabulator N</b></td><td>Pozycja w mm od lewej krawędzi ramki.</td></tr><tr><td><b>Wyrównanie</b></td><td><b>do lewej</b>, <b>do środka</b>, <b>do prawej</b> albo <b>do przecinka</b> (liczby z przecinkiem jedna pod drugą).</td></tr><tr><td><b>Wypełnienie</b></td><td>Pusto, kropki, kreski albo linia przed tekstem — np. spis treści „Rozdział 1 . . . . . 12”.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabulatory.png\" alt=\"Tabulator do prawej z kropkami\" loading=\"lazy\"><figcaption>Tabulator do prawej z kropkami</figcaption></figure>"},{"id":"6.12","tytul":"Oblewanie tekstem","html":"<p>Zdjęcie, kształt albo grupa może odpychać tekst. Zaznacz element i w części <b>Inne</b> wybierz <b>Oblewanie tekstem</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Wartość</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>tekst opływa ramkę elementu</b></td><td>Wiersze kończą się przed prostokątem elementu (albo zaczynają za nim).</td></tr><tr><td><b>tekst opływa kształt</b></td><td>Dla elipsy, wielokąta i kształtu z pióra — wiersze idą wzdłuż jego brzegu.</td></tr><tr><td><b>tekst przeskakuje pod element</b></td><td>Obok elementu nie ma tekstu, ciąg dalszy jest pod nim.</td></tr></tbody></table></div><p><b>Odstęp tekstu od elementu</b> to wolne miejsce wokół elementu (domyślnie 2 mm). Oblewanie działa na wszystkie teksty na stronie — także w trakcie przesuwania elementu. Tekst wybiera tę stronę elementu, po której ma więcej miejsca.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-oblewanie.png\" alt=\"Oblewanie tekstem w części Inne\" loading=\"lazy\"><figcaption>Oblewanie tekstem w części Inne</figcaption></figure>"},{"id":"6.13","tytul":"Siatka linii bazowych","html":"<p>Siatka linii bazowych ustawia wiersze wszystkich kolumn i stron na tej samej wysokości — jak w książkach, w których wiersze z obu stron kartki pokrywają się pod światło.</p><ol class=\"kroki\"><li>W ustawieniach sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>) włącz <b>Siatka linii bazowych w tej sekcji</b>: <b>Odstęp</b> (zwykle interlinia tekstu podstawowego) i <b>Pierwsza linia</b> (mm od górnej krawędzi strony, zwykle górny margines).</li><li>W menu widoku (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>) <b>Siatka linii bazowych</b> pokazuje te linie na stronie.</li><li>Tekstom, które mają stać na siatce, włącz <b>Wyrównaj do siatki linii bazowych</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.9\">Skład akapitu</a>) — najlepiej w stylu tekstu podstawowego.</li></ol>"},{"id":"6.14","tytul":"Tekst po łuku, okręgu i ścieżce; wyginanie","html":"<p>Zaznacz tekst i w części <b>Kształt tekstu</b> panelu wybierz <b>Kształt</b>. Gotowe przykłady znajdziesz też w <span class=\"ui\">Biblioteka</span>, w kategorii <b>Teksty</b>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-ksztalt-tekstu.png\" alt=\"Tekst po łuku, w okręgu i wygięty\" loading=\"lazy\"><figcaption>Tekst po łuku, w okręgu i wygięty</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Kształt</th><th>Co robi i co ustawisz</th></tr></thead><tbody><tr><td><b>Łuk</b></td><td>Napis po łuku. <b>Zgięcie</b> w %: dodatnie – łuk w górę, ujemne – w dół.</td></tr><tr><td><b>Okrąg</b>, <b>Elipsa</b></td><td>Napis dookoła, np. pieczęć: promień, początek, litery na zewnątrz albo do środka.</td></tr><tr><td><b>Po ścieżce</b></td><td>Napis po linii dowolnego kształtu ze strony (narysowanego piórem albo z Biblioteki) — wybierz go w <b>Linia z kształtu na stronie</b>.</td></tr><tr><td><b>Wygięcie</b></td><td>Litery wygięte jak łuk, wypukłość, fala, flaga albo zwężenie; <b>Siła wygięcia</b> w %.</td></tr></tbody></table></div><ul class=\"punkty\"><li>Przy łuku i wygięciach uchwyt ◆ pod tekstem zgina tekst mocniej albo słabiej.</li><li>Kliknij tekst dwa razy, żeby go poprawić — w trakcie pisania stoi prosto.</li><li>Tekst po kształcie jest jednym wierszem; czcionka, kolor, style i pola <code>{…}</code> działają jak zwykle.</li><li><b>Prosto</b> przywraca zwykły tekst.</li></ul>"},{"id":"6.15","tytul":"Znajdź i zamień","html":"<p>Lupa na górnym pasku albo <span class=\"ui\">⋯</span> → <span class=\"ui\">Znajdź i zamień…</span> (<kbd>Ctrl</kbd>+<kbd>F</kbd>; <kbd>Ctrl</kbd>+<kbd>H</kbd> — od razu z polem zamiany).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-znajdz.png\" alt=\"Znajdź i zamień obok strony\" loading=\"lazy\"><figcaption>Znajdź i zamień obok strony</figcaption></figure><ol class=\"kroki\"><li>Wpisz szukany tekst. Lista pokazuje każde trafienie: stronę albo wzorzec i kawałek tekstu wokół.</li><li>Kliknij trafienie (albo <kbd>Enter</kbd> w polu, <kbd>Shift</kbd>+<kbd>Enter</kbd> — wstecz) — edytor otworzy tę stronę i zaznaczy znaleziony fragment.</li><li>Żeby zamienić, wpisz nowy tekst w drugim polu i kliknij <span class=\"ui\">Zamień</span> (wybrane trafienie) albo <span class=\"ui\">Zamień wszystkie</span>.</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Opcja</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Wielkość liter</b></td><td>„Kalendarz” nie znajdzie „kalendarz”.</td></tr><tr><td><b>Całe słowa</b></td><td>„kot” nie znajdzie „kotka”.</td></tr><tr><td><b>Także w danych</b></td><td>Szuka też w komórkach tabel danych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a>).</td></tr><tr><td><b>W nazwach stylów</b></td><td>Szuka też w nazwach stylów akapitu i znakowych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>).</td></tr></tbody></table></div><ul class=\"punkty\"><li>Szukanie obejmuje wszystkie strony i wzorce, także teksty w grupach.</li><li>Pola w klamrach, np. <code>{miesiac}</code>, zostają nietknięte — chyba że wpiszesz klamrę w szukanym tekście.</li><li>Wygląd fragmentów (np. pogrubione słowo) zostaje na swoim miejscu po zamianie.</li><li><span class=\"ui\">Zamień wszystkie</span> cofniesz jednym <span class=\"ui\">Cofnij</span>.</li></ul>"},{"id":"6.16","tytul":"Sprawdzanie pisowni","html":"<p>Słowa spoza słownika polskiego są podkreślone falistą czerwoną linią — tylko w edytorze, nigdy w PDF.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pisownia-dymek.png\" alt=\"Podpowiedzi przy podkreślonym słowie\" loading=\"lazy\"><figcaption>Podpowiedzi przy podkreślonym słowie</figcaption></figure><ol class=\"kroki\"><li>Kliknij tekst dwa razy i kliknij (na telefonie stuknij) podkreślone słowo — albo kliknij je prawym przyciskiem myszy. Obok słowa pojawi się dymek z podpowiedziami i <span class=\"ui\">Dodaj do słownika</span>.</li><li>Kliknij podpowiedź (np. „wcześniej”) — słowo zmieni się w tym miejscu.</li><li>Nazwę własną, której słownik nie zna (np. nazwę firmy), dodaj przyciskiem <span class=\"ui\">Dodaj do słownika</span>. Twój słownik jest na koncie, więc działa w każdym projekcie.</li></ol><p>Wszystkie podejrzane słowa zaznaczonego tekstu widać też w panelu, w części <b>Pisownia</b> — tam podpowiedź zmienia słowo we wszystkich miejscach tego tekstu.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pisownia.png\" alt=\"Część „Pisownia” w panelu tekstu\" loading=\"lazy\"><figcaption>Część „Pisownia” w panelu tekstu</figcaption></figure><ul class=\"punkty\"><li>Pomijane są pola <code>{…}</code>, liczby, słowa z cyframi, adresy stron i e-maile.</li><li>Wyłączysz sprawdzanie w menu widoku: <b>Sprawdzaj pisownię</b>.</li></ul>"}]},
  {"nr":"7","tytul":"Kształty, linie i kolory","czesc":"Edytor","ikona":"olowek","wstep":"Kształty, linie, rysowanie i kolory: wypełnienia, przejścia i obrysy.","sekcje":[{"id":"7.1","tytul":"Prostokąt, elipsa i wielokąt","html":"<p><span class=\"ui\">Prostokąt</span>, <span class=\"ui\">Elipsa</span> i <span class=\"ui\">Wielokąt</span> wstawiają kształty z wypełnieniem i obrysem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"7.5\">Wypełnienie</a>, <a href=\"#\" data-cel=\"7.6\">Obrys</a>). <span class=\"ui\">Wielokąt</span> najpierw pokazuje wybór: trójkąt, romb, pięcio-, sześcio- i ośmiokąt albo gwiazda o 4, 5, 6, 8 lub 12 ramionach. Klawisz <kbd>P</kbd> wstawia od razu trójkąt. Część <b>Kształt</b>:</p><ul class=\"punkty\"><li>prostokąt — <b>Zaokrąglenie</b> narożników w mm,</li><li>wielokąt — te same gotowe kształty co przy wstawianiu (trójkąt … gwiazda 12), <b>Liczba boków</b> (3–24) i przełącznik <b>Gwiazda</b>; zmiana zachowuje miejsce i wielkość.</li></ul>"},{"id":"7.2","tytul":"Linia","html":"<p><span class=\"ui\">Linia</span> wstawia odcinek. Część <b>Linia</b>: <b>Kolor</b>, <b>Grubość</b> w mm i <b>Rodzaj</b> — ciągła, przerywana, kropkowana albo kreska – kropka (kreski rosną razem z grubością). Z <kbd>Shift</kbd> linia jest pozioma, pionowa albo pod kątem 45°. Linia rysowana odręcznie i kształt z pióra mają tę samą część, a zamknięty kształt z pióra — także <b>Wypełnienie</b>. Gotowe linie (cienka, gruba, przerywana, podwójna, pionowa, ozdobne) są w Bibliotece, w kategorii <b>Linie i separatory</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>).</p>"},{"id":"7.3","tytul":"Rysowanie odręczne","html":"<p><span class=\"ui\">Rysuj</span> (<kbd>B</kbd>): przeciągaj po stronie jak ołówkiem — drżenie ręki jest wygładzane. Każde pociągnięcie to osobny element. Tryb zostaje włączony, więc narysujesz kilka kresek.</p><p>Kolor i grubość następnych linii ustawisz we właściwościach, w części <b>Pędzel</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.5\">Właściwości i warstwy</a>). <span class=\"ui\">Zakończ rysowanie</span> albo <kbd>Esc</kbd> kończy rysowanie.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-rysowanie.png\" alt=\"Rysowanie: kolor i grubość pędzla\" loading=\"lazy\"><figcaption>Rysowanie: kolor i grubość pędzla</figcaption></figure>"},{"id":"7.4","tytul":"Pióro i edycja punktów","html":"<p><span class=\"ui\">Pióro</span> (<kbd>N</kbd>) tworzy kształt z punktów:</p><ul class=\"punkty\"><li>kliknięcie stawia punkt narożny, kliknięcie z przeciągnięciem — punkt z łukiem,</li><li>kliknięcie w pierwszy punkt zamyka kształt,</li><li><kbd>Enter</kbd> albo podwójne kliknięcie kończy kształt otwarty,</li><li><kbd>Backspace</kbd> cofa ostatni punkt, <kbd>Esc</kbd> porzuca zaczęty kształt.</li></ul><p><b>Edycja punktów:</b> kliknij kształt dwa razy albo wybierz <span class=\"ui\">Edytuj punkty</span>. Przeciągaj punkty, a uchwytami zaznaczonego punktu zmieniaj łuki. Podwójne kliknięcie w linię dodaje punkt, <kbd>Delete</kbd> usuwa zaznaczony. <kbd>Enter</kbd> zatwierdza, <kbd>Esc</kbd> przywraca kształt sprzed edycji. Tak samo zmienisz linię rysowaną odręcznie.</p><figure><img src=\"img/instrukcja/pioro.png\" alt=\"Edycja punktów\" loading=\"lazy\"><figcaption>Edycja punktów</figcaption></figure>"},{"id":"7.5","tytul":"Wypełnienie","html":"<p>Część <b>Wypełnienie i obrys</b>, lista <b>Wypełnienie</b>:</p><p><b>Brak</b>, <b>Jeden kolor</b>, <b>Przejście liniowe</b> (w jednym kierunku, pod zadanym <b>Kątem</b>) albo <b>Przejście kołowe</b> (od środka na zewnątrz, zasięg — <b>Promień</b>).</p><p>Pasek przejścia pokazuje kolory. <span class=\"ui\">Dodaj kolor</span> dokłada kolejny; kliknięcie koloru na pasku pozwala zmienić go i jego położenie w %, <span class=\"ui\">Usuń ten kolor z przejścia</span> go usuwa.</p><p>Każdy kolor przejścia ma pole <b>Krycie</b> — np. kolor przechodzący w przezroczystość nad zdjęciem.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-krycie-przejscia.png\" alt=\"Krycie koloru w przejściu\" loading=\"lazy\"><figcaption>Krycie koloru w przejściu</figcaption></figure>"},{"id":"7.6","tytul":"Obrys","html":"<p>Kolor obrysu i <b>Grubość obrysu</b> w mm. Grubość nie zmienia się, gdy powiększasz kształt. Przy włączonym obrysie są też <b>Krycie obrysu</b> (półprzezroczysta ramka) i <b>Rodzaj linii</b> — ciągła, przerywana, kropkowana albo kreska – kropka; kreski rosną razem z grubością.</p><p>Kształt (także z obrazem w środku) może mieć <b>Miękkie krawędzie</b> — tak jak zdjęcie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.10\">Obramowanie i miękkie krawędzie</a>).</p>"},{"id":"7.7","tytul":"Wybór koloru","html":"<p>Kliknięcie kółka koloru otwiera okno koloru: próbnik, <b>Kod koloru</b> (np. <code>#2f5bd3</code>), gotowe i ostatnio używane kolory oraz <b>Użyte w projekcie</b> — kolory ze wszystkich stron, wzorców i stylów, najczęstsze najpierw (przy kolorze dodatkowym widać jego nazwę, np. „PANTONE 186 C”, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.1\">Kolory dodatkowe</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolory-uzyte.png\" alt=\"Użyte w projekcie w oknie koloru\" loading=\"lazy\"><figcaption>Użyte w projekcie w oknie koloru</figcaption></figure><p>Gdy masz zestaw marki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>), nad „Użytymi w projekcie” jest część <b>Marka</b> — kolory marki z nazwami (nazwę i kod widać po najechaniu).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-marka-kolor.png\" alt=\"Kolory marki w oknie koloru\" loading=\"lazy\"><figcaption>Kolory marki w oknie koloru</figcaption></figure>"}]},
  {"nr":"8","tytul":"Obrazy","czesc":"Edytor","ikona":"olowek","wstep":"Zdjęcia i grafiki: wstawianie, kadrowanie, ramki, filtry i usuwanie tła.","sekcje":[{"id":"8.1","tytul":"Wstawianie obrazu","html":"<p><span class=\"ui\">Obraz</span> pyta, skąd wziąć obraz:</p><ul class=\"punkty\"><li><span class=\"ui\">Wgraj z urządzenia</span> — wybór pliku PNG, JPEG, WebP, GIF albo SVG,</li><li><span class=\"ui\">Wybierz z obrazów projektu</span> — obraz, który już jest w projekcie, bez drugiej kopii.</li></ul><p>W projekcie bez obrazów od razu otwiera się wybór pliku. Obraz wstawisz też, przeciągając plik na stronę albo wklejając ze schowka (<kbd>Ctrl</kbd>+<kbd>V</kbd>) — np. zrzut ekranu albo obraz skopiowany ze strony internetowej.</p>"},{"id":"8.2","tytul":"Kadrowanie","html":"<p>Kliknij obraz dwa razy albo wybierz <span class=\"ui\">Kadruj przeciąganiem</span>: przesuwasz zdjęcie w ramce i zmieniasz jej brzegi. <kbd>Enter</kbd> zatwierdza, <kbd>Esc</kbd> anuluje. To samo liczbami: <b>Przycięcie (% oryginału)</b> — <b>Z góry</b>, <b>Z dołu</b>, <b>Z lewej</b>, <b>Z prawej</b>.</p>"},{"id":"8.3","tytul":"Właściwości obrazu","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><span class=\"ui\">Podmień zdjęcie</span></td><td>Inne zdjęcie w tej samej ramce (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.4\">Podmiana zdjęcia</a>).</td></tr><tr><td><span class=\"ui\">Obrazy projektu…</span></td><td>Okno wszystkich obrazów (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Okno Obrazy projektu</a>).</td></tr><tr><td>Opis pod nagłówkiem</td><td>Wymiary oryginału w pikselach i rozdzielczość w tym rozmiarze (dpi). Do druku — co najmniej 300 dpi; przy mniejszej opis zmienia kolor.</td></tr><tr><td><b>Obramowanie</b></td><td>Ramka wokół zdjęcia: kolor, <b>Grubość</b>, <b>Krycie obrysu</b>, <b>Rodzaj linii</b> (ciągła, przerywana, kropkowana, kreska – kropka) i <b>Zaokrąglenie narożników</b> w mm — zaokrąglenie przycina też samo zdjęcie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.10\">Obramowanie i miękkie krawędzie</a>).</td></tr><tr><td><b>Odbij lustrzanie w poziomie</b></td><td>Odwraca obraz.</td></tr><tr><td><b>Obraz z danych</b></td><td>Inny obraz na każdej powielonej stronie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18.5\">Obraz z danych</a>).</td></tr></tbody></table></div>"},{"id":"8.4","tytul":"Podmiana zdjęcia","html":"<p><span class=\"ui\">Podmień zdjęcie</span> wstawia inny plik w tę samą ramkę: rozmiar, miejsce, obrót, obrys i cień zostają, a zdjęcie o innych proporcjach jest przycięte do ramki.</p>"},{"id":"8.5","tytul":"Okno Obrazy projektu","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Obrazy projektu…</span> pokazuje wszystkie obrazy projektu: miniaturę, pełną nazwę pliku, wymiary, rozmiar i miejsca użycia (numery stron, wzorce, tabele danych).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Przycisk</th><th>Co robi</th></tr></thead><tbody><tr><td><span class=\"ui\">Wgraj obrazy…</span></td><td>Dodaje pliki z urządzenia, kilka naraz — także archiwum ZIP z obrazami.</td></tr><tr><td><span class=\"ui\">Kopiuj nazwę</span></td><td>Kopiuje nazwę pliku, np. do tabeli danych.</td></tr><tr><td><span class=\"ui\">Zmień nazwę</span></td><td>Nowa nazwa; komórki tabel z tą nazwą zmieniają się razem z nią.</td></tr><tr><td><span class=\"ui\">Podmień plik</span></td><td>Nowy plik w miejsce starego — wszędzie, gdzie obraz był użyty.</td></tr><tr><td><span class=\"ui\">Usuń</span></td><td>Usuwa zaznaczone obrazy. Użytych obrazów aplikacja nie usunie — powie, gdzie są.</td></tr><tr><td><span class=\"ui\">Usuń nieużywane</span></td><td>Usuwa obrazy, których nic nie używa.</td></tr></tbody></table></div><p>Kliknięcie obrazu go zaznacza; <kbd>Ctrl</kbd> dodaje kolejne, <kbd>Shift</kbd> — cały zakres. Ten sam plik wgrany drugi raz nie tworzy kopii. Inny plik o tej samej nazwie — aplikacja pokaże oba obrazy i zapyta: <span class=\"ui\">Zastąp</span> albo <span class=\"ui\">Zachowaj oba</span>.</p><p class=\"ramka-instrukcji uwaga\"><b>Uwaga.</b> Usuniętego obrazu nie przywróci <span class=\"ui\">Cofnij</span>.</p><figure><img src=\"img/instrukcja/obrazy-projektu.png\" alt=\"Obrazy projektu\" loading=\"lazy\"><figcaption>Obrazy projektu</figcaption></figure>"},{"id":"8.6","tytul":"Rysunki SVG","html":"<p>Plik SVG wstawia się jako obraz: wygląda wiernie i zostaje ostry w każdym powiększeniu, ale nie zmienisz w nim kolorów ani napisów.</p><p><span class=\"ui\">Rozłóż rysunek na elementy</span> (we właściwościach obrazu) zamienia go na stronie w <b>grupę zwykłych kształtów i napisów</b> w tym samym miejscu. Kształtom zmienisz kolor i punkty, napisy poprawisz jak każdy tekst. Plik SVG nie zmienia się i zostaje w oknie obrazów projektu.</p><p>Nic przy tym nie znika:</p><ul class=\"punkty\"><li><b>przycięcie</b> i <b>przejścia kolorów</b> zostają kształtami,</li><li><b>prosta maska</b> (biały kształt) staje się przycięciem, a <b>wzór</b> (np. kropki, kratka) — powtórzonymi kształtami przyciętymi do swojej figury,</li><li>fragmenty z <b>efektami, których edytor nie ma</b> (rozmycie, cień z filtra, maska z przejściem, mieszanie kolorów, groty linii, tekst po ścieżce) zostają <b>obrazem</b> w tym samym miejscu, w rozdzielczości do druku. Po rozłożeniu aplikacja powie, ile ich jest; reszta rysunku jest edytowalna.</li></ul><p><kbd>Ctrl</kbd>+<kbd>Z</kbd> przywraca cały rysunek.</p><figure><img src=\"img/instrukcja/rysunek-svg.png\" alt=\"Rysunek SVG przed i po rozłożeniu\" loading=\"lazy\"><figcaption>Rysunek SVG przed i po rozłożeniu</figcaption></figure>"},{"id":"8.7","tytul":"Obraz w kształcie","html":"<p>Każdy kształt może być ramką obrazu: prostokąt, elipsa, wielokąt, gwiazda i zamknięty kształt z pióra.</p><ol class=\"kroki\"><li>Zaznacz kształt i w części <b>Obraz w kształcie</b> wybierz <span class=\"ui\">Wstaw obraz do kształtu</span> — albo upuść plik obrazu prosto na kształt.</li><li>Obraz wypełnia kształt i jest przycięty do jego brzegów.</li><li>Kliknij kształt dwa razy, żeby przesunąć obraz i powiększyć go narożnikami; <kbd>Enter</kbd> zatwierdza, <kbd>Esc</kbd> anuluje. Na telefonie użyj pól <b>Powiększenie</b> i <b>Przesunięcie</b>.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-obraz-w-ksztalcie.png\" alt=\"Kształt z obrazem i część „Obraz w kształcie”\" loading=\"lazy\"><figcaption>Kształt z obrazem i część „Obraz w kształcie”</figcaption></figure><figure><img src=\"img/instrukcja/obraz-w-ksztalcie-kadr.png\" alt=\"Kadrowanie obrazu w kształcie: cały obraz półprzezroczyście, kształt jako obrys\" loading=\"lazy\"><figcaption>Kadrowanie obrazu w kształcie: cały obraz półprzezroczyście, kształt jako obrys</figcaption></figure><p>Kształt zmieniasz jak zwykle — rozmiar, punkty, obrys, cień — a obraz idzie za nim. <span class=\"ui\">Wyjmij obraz</span> zostawia zwykły obraz w miejscu kształtu. Na stronach z danymi wybierz <b>Obraz z kolumny</b>: na każdej stronie pojawi się inny obraz.</p><p>Zdjęcie zamienisz w kształt jednym kliknięciem: w części <b>Kadrowanie</b> <span class=\"ui\">Zaokrąglone rogi</span> albo <span class=\"ui\">Koło</span>. Zaokrąglenie zmienisz potem w części <b>Wypełnienie i obrys</b>.</p>"},{"id":"8.8","tytul":"Usuwanie tła","html":"<p>Zaznacz zdjęcie (albo kształt z obrazem) i wybierz <span class=\"ui\">Usuń tło…</span>.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Narzędzie</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Różdżka</b></td><td>Kliknij tło — znika kolor podobny do klikniętego. <b>Tolerancja</b> mówi, jak podobny.</td></tr><tr><td><b>Tylko połączone z klikniętym miejscem</b></td><td>Nie rusza takich samych kolorów w środku zdjęcia.</td></tr><tr><td><b>Usuń</b> / <b>Przywróć</b></td><td>Pędzle do poprawek brzegów, myszą albo palcem.</td></tr><tr><td><b>Wygładzenie krawędzi</b></td><td>Zmiękcza brzeg.</td></tr></tbody></table></div><p><span class=\"ui\">Zapisz jako nowy obraz</span> dodaje nowy plik do obrazów projektu i wstawia go w miejsce starego; oryginał zostaje.</p><figure><img src=\"img/instrukcja/usun-tlo.png\" alt=\"Okno „Usuń tło”\" loading=\"lazy\"><figcaption>Okno „Usuń tło”</figcaption></figure>"},{"id":"8.9","tytul":"Filtry","html":"<p>W części <b>Filtry</b> zdjęcia albo obrazu w kształcie ustawisz <b>jasność</b>, <b>kontrast</b>, <b>nasycenie</b> i <b>rozmycie</b> oraz włączysz <b>odcień szarości</b> albo <b>sepię</b>. Plik się nie zmienia; <span class=\"ui\">Bez filtrów</span> wraca do oryginału.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-filtry.png\" alt=\"Filtry obrazu\" loading=\"lazy\"><figcaption>Filtry obrazu</figcaption></figure>"},{"id":"8.10","tytul":"Obramowanie i miękkie krawędzie","html":"<p>Część <b>Obramowanie</b> zdjęcia: kolor (pole <b>brak</b> wyłącza ramkę), <b>Grubość</b> w mm, <b>Krycie obrysu</b>, <b>Rodzaj linii</b> i <b>Zaokrąglenie narożników</b> w mm. Zaokrąglenie przycina samo zdjęcie, a obramowanie idzie po zaokrągleniu. Grubość i zaokrąglenie zostają takie same, gdy zmieniasz rozmiar zdjęcia.</p><p>Część <b>Miękkie krawędzie</b> (zdjęcie i kształty): <b>Szerokość przejścia</b> w mm — tyle od brzegu zdjęcie płynnie znika w przezroczystość; 0 to ostry brzeg. <b>Rodzaj</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Rodzaj</th><th>Wygląd</th></tr></thead><tbody><tr><td><b>równo wzdłuż brzegu</b></td><td>Przejście biegnie wzdłuż brzegu — prostokąta, kształtu albo przezroczystych miejsc obrazu PNG.</td></tr><tr><td><b>owalna winieta</b></td><td>Widać owal w środku, który miękko znika ku brzegom i narożnikom.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-obramowanie.png\" alt=\"Obramowanie z zaokrągleniem i owalna winieta\" loading=\"lazy\"><figcaption>Obramowanie z zaokrągleniem i owalna winieta</figcaption></figure><p>Obramowanie, zaokrąglenie i miękkie krawędzie przenosi też <span class=\"ui\">Kopiuj wygląd</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Kopiuj wygląd (malarz formatów)</a>).</p>"}]},
  {"nr":"9","tytul":"Tabela","czesc":"Edytor","ikona":"olowek","wstep":"Tabela na stronie — do cenników, planów, list. To co innego niż tabela danych do powielania stron (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a>).","sekcje":[{"id":"9.1","tytul":"Wstawianie tabeli","html":"<p><span class=\"ui\">Tabela</span> otwiera okno <b>Wstaw tabelę</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Pole</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Wiersze</b></td><td>Liczba wierszy (1–60).</td></tr><tr><td><b>Kolumny</b></td><td>Liczba kolumn (1–12).</td></tr><tr><td><b>Najmniejsza wysokość wiersza (mm)</b></td><td>Wiersz nie będzie niższy; rośnie, gdy tekst się nie mieści.</td></tr><tr><td><b>Pierwszy wiersz to nagłówek</b></td><td>Pierwszy wiersz pogrubiony, z grubszą linią pod spodem.</td></tr></tbody></table></div><p>Tabelę przesuwasz, powiększasz i obracasz w całości, jak każdy element. <b>Pojedyncze kliknięcie komórki</b> zaznaczonej tabeli wybiera tę komórkę (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9.3\">Wiersze, kolumny i ich rozmiar</a>), <b>dwukrotne</b> — zaczyna w niej pisanie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"9.2\">Pisanie w komórkach</a>).</p><figure><img src=\"img/instrukcja/tabela.png\" alt=\"Tabela\" loading=\"lazy\"><figcaption>Tabela</figcaption></figure>"},{"id":"9.2","tytul":"Pisanie w komórkach","html":"<p>Kliknij komórkę dwa razy, żeby w niej pisać. <kbd>Tab</kbd> przechodzi do następnej komórki, <kbd>Shift</kbd>+<kbd>Tab</kbd> do poprzedniej; <kbd>Tab</kbd> w ostatniej komórce dodaje wiersz. Komórka to zwykły tekst: pogrubisz w niej fragment, zmienisz czcionkę, wstawisz pole z danych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Pola w tekście</a>). Wiersz rośnie razem z tekstem — także na stronach powielonych z danych.</p>"},{"id":"9.3","tytul":"Wiersze, kolumny i ich rozmiar","html":"<p><b>Cała tabela</b>: <b>Wiersze</b> i <b>Kolumny</b> <span class=\"ui\">−</span> <span class=\"ui\">+</span> (ostatni wiersz i kolumna), <b>Pierwszy wiersz to nagłówek</b>, <b>Szerokość tabeli</b> w mm (kolumny zmieniają się proporcjonalnie), <b>Wysokość wierszy</b> (najmniejsza — wiersz rośnie sam z tekstem) i <span class=\"ui\">Wyrównaj szerokości kolumn</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabela-cala.png\" alt=\"Cała tabela\" loading=\"lazy\"><figcaption>Cała tabela</figcaption></figure><p><b>Kolumna i wiersz</b> — kliknij raz komórkę zaznaczonej tabeli (albo pisz w niej): szerokość tej kolumny i wysokość tego wiersza w mm, <span class=\"ui\">Kolumna przed</span>, <span class=\"ui\">Kolumna po</span>, <span class=\"ui\">Wiersz nad</span>, <span class=\"ui\">Wiersz pod</span> i usuwanie.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-tabela-komorka.png\" alt=\"Kolumna i wiersz wybranej komórki\" loading=\"lazy\"><figcaption>Kolumna i wiersz wybranej komórki</figcaption></figure><p><b>Szerokości wszystkich kolumn</b> (część zwinięta) — szerokość każdej kolumny w mm, jedna pod drugą.</p><p>Granicę kolumn przesuniesz też myszą: przy zaznaczonej tabeli nad granicami kolumn są niebieskie znaczniki. Kolumna obok zwęża się o tyle samo, a ostatni znacznik zmienia szerokość całej tabeli.</p>"},{"id":"9.4","tytul":"Scalanie komórek","html":"<p>W trakcie pisania w komórce: <span class=\"ui\">Scal z komórką po prawej</span> i <span class=\"ui\">Scal z komórką poniżej</span>. Klikając kilka razy, zrobisz komórkę na kilka kolumn albo wierszy. <span class=\"ui\">Rozdziel komórkę</span> wraca do pojedynczych komórek.</p>"},{"id":"9.5","tytul":"Linie i tła","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Część</th><th>Co ustawisz</th></tr></thead><tbody><tr><td><b>Linie tabeli</b></td><td>Kolor i grubość linii (0 — bez linii).</td></tr><tr><td><b>Linie wiersza, kolumny, tabeli</b></td><td>Które linie — zewnętrzne, poziome, pionowe — dla tego wiersza, tej kolumny albo całej tabeli.</td></tr><tr><td><b>Linie tej komórki</b></td><td>Każda krawędź komórki osobno: jak w tabeli, inna albo bez linii.</td></tr><tr><td><b>Tło wierszy</b></td><td>Kolor wiersza nagłówka i co drugiego wiersza (tabela w paski).</td></tr><tr><td><b>Tekst w komórkach</b></td><td>Czcionka, rozmiar, kolor, wyrównanie i odstęp od brzegu komórki.</td></tr></tbody></table></div>"}]},
  {"nr":"10","tytul":"Warstwy","czesc":"Edytor","ikona":"olowek","wstep":"Lista wszystkich elementów strony — do zaznaczania, ukrywania i zmiany kolejności.","sekcje":[{"id":"10.1","tytul":"Panel Warstwy","html":"<p>Panel <b>Warstwy</b> pokazuje wszystkie elementy otwartej strony, od leżącego na wierzchu do leżącego na spodzie. Na komputerze stoi pod właściwościami, na telefonie otwiera go przycisk <span class=\"ui\">Warstwy</span> na dole ekranu.</p><figure><img src=\"img/instrukcja/warstwy.png\" alt=\"Warstwy\" loading=\"lazy\"><figcaption>Warstwy</figcaption></figure>"},{"id":"10.2","tytul":"Wiersz warstwy","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>W wierszu</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Nazwa</b></td><td>Kliknięcie zaznacza element, podwójne kliknięcie zmienia nazwę.</td></tr><tr><td><b>Uchwyt ⋮⋮</b></td><td>Przeciągnij wiersz, żeby zmienić kolejność — myszą albo palcem.</td></tr><tr><td><b>Oko</b></td><td>Ukrywa element. Ukryty element nie jest drukowany.</td></tr><tr><td><b>Kłódka</b></td><td>Blokuje położenie i rozmiar.</td></tr><tr><td><span class=\"ui\">⋯</span></td><td><span class=\"ui\">Na wierzch</span>, <span class=\"ui\">Wyżej</span>, <span class=\"ui\">Niżej</span>, <span class=\"ui\">Na spód</span>, <span class=\"ui\">Zmień nazwę</span>, <span class=\"ui\">Kopiuj wygląd</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.13\">Kopiuj wygląd (malarz formatów)</a>), <span class=\"ui\">Zapisz w bibliotece</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>).</td></tr></tbody></table></div><p>Zaznaczenie na liście przydaje się, gdy element leży pod innym i trudno w niego trafić na stronie.</p>"},{"id":"10.3","tytul":"Grupy, tabele i wzorce na liście","html":"<ul class=\"punkty\"><li>Trójkąt przy grupie albo tabeli rozwija jej zawartość. Kliknięcie elementu grupy otwiera grupę z tym elementem zaznaczonym (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.5\">Grupy</a>); kliknięcie komórki tabeli zaczyna w niej pisanie.</li><li>Na górze i na dole listy są elementy wzorców strony (nad treścią i pod treścią). Nie zmienisz ich tutaj — kliknięcie otwiera wzorzec do edycji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.5\">Własny wzorzec i edycja</a>).</li></ul>"}]},
  {"nr":"11","tytul":"Strony, sekcje i rozkładówki","czesc":"Edytor","ikona":"olowek","wstep":"Kolejność stron, sekcje o różnych formatach, rozkładówki, okładka z grzbietem i numeracja.","sekcje":[{"id":"11.1","tytul":"Panel stron","html":"<p>Panel z lewej pokazuje miniatury wszystkich stron w kolejności druku, pogrupowane w sekcje (szare nagłówki). Kliknięcie miniatury otwiera stronę. Strona powielana z danych ma znaczek <b>×N</b> — tyle razy wyjdzie w wydruku (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</p><p>Na telefonie strony stoją w poziomym pasku, który przewijasz palcem.</p><figure class=\"kadr telefon\"><img src=\"img/instrukcja/k-strony-telefon.png\" alt=\"Pasek stron na telefonie\" loading=\"lazy\"><figcaption>Pasek stron na telefonie</figcaption></figure><figure><img src=\"img/instrukcja/strony.png\" alt=\"Panel stron z menu strony\" loading=\"lazy\"><figcaption>Panel stron z menu strony</figcaption></figure>"},{"id":"11.2","tytul":"Dodawanie i porządkowanie stron","html":"<ul class=\"punkty\"><li>Kafelek <b>+</b> na końcu stron sekcji dodaje pustą stronę za bieżącą.</li><li><span class=\"ui\">+ Sekcja</span> na dole panelu tworzy nową sekcję.</li><li><b>Przeciągnij miniaturę</b>, żeby zmienić kolejność; upuszczona w innej sekcji przechodzi do niej.</li><li><span class=\"ui\">⋯</span> na miniaturze: <span class=\"ui\">Zmień nazwę</span>, <span class=\"ui\">Duplikuj</span>, <span class=\"ui\">Przesuń wyżej</span>, <span class=\"ui\">Przesuń niżej</span>, <span class=\"ui\">Usuń stronę</span>.</li><li><span class=\"ui\">⋯</span> przy nagłówku sekcji: <span class=\"ui\">Ustawienia sekcji</span>, <span class=\"ui\">Dodaj stronę do sekcji</span>, <span class=\"ui\">Przesuń sekcję wyżej</span>, <span class=\"ui\">Przesuń sekcję niżej</span>, <span class=\"ui\">Usuń sekcję</span>.</li></ul>"},{"id":"11.3","tytul":"Właściwości strony","html":"<p>Gdy nic nie jest zaznaczone, panel właściwości pokazuje ustawienia otwartej strony:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Nazwa strony</b></td><td>Nazwa na liście stron.</td></tr><tr><td><b>Sekcja</b></td><td>Przeniesienie strony do innej sekcji.</td></tr><tr><td><b>Tło</b></td><td>Kolor tła tej strony.</td></tr><tr><td><b>Wzorce</b></td><td>Wzorce z sekcji albo własny wybór dla tej strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Na których stronach jest wzorzec</a>).</td></tr><tr><td><b>Seria</b></td><td>Powielanie strony z tabeli danych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</td></tr><tr><td><b>Prowadnice</b></td><td>Prowadnice wpisane liczbą (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.4\">Linijki i prowadnice</a>).</td></tr><tr><td><span class=\"ui\">Wklej skopiowane elementy</span></td><td>Wkleja elementy ze schowka w to samo miejsce.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-seria.png\" alt=\"Ustawienia strony: seria\" loading=\"lazy\"><figcaption>Ustawienia strony: seria</figcaption></figure>"},{"id":"11.4","tytul":"Ustawienia sekcji","html":"<p>Sekcja to część publikacji z własnymi ustawieniami, np. „Okładka” i „Środek”. Okno otworzysz przyciskiem formatu na górnym pasku albo <span class=\"ui\">⋯</span> przy nagłówku sekcji → <span class=\"ui\">Ustawienia sekcji</span>.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Nazwa sekcji</b></td><td>Nazwa na liście stron.</td></tr><tr><td><b>Układ stron</b></td><td><b>Pojedyncze</b> albo <b>Rozkładówki</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.5\">Rozkładówki</a>).</td></tr><tr><td><b>Rodzaj sekcji</b></td><td><b>Strony</b>, <b>Okładka z grzbietem</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>) albo sekcja specjalna: obwoluta, ulotka składana, kalendarz z datami, kalendarz trójdzielny, wykrojnik, arkusz użytków (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.11\">Sekcje specjalne: obwoluta, ulotka, kalendarze, wykrojniki, użytki</a>) — wtedy wymiary liczą się same.</td></tr><tr><td><b>Format</b></td><td>Rozmiar strony w mm. Zmiana tutaj nie rusza elementów — żeby przeskalować je razem z formatem, kliknij <span class=\"ui\">Zmień format i dopasuj elementy…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.9\">Zmiana formatu ze skalowaniem</a>).</td></tr><tr><td><b>Marginesy i spad</b></td><td>Wpisujesz je na schemacie strony, w mm.</td></tr><tr><td><b>Pierwsza strona sekcji</b></td><td>W rozkładówkach: <b>Prawa (jak w książce)</b> albo <b>Lewa (od razu pełna rozkładówka)</b>.</td></tr><tr><td><b>Numeracja stron</b></td><td><b>Dalszy ciąg poprzedniej sekcji</b>, <b>Zacznij od numeru…</b> albo <b>Bez numerów (np. okładka)</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.8\">Numeracja stron</a>).</td></tr><tr><td><b>Składki (pilnuj liczby stron)</b></td><td><b>Bez pilnowania</b> albo co 4, 8, 16, 32 strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.7\">Składki</a>).</td></tr><tr><td><b>Wzorce na stronach tej sekcji</b></td><td>Wzorce domyślne stron sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.4\">Na których stronach jest wzorzec</a>).</td></tr><tr><td><b>Znaki cięcia w pliku PDF</b></td><td>Znaki cięcia na stronach tej sekcji w pliku dla drukarni.</td></tr><tr><td><b>Siatka linii bazowych</b></td><td><b>Odstęp</b> i <b>Pierwsza linia</b> (mm od góry) — wiersze tekstów z „Wyrównaj do siatki” stoją na tych liniach (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.13\">Siatka linii bazowych</a>).</td></tr></tbody></table></div><figure><img src=\"img/instrukcja/sekcje.png\" alt=\"Ustawienia sekcji\" loading=\"lazy\"><figcaption>Ustawienia sekcji</figcaption></figure>"},{"id":"11.5","tytul":"Rozkładówki","html":"<p>W sekcji z rozkładówkami strony tworzą pary: lewa i prawa, jak w otwartej książce.</p><ul class=\"punkty\"><li>Lewą i prawą stronę edytujesz <b>razem</b>. Nowe elementy trafiają na stronę bieżącą — wybierasz ją kliknięciem w jej obszar.</li><li>Marginesy są <b>lustrzane</b>: wewnętrzny przy grzbiecie, zewnętrzny przy krawędzi.</li><li>Element może leżeć <b>przez grzbiet</b>, np. zdjęcie na całą rozkładówkę — każda strona wydrukuje swoją część. Element należy do strony, na której leży jego środek.</li><li>Gruba ciemna linia to grzbiet. Tekstu nie kładź tuż przy nim — po zszyciu może go nie być widać; aplikacja ostrzega o elementach, które wystają w pas przy grzbiecie.</li><li>Przycisk z dwiema kartkami obok powiększenia przełącza całą rozkładówkę i jedną stronę (na telefonie domyślnie jedna strona).</li></ul><figure><img src=\"img/instrukcja/rozkladowki.png\" alt=\"Rozkładówka\" loading=\"lazy\"><figcaption>Rozkładówka</figcaption></figure>"},{"id":"11.6","tytul":"Okładka z grzbietem","html":"<p>Okładka to osobna sekcja z jedną szeroką stroną: tył, grzbiet i przód. Zrobisz ją w oknie sekcji (<b>Rodzaj sekcji</b> → <b>Okładka z grzbietem</b>), w menu sekcji (<span class=\"ui\">Zamień na okładkę z grzbietem</span>) albo od razu w oknie nowego projektu (pole <b>Okładka</b>).</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co znaczy</th></tr></thead><tbody><tr><td><b>Oprawa</b></td><td><b>Miękka klejona (z grzbietem)</b>, <b>Zeszytowa – szyta zszywkami (bez grzbietu)</b> albo <b>Twarda (tektura z zawinięciem)</b> — przy twardej ustawisz <b>Zawinięcie</b>, <b>Big</b>, <b>Naddatek tektury</b> i <b>Grubość tektury</b> (mm).</td></tr><tr><td><b>Papier środka</b></td><td><b>Gramatura</b> — <b>Gramatura (g/m²)</b> i <b>Rodzaj papieru</b> (offset, kredowy mat, kredowy błysk, objętościowy) — albo <b>Grubość kartki</b> w mm od drukarni.</td></tr><tr><td><b>Strony środka</b></td><td><b>Policz same</b> — ze wszystkich stron środka, razem z powieleniami serii — albo <b>Wpisz</b> liczbę. <b>Środek to sekcje</b> wybiera, które sekcje się liczą, gdy jest ich kilka.</td></tr></tbody></table></div><p>Schemat w oknie pokazuje tył, grzbiet i przód, a pod nim wynik, np. „Grzbiet 6,6 mm · Okładka 352,6 × 246 mm”. Szerokość i wysokość okładki liczą się same.</p><p><b>Wymiary</b> — gdy drukarnia poda grzbiet albo cały rozmiar okładki:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Wybór</th><th>Co się dzieje</th></tr></thead><tbody><tr><td><b>Policz same</b></td><td>Grzbiet z papieru i liczby stron, rozmiar z formatu środka.</td></tr><tr><td><b>Wpisz grzbiet</b></td><td><b>Grzbiet (mm)</b> od drukarni zamiast liczonego. Reszta liczy się jak zwykle.</td></tr><tr><td><b>Wpisz rozmiar</b></td><td><b>Szerokość okładki</b> i <b>Wysokość okładki</b> (mm, bez spadu) — tył i przód dzielą resztę szerokości po równo wokół grzbietu. Grzbiet możesz też wpisać; puste pole — grzbiet liczony.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-wymiary.png\" alt=\"Wymiary okładki wpisane ręcznie\" loading=\"lazy\"><figcaption>Wymiary okładki wpisane ręcznie</figcaption></figure><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-okno.png\" alt=\"Okno sekcji: okładka z grzbietem, schemat i wynik\" loading=\"lazy\"><figcaption>Okno sekcji: okładka z grzbietem, schemat i wynik</figcaption></figure><p>Na płótnie przerywane linie pokazują zgięcia (grzbiet, bigi, zawinięcia), a niebieskie ramki — bezpieczne pola tyłu, grzbietu i przodu.</p><figure><img src=\"img/instrukcja/okladka.png\" alt=\"Okładka na płótnie: tył, grzbiet, przód\" loading=\"lazy\"><figcaption>Okładka na płótnie: tył, grzbiet, przód</figcaption></figure><p>Gdy w środku przybędzie stron albo zmienisz papier, okładka przelicza się sama: tył zostaje, przód przesuwa się razem z grzbietem, napisy na grzbiecie zostają na jego środku, a tło na całą okładkę się rozciąga. W panelu elementu, w części <b>Inne</b>, lista <b>Na okładce trzyma się</b> (automatycznie, tyłu, grzbietu albo przodu) mówi, czego element się trzyma; przełącznik <b>Dopasuj szerokość do grzbietu</b> rozciąga pasek na grzbiecie na całą jego szerokość. Ostrzeżenie „Szerszy niż grzbiet” mówi, że element zachodzi na tył albo przód.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-okladka-przypiecie.png\" alt=\"Element przypięty do części okładki\" loading=\"lazy\"><figcaption>Element przypięty do części okładki</figcaption></figure><p class=\"ramka-instrukcji uwaga\"><b>Uwaga.</b> wzorce przypisane do sekcji okładki nie przesuwają się same.</p>"},{"id":"11.7","tytul":"Składki","html":"<p>Środek szyty albo klejony ze składek musi mieć liczbę stron podzielną przez wielkość składki. W ustawieniach sekcji wybierz <b>Składki</b>: co 4, 8, 16 albo 32 strony.</p><p>Na liście stron pod nazwą sekcji zobaczysz np. „46 z 48 – brakuje 2 do pełnej składki (×16)”. <span class=\"ui\">Dopełnij pustymi</span> dodaje brakujące puste strony na końcu sekcji — cofniesz to jak każdą zmianę. <b>Sprawdź przed drukiem</b> też przypomni o niepełnej składce, a przy oprawie zeszytowej — o liczbie stron niepodzielnej przez 4.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-skladki.png\" alt=\"Licznik składki i „Dopełnij pustymi”\" loading=\"lazy\"><figcaption>Licznik składki i „Dopełnij pustymi”</figcaption></figure>"},{"id":"11.8","tytul":"Numeracja stron","html":"<p>Numer strony wstawisz polem <code>{nr}</code> — najlepiej we wzorcu, żeby był na każdej stronie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.7\">Pola we wzorcu</a>). Numeracja zależy od ustawień sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>) i liczy strony po powieleniu serii. Inne zapisy numeru (rzymskie, z zerami) są w tabeli pól (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.2\">Pola dokumentu</a>).</p>"},{"id":"11.9","tytul":"Zmiana formatu ze skalowaniem","html":"<p>Kalendarz z A4 na A3, książka z B5 na A5 — format zmienisz razem z elementami:</p><ul class=\"punkty\"><li>jedna sekcja: okno sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>) → <span class=\"ui\">Zmień format i dopasuj elementy…</span>,</li><li>cały projekt: <span class=\"ui\">⋯</span> → <span class=\"ui\">Zmień format projektu…</span>.</li></ul><ol class=\"kroki\"><li>Wybierz <b>Nowy format</b> z listy albo wpisz <b>Szerokość (mm)</b> i <b>Wysokość (mm)</b>; <span class=\"ui\">Zamień orientację</span> obraca kartkę.</li><li>Wybierz, <b>Co z elementami</b>:</li></ol><div class=\"tabela-instrukcji\"><table><thead><tr><th>Sposób</th><th>Co się dzieje</th></tr></thead><tbody><tr><td><b>Skaluj wszystko</b></td><td>Elementy, pismo, linie, marginesy, prowadnice i wzorce zmieniają się proporcjonalnie. <b>Skala</b>: <b>Zmieść całą stronę (wyśrodkuj)</b>, <b>Dopasuj do szerokości</b> albo <b>Dopasuj do wysokości</b>.</td></tr><tr><td><b>Zostaw rozmiary, przesuń względem krawędzi</b></td><td>Rozmiary zostają; element trzyma się najbliższej krawędzi albo środka. Tło i paski na całą szerokość lub wysokość rozciągają się na nową stronę.</td></tr><tr><td><b>Tylko zmień format</b></td><td>Elementy zostają tam, gdzie są.</td></tr></tbody></table></div><ol class=\"kroki\"><li>Podgląd <b>Teraz → Po zmianie</b> pokazuje pierwszą stronę przed i po. Pod nim są uwagi, np. ile elementów wyjdzie poza stronę.</li><li><span class=\"ui\">Zmień format</span>. Całą zmianę cofniesz jednym <span class=\"ui\">Cofnij</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-format.png\" alt=\"Zmiana formatu z podglądem przed i po\" loading=\"lazy\"><figcaption>Zmiana formatu z podglądem przed i po</figcaption></figure><p>Okładka z grzbietem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>) przelicza się sama po zmianie formatu środka. Elementy, które po zmianie wystają poza stronę, pokaże <b>Sprawdź przed drukiem</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>).</p>"},{"id":"11.10","tytul":"Gotowe sekcje (szablony dokumentów)","html":"<p>Cały gotowy dokument wstawisz jednym kliknięciem jako nową sekcję: kalendarz ścienny, planer na 365 dni, notes, zaproszenie, dyplomy dla listy osób, wizytówki, ulotkę, menu, rozdział książki i ponad 30 innych. Gdzie: na dole panelu stron przycisk <span class=\"ui\">Gotowa</span> (obok <span class=\"ui\">Sekcja</span>), w Bibliotece kategoria <b>Gotowe sekcje</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"5.8\">Biblioteka</a>) albo od razu przy nowym projekcie: <b>Zacznij od → Gotowego szablonu</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.2\">Nowy projekt</a>).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-gotowe-sekcje.png\" alt=\"Gotowe sekcje – galeria szablonów\" loading=\"lazy\"><figcaption>Gotowe sekcje – galeria szablonów</figcaption></figure><ol class=\"kroki\"><li>Wybierz rodzaj u góry (<b>Książka</b>, <b>Kalendarze</b>, <b>Planery i notesy</b>, <b>Zaproszenia i dyplomy</b>, <b>Firma i reklama</b>, <b>Inne</b>) albo wpisz słowo w <b>Szukaj</b>. Miniatura pokazuje pierwszą stronę w formacie Twojego projektu, a pod nią widać, ile stron powstanie. Plakietka <b>z danymi</b> – strony biorą treść z tabeli (np. 365 dni, osoby do dyplomów).</li><li>Kliknij szablon. Zobaczysz podgląd pierwszych stron i ustawienia: - pytania szablonu, np. <b>Rok</b> kalendarza albo <b>Liczba stron</b> notesu, - <b>Kolory</b>: kolory marki (gdy masz zestaw marki, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>), kolory szablonu albo jedna z gotowych palet, - szablony z własnym formatem (wizytówka 85 × 55 mm, dyplom A4 poziomo, etykieta 70 × 40 mm) mają przełącznik formatu – odznacz go, żeby szablon dopasował się do formatu sekcji.</li><li><span class=\"ui\">Wstaw jako nową sekcję</span>. Sekcja staje za bieżącą, a edytor przechodzi na jej pierwszą stronę.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-gotowe-szczegoly.png\" alt=\"Szczegóły szablonu – podgląd, rok i kolory\" loading=\"lazy\"><figcaption>Szczegóły szablonu – podgląd, rok i kolory</figcaption></figure><p>Szablon nie jest zamrożonym plikiem: buduje się dla Twojego formatu, marginesów i spadu, w kolorach i czcionkach marki. Po wstawieniu to zwykłe strony, wzorce (np. numer strony), style i tabela danych z serią (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15\">Tabele danych</a>, <a href=\"#\" data-cel=\"17\">Serie</a>) – zmienisz w nich wszystko jak we własnych. Szare pola to miejsca na zdjęcia: wstaw do nich obraz (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.7\">Obraz w kształcie</a>). Całą wstawioną sekcję usuwa jedno <span class=\"ui\">Cofnij</span> (<kbd>Ctrl</kbd>+<kbd>Z</kbd>).</p>"},{"id":"11.11","tytul":"Sekcje specjalne: obwoluta, ulotka, kalendarze, wykrojniki, użytki","html":"<p>Sekcja specjalna działa jak okładka z grzbietem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>): wie, czym jest wydrukowana rzecz. Sama liczy swój format, podpisuje na stronie strefy (panele, skrzydełka, klapy), rysuje linie zgięć (bigi, przerywane), perforacji (kropkowane) i cięcia (ciągła różowa linia), ostrzega o tekście na zgięciu i o elementach poza linią cięcia, a w pliku PDF daje arkusz w pełnym wymiarze. Rodzaj wybierasz w ustawieniach sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>): <b>Rodzaj sekcji</b>. Schemat w oknie pokazuje strefy i zgięcia na bieżąco, pod nim wymiary arkusza.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-sekcja-ulotka.png\" alt=\"Ulotka składana w ustawieniach sekcji\" loading=\"lazy\"><figcaption>Ulotka składana w ustawieniach sekcji</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Rodzaj</th><th>Co liczy</th></tr></thead><tbody><tr><td><b>Obwoluta ze skrzydełkami</b></td><td>Tył, grzbiet i przód z twardej okładki projektu (płyty i grzbiet), dwa skrzydełka (<b>Skrzydełko</b>, 0 – około połowy przodu) i zapas na zgięcie przy płycie. Przybędzie stron – obwoluta przeliczy się sama, a elementy przodu przesuną się razem z nim.</td></tr><tr><td><b>Ulotka składana</b></td><td>Arkusz na 2, 3 albo 4 panele, <b>Złożenie</b>: <b>Zwijane</b> (łamana C – panel składany do środka jest węższy o <b>Skrót</b>, żeby się nie zaginał) albo <b>Harmonijka</b> (Z – panele równe). Sekcja ma dwie strony: zewnętrzną (z panelem <b>Okładka</b>) i wewnętrzną.</td></tr><tr><td><b>Kalendarz z datami (rok)</b></td><td><b>Rok</b>, <b>Strona na</b> miesiąc, tydzień albo dzień, początek tygodnia i <b>Święta</b> (Polska: stałe i ruchome – Wielkanoc, Zielone Świątki, Boże Ciało). Tworzy tabelę danych i serię: pierwsza strona sekcji powiela się dla każdego miesiąca, tygodnia albo dnia. Zmiana roku przelicza wszystko.</td></tr><tr><td><b>Kalendarz trójdzielny</b></td><td>Główka, trzy kalendaria jedno pod drugim, okienko na środkowym i pasek reklamowy – z bigiem pod główką i perforacjami.</td></tr><tr><td><b>Wykrojnik</b></td><td><b>Koperta</b> (C6, DL, C5, kwadrat), <b>Teczka ofertowa</b> z kieszenią i nacięciami na wizytówkę albo <b>Pudełko</b> (długość, szerokość, wysokość → siatka z wieczkiem, dnem, klapkami i zakładką klejową).</td></tr><tr><td><b>Arkusz użytków</b></td><td>Naklejki, wizytówki, etykiety: projektujesz jeden użytek (albo kolejne z danych – seria), a w PDF stoją obok siebie na arkuszu (SRA3, A3, A4, B2) ze znakami cięcia. <b>Naklejka</b> dostaje linię wykrojnika z zaokrąglonymi rogami.</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-sekcja-wykrojnik.png\" alt=\"Wykrojnik pudełka na stronie: strefy, zgięcia i linia cięcia\" loading=\"lazy\"><figcaption>Wykrojnik pudełka na stronie: strefy, zgięcia i linia cięcia</figcaption></figure><p><b>Pola kalendarza z datami</b> do wstawienia w tekst (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Pola w tekście</a>): <code>{data}</code>, <code>{dzien}</code>, <code>{miesiac}</code>, <code>{dzien_tygodnia}</code>, <code>{tydzien}</code>, <code>{swieto}</code>; kolumna <code>wolne</code> ma wartość „tak” w niedziele i święta – użyj jej w kolorze zależnym od danych (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18\">Wygląd z danych</a>), żeby święta były czerwone. Własne kolumny dopisane do tej tabeli zostają po zmianie roku.</p><p><b>W pliku PDF</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22\">Eksport do PDF i PNG</a>): linia cięcia wykrojnika jest osobnym kolorem dodatkowym <b>CutContour</b>, zgięcia – <b>Crease</b>, perforacje – <b>Perforation</b>: drukarnia ich nie drukuje, tylko wycina, biguje i perforuje. Przy obwolucie, ulotce i kalendarzu trójdzielnym (cięte prosto) zgięcia i perforacje są zaznaczone kreskami poza formatem, obok znaków cięcia. Arkusz użytków składa się sam, gdy w eksporcie jest <b>Układ arkuszy: Zwykły</b>. Uwagi o tekście na zgięciu i elementach poza linią cięcia pokazuje też <b>Sprawdź przed drukiem</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>).</p><p>Gotowe sekcje (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.10\">Gotowe sekcje (szablony dokumentów)</a>) <b>Broszura składana</b>, <b>Wizytówki</b> i <b>Etykiety i naklejki</b> wstawiają się od razu jako ulotka składana i arkusz użytków.</p>"}]},
  {"nr":"12","tytul":"Wzorce stron","czesc":"Edytor","ikona":"olowek","sekcje":[{"id":"12.1","tytul":"Czym jest wzorzec i kiedy go użyć","html":"<p>Niektóre rzeczy powtarzają się na wielu stronach: <b>numer strony, nagłówek, stopka, tło, ramka, linie do pisania</b>. Zamiast wstawiać je na każdą stronę osobno, wstawiasz je raz — jako <b>wzorzec</b>.</p><ul class=\"punkty\"><li>Wzorzec leży <b>pod</b> treścią każdej strony, która go ma. Na samej stronie go nie zaznaczysz ani nie przesuniesz — dzięki temu nie rozjedzie się przypadkiem.</li><li>Zmieniasz go raz, a zmieniają się <b>wszystkie</b> te strony.</li><li>Pole <code>{nr}</code> we wzorcu pokazuje na każdej stronie jej własny numer: jeden wzorzec, a na stronach 1, 2, 3…</li><li>Strona może mieć kilka wzorców naraz, np. „Kratka” pod treścią i „Numer strony” na dole.</li></ul><p>Kiedy wzorzec, a kiedy zwykły element? Jeśli coś ma być <b>na wielu stronach w tym samym miejscu</b> — wzorzec. Jeśli tylko na jednej stronie — zwykły element.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wzorce-galeria.png\" alt=\"Okno Wzorce stron: co to jest i gotowe wzorce\" loading=\"lazy\"><figcaption>Okno Wzorce stron: co to jest i gotowe wzorce</figcaption></figure>"},{"id":"12.2","tytul":"Gdzie są wzorce","html":"<ul class=\"punkty\"><li><span class=\"ui\">Wzorce</span> pod listą stron (obok <span class=\"ui\">Sekcja</span>) i na górnym pasku edytora — otwiera okno <b>Wzorce stron</b>.</li><li>Menu ⋯ strony → <span class=\"ui\">Wzorce tej strony…</span> — przechodzi na tę stronę i otwiera okno.</li><li>Menu ⋯ sekcji → <span class=\"ui\">Wzorce sekcji…</span>.</li><li>Właściwości strony (nic nie jest zaznaczone) → część <b>Wzorce</b>: które wzorce są na tej stronie; dopóki projekt nie ma wzorców, jest tam przycisk <span class=\"ui\">Wybierz gotowy wzorzec…</span>.</li><li>Biblioteka → kategoria <b>Wzorce stron</b> — te same gotowe wzorce co w oknie.</li></ul><p>Strona, na której leży wzorzec, ma na miniaturze mały fioletowy znak; podpowiedź na nim mówi, jakie to wzorce.</p>"},{"id":"12.3","tytul":"Gotowe wzorce","html":"<p>W oknie <b>Wzorce stron</b> niżej jest galeria gotowych wzorców z podglądami — na schemacie elementy wzorca są wyraźne, a blade bloki to treść strony. Grupy:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Grupa</th><th>Przykłady</th></tr></thead><tbody><tr><td>Numeracja</td><td>numer na dole, przy zewnętrznej krawędzi, „Strona 5 z 120”, w kółku, na pasku bocznym, rzymski</td></tr><tr><td>Nagłówki i stopki</td><td>nazwa sekcji, projekt i sekcja, kolorowy pas, stopka z kontaktem</td></tr><tr><td>Tła i papier</td><td>linie, kratka, kropki, papier milimetrowy, zeszyt z marginesem, kolorowe tło, znak wodny</td></tr><tr><td>Ramki</td><td>w marginesach, podwójna, zaokrąglona, obwódka strony, narożniki</td></tr><tr><td>Kalendarz i planer</td><td>zakładka na brzegu, nagłówek dnia, kolumna „Notatki”, tydzień</td></tr><tr><td>Książka</td><td>żywa pagina z tytułem rozdziału, numer i rozdział u góry</td></tr><tr><td>Katalog i oferta, Gazetka, Zaproszenie</td><td>logo i kontakt, winieta, szpalty, ozdobna ramka, pasy</td></tr></tbody></table></div><p>Kliknięcie karty dodaje wzorzec do projektu i <b>od razu na wszystkie strony sekcji</b> otwartej strony — okno się zamyka, a wzorzec widać na stronie. <span class=\"ui\">Cofnij</span> w komunikacie albo <kbd>Ctrl</kbd>+<kbd>Z</kbd> odwraca to jednym krokiem. Gotowe wzorce dopasowują się do formatu i marginesów sekcji, a kolory i czcionki biorą z zestawu marki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.9\">Zestaw marki</a>), jeśli go masz. Po dodaniu to zwykły wzorzec — możesz go zmienić.</p>"},{"id":"12.4","tytul":"Na których stronach jest wzorzec","html":"<p>W oknie, w części <b>W tym projekcie</b>, przy każdym wzorcu:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Przycisk</th><th>Co robi</th></tr></thead><tbody><tr><td><span class=\"ui\">+ Dodaj do tej strony</span></td><td>Włącza wzorzec tylko na otwartej stronie. Ponowne kliknięcie (✓) go zdejmuje.</td></tr><tr><td><span class=\"ui\">+ Do całej sekcji</span></td><td>Włącza wzorzec na stronach sekcji, które nie mają własnego wyboru.</td></tr><tr><td><span class=\"ui\">Edytuj</span></td><td>Otwiera wzorzec do edycji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.5\">Własny wzorzec i edycja</a>).</td></tr><tr><td><span class=\"ui\">⋯</span></td><td><span class=\"ui\">Zmień nazwę</span>, <span class=\"ui\">Duplikuj</span>, <span class=\"ui\">Przesuń wyżej</span>, <span class=\"ui\">Przesuń niżej</span>, <span class=\"ui\">Usuń wzorzec</span>.</td></tr></tbody></table></div><p>Pojedynczej stronie wybierzesz wzorce też we właściwościach strony: <b>Wzorce na tej stronie</b> → <b>Jak w sekcji</b> albo <b>Własny wybór</b> i przełączniki przy nazwach.</p><figure><img src=\"img/instrukcja/okno-wzorcow.png\" alt=\"Okno Wzorce\" loading=\"lazy\"><figcaption>Okno Wzorce</figcaption></figure>"},{"id":"12.5","tytul":"Własny wzorzec i edycja","html":"<p><span class=\"ui\">Narysuj własny wzorzec</span> tworzy pusty wzorzec i od razu go otwiera. <span class=\"ui\">Edytuj</span> otwiera istniejący. Fioletowy pasek nad stroną przypomina, że zmieniasz wzorzec — wszystko, co tu narysujesz, pojawi się na stronach z tym wzorcem; <span class=\"ui\">Gotowe</span> wraca do stron. Na zwykłych stronach elementy wzorca widać na liście warstw, a kliknięcie tam otwiera wzorzec.</p><figure><img src=\"img/instrukcja/wzorce.png\" alt=\"Edycja wzorca\" loading=\"lazy\"><figcaption>Edycja wzorca</figcaption></figure>"},{"id":"12.6","tytul":"Nad treścią i odbicie lustrzane","html":"<p>Elementy wzorca leżą <b>pod</b> treścią strony. Zaznacz element we wzorcu i włącz:</p><ul class=\"punkty\"><li><b>Nad treścią strony</b> — element przykryje treść, np. ramka albo znak wodny,</li><li><b>Odbijaj lustrzanie na lewych stronach</b> — element przy prawej krawędzi (np. numer strony) na lewych stronach rozkładówek przejdzie na lewą krawędź. Gotowe wzorce „przy zewnętrznej krawędzi” mają to włączone.</li></ul>"},{"id":"12.7","tytul":"Pola we wzorcu","html":"<p>Wpisz we wzorcu tekst z polem, np. <code>Strona {nr} z {liczba_stron}</code>, <code>{sekcja}</code> albo <code>{rozdzial}</code> (tytuł bieżącego rozdziału). Na każdej stronie pojawi się jej wartość. Najprościej zacząć od gotowego wzorca z numerem strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.3\">Gotowe wzorce</a>).</p>"}]},
  {"nr":"13","tytul":"Linie pomocnicze, siatka i powiększenie","czesc":"Edytor","ikona":"olowek","wstep":"Rzeczy, które pomagają ustawiać elementy, a nie drukują się: marginesy, spad, siatka, prowadnice, powiększenie.","sekcje":[{"id":"13.1","tytul":"Linie na stronie","html":"<p>Linie pomocnicze nie są drukowane:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Linia</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Czerwona</b></td><td>Krawędź strony po przycięciu.</td></tr><tr><td><b>Różowy pas</b></td><td>Spad. Tła i zdjęcia, które mają sięgać krawędzi, rozciągnij aż do jego końca.</td></tr><tr><td><b>Niebieska przerywana</b></td><td>Margines. Teksty trzymaj w środku.</td></tr><tr><td><b>Gruba ciemna</b></td><td>Grzbiet rozkładówki.</td></tr><tr><td><b>Przerywane z podpisami</b></td><td>Na okładce: zgięcia — grzbiet, bigi, zawinięcia (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>).</td></tr><tr><td><b>Turkusowa</b></td><td>Prowadnica (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.4\">Linijki i prowadnice</a>).</td></tr></tbody></table></div><p><span class=\"ui\">Linie pomocnicze</span> (<kbd>W</kbd>) w prawym dolnym rogu chowa je wszystkie.</p>"},{"id":"13.2","tytul":"Ostrzeżenia","html":"<p>Element w marginesie albo poza spadem, tekst, który się nie mieści, czy pole z literówką dostają pomarańczową ramkę i trafiają na listę <b>Ostrzeżenia</b> na dole panelu z prawej (na telefonie — przycisk na dole ekranu). Kliknięcie pozycji zaznacza element. Gdy to celowe (np. tło na spad), kliknij <span class=\"ui\">Wycisz</span>.</p><figure><img src=\"img/instrukcja/ostrzezenia.png\" alt=\"Ostrzeżenia\" loading=\"lazy\"><figcaption>Ostrzeżenia</figcaption></figure>"},{"id":"13.3","tytul":"Siatka","html":"<p>W menu widoku (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>): <b>Siatka</b> pokazuje linie co <b>Krok siatki</b> (w mm, od rogu strony), a <b>Przyciągaj do siatki</b> ustawia lewy górny róg przesuwanego elementu na linii siatki.</p><figure><img src=\"img/instrukcja/siatka.png\" alt=\"Siatka i prowadnice\" loading=\"lazy\"><figcaption>Siatka i prowadnice</figcaption></figure>"},{"id":"13.4","tytul":"Linijki i prowadnice","html":"<ul class=\"punkty\"><li><b>Linijki</b> pokazują milimetry; zero leży w rogu otwartej strony.</li><li><b>Prowadnicę</b> wyciągniesz z linijki: z górnej w dół — poziomą, z lewej w prawo — pionową. Prowadnicę można przesunąć; wyciągnięta poza stronę znika.</li><li>We właściwościach strony część <b>Prowadnice</b> pozwala wpisać położenie liczbą i dodać prowadnicę pionową albo poziomą.</li><li><b>Zablokuj prowadnice</b> w menu widoku chroni je przed przypadkowym przesunięciem.</li></ul>"},{"id":"13.5","tytul":"Przyciąganie i odległości","html":"<p>Przy przesuwaniu i zmianie rozmiaru element przyciąga się do krawędzi, marginesów i środka strony, do prowadnic i do innych elementów:</p><ul class=\"punkty\"><li><b>różowa linia</b> — krawędź albo środek zrównały się z innym elementem,</li><li><b>strzałki z liczbą</b> — odległość w mm do najbliższych elementów,</li><li><b>fioletowe liczby</b> — odstęp jest równy innemu odstępowi w rzędzie.</li></ul><p>Przytrzymany <kbd>Ctrl</kbd> na chwilę wyłącza przyciąganie. Przytrzymany <kbd>Alt</kbd> przy zaznaczonym elemencie pokazuje też odległości do krawędzi strony.</p><figure><img src=\"img/instrukcja/odleglosci.png\" alt=\"Równe odstępy\" loading=\"lazy\"><figcaption>Równe odstępy</figcaption></figure>"},{"id":"13.6","tytul":"Powiększenie","html":"<ul class=\"punkty\"><li><span class=\"ui\">−</span> i <span class=\"ui\">+</span> w prawym dolnym rogu; kliknięcie procentu dopasowuje stronę do okna (<kbd>Ctrl</kbd>+<kbd>0</kbd>).</li><li><kbd>Ctrl</kbd> + kółko myszy powiększa w miejscu kursora.</li><li>Spacja + przeciąganie przesuwa widok.</li><li>Na ekranie dotykowym — dwa palce (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.1\">Gesty</a>).</li></ul>"}]},
  {"nr":"14","tytul":"Książka: spis treści, pagina, przypisy, odsyłacze, skorowidz","czesc":"Edytor","ikona":"olowek","wstep":"Spis treści, tytuł rozdziału w stopce, przypisy, odsyłacze i skorowidz — liczą się same.","sekcje":[{"id":"14.1","tytul":"W skrócie","html":"<p>Numery stron biorą się z numeracji sekcji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.8\">Numeracja stron</a>), także ze stronami powielonymi serią (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</p><figure><img src=\"img/instrukcja/ksiazka.png\" alt=\"Spis treści, przypis i żywa pagina na stronach książki\" loading=\"lazy\"><figcaption>Spis treści, przypis i żywa pagina na stronach książki</figcaption></figure>"},{"id":"14.2","tytul":"Nagłówki","html":"<p>Nagłówki to teksty w stylach akapitu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.4\">Style</a>), które projekt uznaje za tytuły rozdziałów. Z nich powstają spis treści, żywa pagina i lista odsyłaczy.</p><ul class=\"punkty\"><li>Bez ustawień styl <b>Tytuł</b> to nagłówek 1 (rozdział), a <b>Nagłówek</b> – nagłówek 2.</li><li>Inne style ustawisz w panelu spisu treści: przy każdym stylu wybierz <b>nagłówek 1</b>, <b>nagłówek 2</b>, <b>nagłówek 3</b> albo <b>nie jest nagłówkiem</b>.</li></ul><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> nadaj ten sam styl wszystkim tytułom rozdziałów – wtedy spis treści i pagina ułożą się same.</p>"},{"id":"14.3","tytul":"Spis treści","html":"<ol class=\"kroki\"><li>Otwórz <span class=\"ui\">Biblioteka</span> → <b>Książka</b> → <b>Spis treści</b> (albo <kbd>Ctrl</kbd>+<kbd>K</kbd> i „spis treści”).</li><li>Spis staje na stronie jako tekst i od razu wypełnia się nagłówkami z numerami stron.</li><li>Wygląd (czcionkę, rozmiar, interlinię) zmieniasz jak w każdym tekście.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-spis-tresci.png\" alt=\"Spis treści i jego panel\" loading=\"lazy\"><figcaption>Spis treści i jego panel</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Poziomy</b></td><td><b>tylko rozdziały</b>, <b>rozdziały i podrozdziały</b> albo <b>trzy poziomy</b>; niższe poziomy są wcięte.</td></tr><tr><td><b>Kropki do numeru strony</b></td><td>Wypełnia odstęp między tytułem a numerem kropkami.</td></tr><tr><td><b>Styl „…”</b></td><td>Który styl jest nagłówkiem i jakiego poziomu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14.2\">Nagłówki</a>).</td></tr><tr><td><span class=\"ui\">Odśwież teraz</span></td><td>Układa spis od razu. Zwykle nie trzeba – spis odświeża się sam po każdej zmianie.</td></tr></tbody></table></div><p>Długi spis przelej do kolejnej ramki, także na następnej stronie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.7\">Kolumny i tekst przez kilka ramek</a>). Treści spisu nie wpisuje się ręcznie – przy następnym odświeżeniu ułożyłaby się od nowa.</p>"},{"id":"14.4","tytul":"Żywa pagina","html":"<p>Żywa pagina to tytuł bieżącego rozdziału w stopce albo nagłówku strony.</p><ol class=\"kroki\"><li>Otwórz wzorzec stopki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12\">Wzorce stron</a>).</li><li>W tekście stopki wybierz <b>Wstaw pole</b> → <b>{rozdzial}</b>. Obok możesz dać numer strony: <code>{rozdzial} – {nr}</code>.</li></ol><p>Na każdej stronie pole pokazuje ostatni nagłówek 1 do tej strony. <code>{rozdzial:2}</code> pokazuje nagłówek 2 – nowy rozdział go zeruje.</p>"},{"id":"14.5","tytul":"Przypisy dolne","html":"<ol class=\"kroki\"><li>Zaznacz tekst (albo pisz w nim – przypis stanie w miejscu kursora).</li><li>W panelu, w części <b>Przypisy, odsyłacze, skorowidz</b>, wybierz <span class=\"ui\">Wstaw przypis</span> (albo <kbd>Ctrl</kbd>+<kbd>K</kbd> i „przypis”).</li><li>W polu <b>Przypis 1</b> wpisz treść.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-przypisy.png\" alt=\"Przypis w panelu i na dole strony\" loading=\"lazy\"><figcaption>Przypis w panelu i na dole strony</figcaption></figure><ul class=\"punkty\"><li>W tekście staje numer w indeksie górnym, a treść – na dole tej samej strony, nad dolnym marginesem, pod krótką kreską. W edytorze widać ją od razu, ale nie da się jej zaznaczyć: zmieniasz ją w panelu.</li><li>Numery liczą się same. <b>Numeracja przypisów</b>: <b>Od nowa w każdej sekcji</b>, <b>Od nowa na każdej stronie</b> albo <b>W całym projekcie</b>.</li><li>Tekst płynący przez kilka ramek zabiera przypis ze sobą: przypis jest na tej stronie, na której stoi jego numer.</li><li>Wygląd przypisów: styl akapitu o nazwie <b>Przypis</b> (jeśli go nie ma – pismo 8 pt).</li><li><span class=\"ui\">Usuń przypis</span> zdejmuje i numer z tekstu, i treść.</li></ul>"},{"id":"14.6","tytul":"Odsyłacze","html":"<p>Odsyłacz to numer strony innego miejsca w książce, np. „zob. s. 12”.</p><ol class=\"kroki\"><li>Zaznacz tekst, w którym ma stać odsyłacz.</li><li>W części <b>Przypisy, odsyłacze, skorowidz</b> wybierz z listy <b>Wstaw odsyłacz do</b> nagłówek.</li><li>W tekście pojawi się „s. 12” – numer zmienia się sam, gdy strony się przesuną.</li></ol><p>W edytorze odsyłacz widać jako pole <code>{s:…}</code>; liczbę zobaczysz w podglądzie i w PDF. Gdy nagłówek usuniesz, zamiast numeru stanie „?”, a <b>Sprawdź przed drukiem</b> o tym przypomni (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>).</p>"},{"id":"14.7","tytul":"Skorowidz","html":"<ol class=\"kroki\"><li>Zaznacz słowo w pisanym tekście.</li><li>Wybierz <span class=\"ui\">Dodaj do skorowidza</span> (albo <kbd>Ctrl</kbd>+<kbd>K</kbd> i „skorowidz”). Bez zaznaczenia aplikacja zapyta o hasło.</li><li>Wstaw skorowidz: <span class=\"ui\">Biblioteka</span> → <b>Książka</b> → <b>Skorowidz</b>.</li></ol><p>Skorowidz ma hasła alfabetycznie (po polsku: ą po a, ł po l) z numerami wszystkich stron, na których słowo występuje w jakimkolwiek tekście – wielkość liter nie ma znaczenia, a kolejne strony łączą się w zakres (3–5). Hasła tekstu widać w panelu jako żetony; kliknięcie żetonu usuwa hasło.</p>"}]},
  {"nr":"15","tytul":"Tabele danych","czesc":"Dane i serie","ikona":"dane","wstep":"Dane trzymasz w tabelach projektu; z nich biorą się wartości pól i powielane strony.","sekcje":[{"id":"15.1","tytul":"Okno Dane","html":"<p>Tabela to arkusz: kolumny mają nazwy (np. <code>dzien</code>, <code>imie</code>), a wiersze — wartości. Z tabel biorą się wartości pól w tekście (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16\">Pola w tekście</a>) i powielone strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</p><p>Okno otwiera <span class=\"ui\">Dane</span> na górnym pasku edytora. Z lewej jest lista tabel projektu, z prawej wybrana tabela. <span class=\"ui\">+</span> dodaje pustą tabelę, <span class=\"ui\">Importuj CSV albo Excel</span> — tabelę z pliku (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15.2\">Import z Excela i CSV</a>), <span class=\"ui\">Wiersz pomijany</span> — wiersz <code>[pomiń]</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.4\">Wiersze pomijane</a>), a <span class=\"ui\">Pobierz tabelę jako plik CSV</span> daje tabelę do dokończenia w arkuszu. Zmiany z jednego otwarcia okna cofniesz jednym <span class=\"ui\">Cofnij</span>.</p><figure><img src=\"img/instrukcja/dane.png\" alt=\"Okno Dane\" loading=\"lazy\"><figcaption>Okno Dane</figcaption></figure>"},{"id":"15.2","tytul":"Import z Excela i CSV","html":"<p><span class=\"ui\">Importuj CSV albo Excel</span> wczytuje plik <code>.xlsx</code>, <code>.xls</code>, <code>.ods</code> albo <code>.csv</code>:</p><ul class=\"punkty\"><li>pierwszy wiersz pliku to nazwy kolumn,</li><li>z pliku Excela powstaje po jednej tabeli na każdy arkusz,</li><li>separator (średnik, przecinek, tabulator) i polskie znaki aplikacja rozpoznaje sama,</li><li>liczby i daty trafiają do tabeli tak, jak je widać w arkuszu. Datę najlepiej rozbić na osobne kolumny, np. <code>dzien</code>, <code>miesiac</code>, <code>rok</code>.</li></ul><p>Poprawiłeś dane w arkuszu? Zaimportuj plik jeszcze raz. Gdy w projekcie jest tabela o tej samej nazwie, aplikacja zapyta, czy podmienić jej dane.</p>"},{"id":"15.3","tytul":"Poprawianie danych w aplikacji","html":"<ul class=\"punkty\"><li>Kliknij komórkę i pisz. <kbd>Enter</kbd> przechodzi wiersz niżej, <kbd>Shift</kbd>+<kbd>Enter</kbd> robi nową linię w komórce.</li><li>Dane skopiowane z Excela albo Arkuszy Google wklejasz od zaznaczonej komórki (<kbd>Ctrl</kbd>+<kbd>V</kbd>); tabela sama rośnie w dół i w prawo.</li><li><b>×</b> przy wierszu albo kolumnie usuwa go.</li><li>Nazwę kolumny zmieniasz, klikając nagłówek. Aplikacja poprawi tę nazwę we wszystkich polach projektu.</li></ul>"},{"id":"15.4","tytul":"Wygląd komórek","html":"<p>Pogrubienie, kursywa i kolor liter z pliku Excela przechodzą na strony: wartość wstawiona w pole dostaje wygląd swojej komórki — np. święta pogrubione na czerwono. Przechodzi też wygląd części tekstu w komórce.</p><p>W oknie Dane zaznacz komórkę (<kbd>Shift</kbd>+kliknięcie zaznacza prostokąt kilku komórek) i użyj: <span class=\"ui\">B</span> — pogrubienie, <span class=\"ui\">I</span> — kursywa, kolor liter, <span class=\"ui\">Wyczyść wygląd</span> (gumka).</p><p>Przełącznik <b>Przenoś wygląd komórek na strony</b> wyłącza przenoszenie — wygląd zostaje zapisany w tabeli.</p>"},{"id":"15.5","tytul":"Pilnowanie wartości","html":"<p>Przy nazwie każdej kolumny są dwa znaki:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Znak</th><th>Co robi</th></tr></thead><tbody><tr><td><b>≠</b></td><td>Wartości w kolumnie nie powinny się powtarzać (np. hasła dnia). Powtórzone komórki są czerwone, a przed drukiem aplikacja poda strony, na których ta sama wartość wypada dwa razy. Wielkość liter i spacje nie mają znaczenia.</td></tr><tr><td><b>☰</b></td><td>Lista dozwolonych wartości, np. <code>praca; dom; wolne</code>. Inne wartości są podświetlone i trafiają na listę przed drukiem; w szablonie danych komórki dostają listę rozwijaną. <span class=\"ui\">Usuń listę</span> ją usuwa.</td></tr></tbody></table></div>"}]},
  {"nr":"16","tytul":"Pola w tekście","czesc":"Dane i serie","ikona":"dane","wstep":"Pole to miejsce w tekście, w które wchodzi wartość z tabeli albo z projektu, np. numer strony.","sekcje":[{"id":"16.1","tytul":"Wstawianie pola","html":"<p>Pole to nazwa kolumny w klamrach, wpisana w zwykły tekst, np. <code>Imieniny: {imieniny}</code>. Na gotowej stronie w miejsce pola wchodzi wartość z tabeli.</p><p>Zaznacz tekst i wybierz kolumnę z listy <span class=\"ui\">Wstaw pole</span> we właściwościach. Lista zaczyna się od kolumn tabeli tej strony, dalej są pola dokumentu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.2\">Pola dokumentu</a>). Pole możesz też wpisać ręcznie.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-wstaw-pole.png\" alt=\"Wstaw pole\" loading=\"lazy\"><figcaption>Wstaw pole</figcaption></figure><p>W edytorze pola mają fioletowe tło, a pole, którego aplikacja nie zna (np. literówka) — czerwone. Prawdziwe wartości widać na miniaturach, w podglądzie i w PDF.</p><ul class=\"punkty\"><li>Pola z tabeli działają na stronach serii z tą tabelą (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17\">Serie</a>).</li><li>Pole z tabeli dodatkowej wpisujesz z nazwą tabeli: <code>{Tygodnie.haslo}</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.5\">Tabele dodatkowe</a>).</li><li>Pogrubione pole da pogrubioną wartość.</li></ul><figure><img src=\"img/instrukcja/pola.png\" alt=\"Pola w tekście\" loading=\"lazy\"><figcaption>Pola w tekście</figcaption></figure>"},{"id":"16.2","tytul":"Pola dokumentu","html":"<p>Pola dokumentu wynikają z samego projektu i działają na każdej stronie, także we wzorcach:</p><div data-wstaw=\"pola\"></div><p>Gdy kolumna tabeli nazywa się tak samo jak pole dokumentu, na stronach tej tabeli wygrywa kolumna.</p>"},{"id":"16.3","tytul":"Zwykłe klamry","html":"<ul class=\"punkty\"><li>Cały tekst bez pól: zaznacz tekst i włącz <b>Klamry { } to zwykły tekst, nie pola</b> (przełącznik pojawia się, gdy w tekście są klamry).</li><li>Pole i klamry w jednym tekście: wpisz klamry podwójnie — <code>{{</code> i <code>}}</code> staną się pojedynczymi klamrami, np. <code>Dzień {dzien}, wzór {{x}}</code> da „Dzień 5, wzór {x}”.</li></ul>"}]},
  {"nr":"17","tytul":"Serie","czesc":"Dane i serie","ikona":"dane","wstep":"Seria powiela stronę dla każdego wiersza tabeli — tak powstaje kalendarz na 365 dni z jednej strony.","sekcje":[{"id":"17.1","tytul":"Czym jest seria","html":"<p>Projektujesz jedną stronę dnia — dostajesz 365 stron, każdą z danymi swojego wiersza. Seria może obejmować kilka sąsiednich stron (<b>blok</b>), np. tydzień na rozkładówce: wtedy cały blok powiela się razem.</p><p>Powielone strony nie są zapisywane osobno — powstają na bieżąco, więc zmiana tabeli od razu zmienia publikację.</p>"},{"id":"17.2","tytul":"Nowa seria","html":"<ol class=\"kroki\"><li>Kliknij puste miejsce strony — właściwości pokażą ustawienia strony.</li><li>W polu <b>Seria</b> wybierz <span class=\"ui\">+ Nowa seria…</span>.</li><li>Ustaw serię w oknie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.3\">Ustawienia serii</a>) i kliknij <span class=\"ui\">Zapisz</span>.</li><li>Kolejnym stronom bloku wybierz tę samą serię.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-seria.png\" alt=\"Seria we właściwościach strony\" loading=\"lazy\"><figcaption>Seria we właściwościach strony</figcaption></figure><p>Strony serii mają na liście stron fioletowy znaczek z liczbą powieleń, np. <b>×31</b>. <b>×0</b> znaczy, że wszystkie wiersze tej strony są pomijane.</p><figure><img src=\"img/instrukcja/serie.png\" alt=\"Strony powielone w podglądzie\" loading=\"lazy\"><figcaption>Strony powielone w podglądzie</figcaption></figure>"},{"id":"17.3","tytul":"Ustawienia serii","html":"<p>Okno serii otwiera się po wybraniu <span class=\"ui\">+ Nowa seria…</span>, a dla istniejącej serii — przyciskiem <span class=\"ui\">Ustawienia serii</span> we właściwościach strony. Pod polem <b>Seria</b> widać, ile stron wyjdzie w wydruku.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Nazwa serii</b></td><td>Nazwa na liście serii.</td></tr><tr><td><b>Dane z tabeli</b></td><td>Tabela, z której biorą się wiersze.</td></tr><tr><td><b>Ile razy powielić</b></td><td><b>Tyle razy, ile wierszy ma tabela</b> albo <b>Stałą liczbę razy</b> — np. 12 miesięcy; dane idą wtedy w kółko.</td></tr><tr><td><b>Jak czytać tabelę</b></td><td><b>Jeden wiersz na cały blok stron</b> (kolumny np. <code>s1_tytul</code>, <code>s2_tytul</code> dla kolejnych stron) albo <b>Jeden wiersz na każdą stronę bloku</b>.</td></tr><tr><td><b>Dokończ ostatni blok stronami bez danych</b></td><td>Seria kończy się na ostatnim wierszu; z tym ustawieniem ostatni blok jest pełny.</td></tr><tr><td><b>Pilnuj lewej i prawej strony</b></td><td>W rozkładówkach (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.6\">Serie w rozkładówkach</a>).</td></tr><tr><td><b>Dodatkowe tabele</b></td><td>Dane zmieniające się rzadziej niż strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.5\">Tabele dodatkowe</a>).</td></tr><tr><td><b>Dane, których potrzebują strony</b></td><td>Pola użyte na stronach bloku. <span class=\"ui\">Dodaj brakujące kolumny do tabeli</span> dopisuje brakujące.</td></tr><tr><td><span class=\"ui\">Pobierz szablon danych (Excel)</span></td><td>Plik z kolumnami, których potrzebują strony (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.7\">Szablon danych</a>).</td></tr></tbody></table></div>"},{"id":"17.4","tytul":"Wiersze pomijane","html":"<p>Przykład: kalendarz z blokiem na tydzień (poniedziałek–niedziela), a rok zaczyna się w czwartek. Bez niczego 1 stycznia trafiłby na stronę poniedziałku. Dopisz więc na początku tabeli trzy <b>wiersze pomijane</b> — za poniedziałek, wtorek i środę.</p><p>Wiersz pomijany ma w pierwszej komórce znacznik <code>[pomiń]</code>. Zajmuje swoje miejsce w bloku, ale jego strona nie powstaje: nie ma jej w podglądzie, w PDF ani w numeracji. Wstawisz go przyciskiem <span class=\"ui\">Wiersz pomijany</span> w oknie Dane — nad wierszem, w którym stoi kursor — albo wpiszesz <code>[pomiń]</code> w Excelu.</p><p>Koniec roku nie wymaga niczego: seria kończy się na ostatnim wierszu danych.</p>"},{"id":"17.5","tytul":"Tabele dodatkowe","html":"<p>Tabela dodatkowa daje dane, które zmieniają się rzadziej niż strony — np. hasło tygodnia na stronach dni albo obrazek miesiąca. W oknie serii: <span class=\"ui\">Dodaj tabelę</span>, a potem <b>Nowy wiersz</b>:</p><ul class=\"punkty\"><li><b>co stałą liczbę stron</b> — np. co 7 stron dla tygodni,</li><li><b>gdy zmieni się kolumna „…”</b> — np. <code>miesiac</code>: nowy wiersz tam, gdzie w tabeli głównej zmienia się miesiąc. Kilka kolumn (np. miesiąc i rok) wybierzesz w kolejnych listach <b>albo kolumna</b>.</li></ul><p>Pole z tabeli dodatkowej: <code>{Tygodnie.haslo}</code>. Gdy tabeli dodatkowej zabraknie wierszy, okno serii pokaże to na czerwono, a przed drukiem — na liście uwag.</p>"},{"id":"17.6","tytul":"Serie w rozkładówkach","html":"<p><b>Pilnuj lewej i prawej strony – wstaw pustą stronę, gdy trzeba</b> sprawia, że strona zaprojektowana jako lewa zawsze wychodzi po lewej, a prawa po prawej. Gdy trzeba, aplikacja wstawia pustą białą stronę — np. za serią, gdy dane kończą się na lewej stronie. Pusta strona liczy się w numeracji, jak w drukowanych książkach. <span class=\"ui\">Sprawdź przed drukiem</span> wypisuje, gdzie stoją puste strony.</p>"},{"id":"17.7","tytul":"Szablon danych","html":"<p><span class=\"ui\">Pobierz szablon danych (Excel)</span> daje plik z kolumnami dokładnie takimi, jakich wymagają strony, razem z danymi, które już są w tabeli. Arkusz „Instrukcja” opisuje każdą kolumnę. Kolumny z listą wartości, nazwami obrazów albo kadrem mają listy rozwijane. Wypełniony plik zaimportuj w oknie Dane.</p>"}]},
  {"nr":"18","tytul":"Wygląd z danych","czesc":"Dane i serie","ikona":"dane","wstep":"Kolor, położenie, obraz albo widoczność elementu mogą zmieniać się na każdej powielonej stronie.","sekcje":[{"id":"18.1","tytul":"Część Z danych","html":"<p>Element może zmieniać się razem z danymi na kolejnych powielonych stronach: kolor, miejsce, rozmiar, obrót, obraz albo widoczność. Zaznacz element i rozwiń część <b>Z danych</b> we właściwościach.</p><p>W edytorze element wygląda jak wzór (pozycja 1, kolor wzoru, zawsze widoczny). Właściwy wygląd każdej strony widać w podglądzie, na miniaturach i w PDF.</p><figure><img src=\"img/instrukcja/zakladki.png\" alt=\"Zakładka na brzegu: inne miejsce i kolor na każdej stronie\" loading=\"lazy\"><figcaption>Zakładka na brzegu: inne miejsce i kolor na każdej stronie</figcaption></figure>"},{"id":"18.2","tytul":"Kolor z pola","html":"<p><b>Kolor z pola</b> — kolumna z kolorami, np. <code>#d1495b</code>, <code>2e86ab</code> albo nazwa po angielsku (<code>navy</code>). Pusta albo błędna wartość zostawia kolor wzoru. Linia i kształt bez wypełnienia dostają kolor obrysu. Przy wypełnieniu przejściem kolorów wybierasz, co zmienia kolor z pola: pierwszy kolor, ostatni kolor albo całe przejście w odcieniach.</p>"},{"id":"18.3","tytul":"Położenie, rozmiar i obrót z pola","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Przesunięcie w poziomie z pola</b>, <b>Przesunięcie w pionie z pola</b></td><td>Pole z liczbą — kolumna tabeli albo np. <code>{egzemplarz}</code> (numer powielenia).</td></tr><tr><td><b>Wartość pola to</b></td><td><b>numer pozycji</b> — element przesuwa się o <b>Krok</b> (mm) za każdą pozycję; <b>Od nowa co</b> N wraca na początek. Albo <b>przesunięcie w mm</b> — liczba z tabeli wprost.</td></tr><tr><td><b>Szerokość z pola</b>, <b>Wysokość z pola</b></td><td>Wartość to <b>procent rozmiaru wzoru (100 = bez zmian)</b> albo <b>rozmiar w mm</b>. <b>Przy zmianie rozmiaru na miejscu zostaje</b> — który bok albo róg stoi w miejscu.</td></tr><tr><td><b>Obrót z pola (stopnie)</b></td><td>Kąt dodawany do obrotu wzoru, np. wskazówka na każdej stronie inaczej.</td></tr></tbody></table></div><p>Tak robi się zakładki na brzegu strony — na każdej stronie niżej — albo słupki o wysokości z tabeli.</p>"},{"id":"18.4","tytul":"Pokaż element","html":"<p><b>Pokaż element</b>: <b>zawsze</b> albo tylko wtedy, gdy wybrane pole <b>nie jest puste</b>, <b>jest puste</b> albo <b>równa się</b> wpisanej wartości. Przykład: gwiazdka przy święcie — kolumna <code>swieto</code> i „nie jest puste”.</p>"},{"id":"18.5","tytul":"Obraz z danych","html":"<p>Wstaw dowolny obraz jako wzór — wyznacza miejsce i rozmiar. We właściwościach obrazu, w części <b>Obraz z danych</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Kolumna z nazwą pliku</b></td><td>W każdym wierszu nazwa pliku, np. <code>styczen.jpg</code>. Pliki wgrasz naraz w oknie Obrazy projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Okno Obrazy projektu</a>).</td></tr><tr><td><b>Podmieniony obraz</b></td><td><b>mieści się w ramce (cały widoczny)</b> — z wolnym miejscem po bokach albo u góry; <b>wypełnia ramkę (brzegi przycięte)</b> — bez pustych pasów.</td></tr><tr><td><b>Zostaje część zdjęcia</b></td><td>Przy wypełnianiu: środek, góra, dół, lewa albo prawa strona — np. „góra”, żeby nie ucinać głów na portretach.</td></tr><tr><td><b>Kadr z kolumny</b></td><td><b>ten sam na każdej stronie</b> albo kolumna, w której dla każdego zdjęcia wpiszesz <code>góra</code>, <code>dół</code>, <code>lewa</code>, <code>prawa</code> albo <code>środek</code>.</td></tr></tbody></table></div>"},{"id":"18.6","tytul":"Tekst o różnej długości","html":"<p>Teksty z tabeli mają różną długość, a układ strony ma zostać ten sam. Ustaw ramce <b>Stałą wysokość</b> i włącz <b>Zmniejszaj tekst, gdy się nie mieści</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"6.6\">Ramka tekstu</a>). <span class=\"ui\">Sprawdź przed drukiem</span> poda strony, na których tekst mimo to się nie mieści.</p><figure><img src=\"img/instrukcja/ramka-tekstu.png\" alt=\"Ramka o stałej wysokości\" loading=\"lazy\"><figcaption>Ramka o stałej wysokości</figcaption></figure>"}]},
  {"nr":"19","tytul":"Przykłady","czesc":"Dane i serie","ikona":"dane","wstep":"Gotowe przepisy krok po kroku.","sekcje":[{"id":"19.1","tytul":"Kalendarz książkowy","html":"<p>Jedna strona na dzień, z dniem tygodnia, imieninami i świętami w kolorze.</p><ol class=\"kroki\"><li>Nowy projekt A5, układ <b>Rozkładówki</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.2\">Nowy projekt</a>).</li><li>W oknie Dane zaimportuj tabelę <b>Dni</b> z kolumnami <code>dzien</code>, <code>miesiac</code>, <code>dzien_tygodnia</code>, <code>imieniny</code>, <code>swieto</code> — albo poproś o nią AI (polecenie niżej).</li><li>Na stronie wstaw teksty <code>{dzien}</code>, <code>{dzien_tygodnia}</code> i <code>Imieniny: {imieniny}</code> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"16.1\">Wstawianie pola</a>).</li><li>Kliknij puste miejsce strony i w <b>Seria</b> utwórz serię z tabelą Dni (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.2\">Nowa seria</a>) — powstanie 365 stron.</li><li>Wstaw mały tekst <code>{swieto}</code> w kolorze czerwonym i ustaw <b>Pokaż element → nie jest puste</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18.4\">Pokaż element</a>).</li><li>Numer strony i stopkę dodaj jako wzorzec (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"12.3\">Gotowe wzorce</a>).</li><li>Sprawdź podgląd i wyeksportuj PDF (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Podgląd</a>, <a href=\"#\" data-cel=\"22\">Eksport do PDF i PNG</a>).</li></ol><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Polecenie dla AI: tabela dni do kalendarza</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Kopiuj</button></div><p class=\"ciche\">Skopiuj, podmień nazwę projektu i wklej do rozmowy z AI, które ma podłączoną Makietkę (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"26\">Praca z AI</a>).</p><pre>Korzystając z łącznika Makietka, w projekcie „&lt;nazwa projektu&gt;”:\n1. Przeczytaj opis formatu (narzędzie opis_formatu) i przegląd projektu.\n2. Zrób tabelę danych „Dni 2027” z kolumnami: data, dzien, miesiac, dzien_tygodnia, swieto, kolor (kolor liczby: czarny w dni zwykłe, czerwony #c0392b w niedziele i święta).\n3. Wypełnij ją dla całego roku 2027 (polskie święta państwowe i kościelne w kolumnie swieto).\n4. Zrób stronę-wzór dnia: duża liczba {dzien} z kolorem z pola „kolor”, pod nią {dzien_tygodnia} i {miesiac}, a niżej {swieto}. Ustaw serię „Dni” z tą tabelą.\n5. Pokaż mi, ile stron powstanie, i uruchom kontrolę przed drukiem.</pre></div>"},{"id":"19.2","tytul":"Planer z obrazkiem miesiąca","html":"<ol class=\"kroki\"><li>Strony dni zrób jak w kalendarzu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"19.1\">Kalendarz książkowy</a>).</li><li>Dodaj tabelę <b>Miesiące</b> z kolumnami <code>miesiac</code> i <code>obraz</code> (nazwy plików), a zdjęcia wgraj w oknie Obrazy projektu (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.5\">Okno Obrazy projektu</a>).</li><li>W oknie serii dodaj ją jako tabelę dodatkową: <b>Nowy wiersz → gdy zmieni się kolumna „miesiac”</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"17.5\">Tabele dodatkowe</a>).</li><li>Wstaw obraz na stronie i w <b>Kolumna z nazwą pliku</b> wybierz kolumnę <code>obraz</code> tabeli Miesiące (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"18.5\">Obraz z danych</a>).</li></ol>"},{"id":"19.3","tytul":"Zaproszenia imienne","html":"<ol class=\"kroki\"><li>Projekt w formacie zaproszenia, np. 148 × 105 mm.</li><li>Tabela <b>Goście</b> z kolumną <code>imie</code> — np. wklejona z arkusza (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"15.3\">Poprawianie danych w aplikacji</a>).</li><li>Zaprojektuj zaproszenie i wpisz w tekście <code>Kochana {imie}!</code> albo <code>Drogi {imie}!</code>.</li><li>Seria z tabelą Goście — jedno zaproszenie na każdego gościa.</li><li>PDF <b>Do drukarni</b> z podziałem na pliki albo jednym plikiem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.1\">Okno eksportu</a>).</li></ol>"}]},
  {"nr":"20","tytul":"Podgląd","czesc":"Gotowa publikacja","ikona":"pdf","wstep":"Podgląd pokazuje całą publikację tak, jak wyjdzie z druku.","sekcje":[{"id":"20.1","tytul":"Otwieranie podglądu","html":"<p>Podgląd jest z danymi i powielonymi stronami, bez linii pomocniczych i bez możliwości przypadkowej zmiany. Otworzysz go przyciskiem <span class=\"ui\">Podgląd</span> na górnym pasku edytora (<kbd>Shift</kbd>+<kbd>W</kbd>) albo z menu <span class=\"ui\">⋯</span> na karcie projektu — wtedy podgląd otwiera się od razu, bez edytora.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-podglad.png\" alt=\"Podgląd na górnym pasku\" loading=\"lazy\"><figcaption>Podgląd na górnym pasku</figcaption></figure><p>Strony idą po kolei, rozkładówki stoją obok siebie. Strony serii mają podpis, np. „3 z 31”. Kliknięcie strony otwiera ją w edytorze; <span class=\"ui\">Edytor</span> albo <kbd>Esc</kbd> wraca do edycji.</p><figure><img src=\"img/instrukcja/podglad.png\" alt=\"Podgląd\" loading=\"lazy\"><figcaption>Podgląd</figcaption></figure>"},{"id":"20.2","tytul":"Powiększanie","html":"<ul class=\"punkty\"><li><span class=\"ui\">−</span> i <span class=\"ui\">+</span> na pasku; kliknięcie procentu wraca do 100%, czyli całej rozkładówki w oknie.</li><li><kbd>Ctrl</kbd> + kółko myszy powiększa w miejscu kursora.</li><li>Na telefonie i tablecie: szczypanie dwoma palcami, podwójne stuknięcie powiększa albo wraca.</li></ul>"},{"id":"20.3","tytul":"Prezentacja","html":"<p><span class=\"ui\">Prezentacja</span> pokazuje jedną stronę albo rozkładówkę naraz, na całym ekranie. Strzałki i spacja przewracają strony, <kbd>Esc</kbd> albo <span class=\"ui\">×</span> zamyka. Na telefonie przesunięcie palcem w bok przewraca stronę, w dół — zamyka prezentację.</p>"},{"id":"20.4","tytul":"Makieta 3D","html":"<p><span class=\"ui\">Makieta 3D</span> obok <span class=\"ui\">Separacje</span> na pasku podglądu pokazuje projekt jako wydrukowaną rzecz — jak zdjęcie produktu w studiu: prawdziwe wymiary stron, grubość z papieru i liczby stron, światło z cieniem na stole albo ścianie. Można ją obracać i kartkować, zanim pójdzie do drukarni.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta.png\" alt=\"Makieta 3D: otwarta książka w twardej oprawie\" loading=\"lazy\"><figcaption>Makieta 3D: otwarta książka w twardej oprawie</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Rodzaj</th><th>Jak wygląda</th></tr></thead><tbody><tr><td><b>Książka – miękka oprawa</b></td><td>Leży na stole. Okładka z sekcji okładki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>): przód, grzbiet i tył; środek kartka po kartce, otwarte strony wygięte przy grzbiecie, krawędzie kartek widać z boku. Bez sekcji okładki okładką jest pierwsza strona.</td></tr><tr><td><b>Książka – twarda oprawa</b></td><td>Okładka z tektury, większa od środka i z lekkim połyskiem, grzbiet zaokrąglony.</td></tr><tr><td><b>Notes na spirali</b></td><td>Kartki na podwójnej spirali z drutu wzdłuż grzbietu, z otworami.</td></tr><tr><td><b>Kalendarz ścienny</b></td><td>Wisi na ścianie na wieszaku; karta po karcie na spirali u góry, przewrócona karta przechodzi na tył.</td></tr><tr><td><b>Kalendarz biurkowy</b></td><td>Stoi na biurku na stojaku z grubej tektury; karty przewracają się przez górę na drugą stronę.</td></tr><tr><td><b>Pojedyncza kartka</b></td><td>Ulotka, plakat, zaproszenie — leży na stole, przód i tył.</td></tr></tbody></table></div><p>Rodzaj dobiera się sam (z okładką — książka, kalendarz z nazwy albo z 12–14 kart, jedna strona — kartka); zmienisz go listą <b>Rodzaj</b>.</p><ul class=\"punkty\"><li><b>Obracanie</b> — przeciągnij myszą albo palcem. Światło idzie razem z widokiem, a makieta nie daje się obrócić pod stół ani za ścianę.</li><li><b>Przybliżanie</b> — kółko myszy, dwa palce albo <span class=\"ui\">−</span> i <span class=\"ui\">+</span>; <span class=\"ui\">Widok</span> wraca do widoku z przodu.</li><li><b>Kartkowanie</b> — strzałki pod makietą, klawisze <kbd>←</kbd> <kbd>→</kbd> albo stuknięcie w prawą lub lewą połowę obrazu. Pod spodem widać, co jest otwarte, np. „Strony 2–3” albo „Karta 3 z 13”.</li><li><span class=\"ui\">Pobierz obraz makiety</span> zapisuje obraz PNG w dużej rozdzielczości (dłuższy bok 3200 px), z tłem studia i cieniem, w tym samym kadrze co na ekranie — np. do oferty albo wpisu w sieci. W ciemnym motywie tło jest ciemne.</li></ul><figure class=\"kadr\"><img src=\"img/instrukcja/k-makieta-kalendarz.png\" alt=\"Makieta 3D: kalendarz ścienny\" loading=\"lazy\"><figcaption>Makieta 3D: kalendarz ścienny</figcaption></figure><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> makieta pokazuje kształt i grubość publikacji z papieru i liczby stron (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>) — to podgląd, nie próbny wydruk. Kolory sprawdzisz w <span class=\"ui\">Separacje</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.6\">Podgląd separacji</a>).</p>"},{"id":"20.5","tytul":"Podgląd na żywo","html":"<p>Otwarty podgląd odświeża się sam, gdy projekt zmieni się gdzie indziej — na innym urządzeniu, u współpracownika albo przez AI. Zostaje w tym samym miejscu i powiększeniu; przerysowują się tylko zmienione strony.</p>"}]},
  {"nr":"21","tytul":"Sprawdź przed drukiem","czesc":"Gotowa publikacja","ikona":"pdf","wstep":"Lista miejsc do sprawdzenia, zanim wyślesz plik do drukarni.","sekcje":[{"id":"21.1","tytul":"Lista uwag","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Sprawdź przed drukiem</span> przegląda cały projekt — także każdą powieloną stronę.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-kontrola.png\" alt=\"Sprawdź przed drukiem w menu ⋯\" loading=\"lazy\"><figcaption>Sprawdź przed drukiem w menu ⋯</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Uwaga</th><th>Co znaczy</th></tr></thead><tbody><tr><td><b>Tekst nie mieści się w ramce</b></td><td>Na podanych stronach tekst wystaje z ramki o stałej wysokości — np. przy dłuższej wartości z tabeli.</td></tr><tr><td><b>Pole bez wartości</b></td><td>Pole z literówką albo z usuniętej kolumny.</td></tr><tr><td><b>Brak pliku obrazu</b></td><td>W tabeli jest nazwa obrazu, którego nie wgrano.</td></tr><tr><td><b>Powtórzenia</b></td><td>Ta sama wartość w kolumnie z <b>≠</b>, z numerami stron.</td></tr><tr><td><b>Wartości spoza listy</b></td><td>Wartości spoza listy kolumny z <b>☰</b>, z numerami wierszy.</td></tr><tr><td><b>Brak danych</b></td><td>Tabeli dodatkowej zabrakło wierszy przed końcem serii.</td></tr><tr><td><b>Strony serii w rozkładówkach</b></td><td>Gdzie stoją puste strony albo od której strony blok wychodzi po przeciwnej stronie.</td></tr><tr><td><b>Tabela wychodzi poza stronę</b></td><td>Wiersze urosły razem z treścią i tabela wyszła poza kartkę.</td></tr><tr><td><b>Niepełna składka</b></td><td>Sekcji brakuje stron do pełnej składki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.7\">Składki</a>); przy oprawie zeszytowej — liczba stron niepodzielna przez 4.</td></tr><tr><td><b>Pokrycie farbą</b></td><td>Kolor elementu po przeliczeniu profilem drukarni daje ponad 300% farby — po otwarciu podglądu separacji z profilem albo eksporcie PDF/X-4 (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.6\">Podgląd separacji</a>).</td></tr><tr><td><b>Element w marginesie albo poza spadem</b></td><td>Jak na liście ostrzeżeń w edytorze (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.2\">Ostrzeżenia</a>).</td></tr></tbody></table></div><p><span class=\"ui\">Pokaż</span> przy uwadze otwiera podgląd na pierwszej stronie, której uwaga dotyczy, z wyróżnioną kartką. <span class=\"ui\">Otwórz wzór</span> otwiera w edytorze stronę-wzór. Uwagi nie blokują eksportu — ta sama lista jest na dole okna eksportu PDF.</p><figure><img src=\"img/instrukcja/kontrola.png\" alt=\"Lista uwag\" loading=\"lazy\"><figcaption>Lista uwag</figcaption></figure>"}]},
  {"nr":"22","tytul":"Eksport do PDF i PNG","czesc":"Gotowa publikacja","ikona":"pdf","wstep":"Plik dla drukarni, do oglądania na ekranie albo do wydruku w domu.","sekcje":[{"id":"22.1","tytul":"Okno eksportu","html":"<p>Wybierz <span class=\"ui\">⋯</span> → <span class=\"ui\">Eksportuj do PDF…</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-pdf.png\" alt=\"Eksportuj do PDF w menu ⋯\" loading=\"lazy\"><figcaption>Eksportuj do PDF w menu ⋯</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Rodzaj pliku</b></td><td><b>Wektorowy – ostry tekst i kształty</b>: tekst z osadzonymi czcionkami, ostry w każdym powiększeniu, da się go zaznaczyć. <b>Obrazy stron – strona jako zdjęcie</b>: każda strona to jeden obraz; wygląda wszędzie tak samo, ale plik jest większy.</td></tr><tr><td><b>Zakres</b></td><td><b>Cały projekt</b>, <b>Tylko bieżąca sekcja</b> albo <b>Strony od–do</b> (numery w całym wydruku).</td></tr><tr><td><b>Przeznaczenie</b></td><td><b>Do drukarni – ze spadem i znakami cięcia</b> albo <b>Do oglądania – równo do formatu</b>. Znaki cięcia dostają sekcje, które mają je włączone (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.4\">Ustawienia sekcji</a>).</td></tr><tr><td><b>Układ arkuszy</b></td><td><b>Zwykłe strony</b> albo strony ułożone na arkuszach do samodzielnego druku (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.6\">Broszura i kilka stron na arkuszu</a>).</td></tr><tr><td><b>Jakość</b></td><td>Rozdzielczość zdjęć: 300 dpi — standard do druku, 150 dpi — mały plik na próbę, 600 dpi — bardzo ostro.</td></tr></tbody></table></div><p>Na dole okna jest lista <b>Do sprawdzenia przed drukiem</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>). <span class=\"ui\">Eksportuj</span> zapisuje plik; długi eksport przerwiesz przyciskiem <span class=\"ui\">Anuluj</span> na karcie postępu.</p><figure><img src=\"img/instrukcja/pdf.png\" alt=\"Okno eksportu\" loading=\"lazy\"><figcaption>Okno eksportu</figcaption></figure>"},{"id":"22.2","tytul":"Zaawansowane","html":"<p>Część <b>Zaawansowane</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Zamień tekst na krzywe (bez czcionek w pliku)</b></td><td>Litery stają się kształtami. Tego wymagają niektóre drukarnie; tekstu nie da się potem zaznaczyć.</td></tr><tr><td><b>Kolory tekstu i kształtów w CMYK (czarny jako sama czerń)</b></td><td>Kolory zapisane czterema farbami drukarskimi; czarny tekst idzie samą czarną farbą, więc jest ostry.</td></tr><tr><td><b>Standard dla drukarni</b></td><td><b>Bez standardu – zwykły PDF</b>, <b>PDF/X-4 – papier powlekany (FOGRA39)</b>, <b>PDF/X-4 – papier niepowlekany (FOGRA47)</b> albo <b>PDF/X-4 – profil od drukarni (plik .icc)</b> — <span class=\"ui\">Wybierz plik profilu…</span>.</td></tr><tr><td><b>Zdjęcia też w CMYK (większy plik)</b></td><td>Przy PDF/X-4: zdjęcia przeliczone na farby drukarskie przez ten sam profil.</td></tr><tr><td><b>Podział na pliki</b></td><td><b>Jeden plik</b>, <b>Osobny plik dla każdej sekcji</b> albo <b>Części po tyle stron</b> (<b>Stron w części</b>). Kilka plików dostajesz w archiwum ZIP.</td></tr><tr><td><b>Dołącz pliki czcionek użytych w projekcie</b></td><td>Do pobrania trafia ZIP z plikiem PDF i folderem <code>czcionki</code>.</td></tr><tr><td><b>PDF do czytania na ekranie: zakładki i klikalne linki</b></td><td>Zakładki i linki dla czytających na ekranie (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.7\">PDF do czytania na ekranie</a>). Domyślnie włączone; przy PDF/X-4 i układzie arkuszy niedostępne.</td></tr><tr><td><b>Uszlachetnienia</b></td><td>Gdy projekt je ma: <b>Osobne płyty w tym samym pliku PDF</b>, <b>Osobny plik PDF na każde uszlachetnienie</b> albo <b>Pomiń uszlachetnienia</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"23.4\">Uszlachetnienia w pliku PDF</a>).</td></tr></tbody></table></div>"},{"id":"22.3","tytul":"Jak wybrać ustawienia dla drukarni","html":"<p>Zapytaj drukarnię, czego wymaga:</p><ul class=\"punkty\"><li>mówi „PDF/X-4” — wybierz ten standard i papier, na którym będzie drukować,</li><li>mówi „wszystko w CMYK” — zaznacz też oba pola CMYK,</li><li>mówi „bez czcionek” albo „krzywe” — zaznacz <b>Zamień tekst na krzywe</b>,</li><li>nic nie wymaga — <b>Wektorowy</b>, <b>Do drukarni</b>, 300 dpi.</li></ul><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Plik z projektu w kolorach ekranu wygląda w druku nieco inaczej. Najpewniej zamówić wydruk próbny.</p>"},{"id":"22.4","tytul":"Czego nie da się zapisać wektorowo","html":"<p>Element z cieniem, element przycięty maską i rysunek SVG z filtrem trafiają do pliku jako obraz tego jednego elementu — reszta strony zostaje wektorowa. Tekst w czcionce, której nie da się osadzić, trafia do pliku jako krzywe. Po eksporcie aplikacja mówi, jeśli coś takiego się zdarzyło.</p>"},{"id":"22.5","tytul":"Strona jako PNG","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Pobierz bieżącą stronę jako PNG</span> zapisuje obraz otwartej strony w 300 dpi, ze spadem — np. do pokazania komuś w wiadomości.</p>"},{"id":"22.6","tytul":"Broszura i kilka stron na arkuszu","html":"<p><b>Układ arkuszy</b> w oknie eksportu kładzie strony na arkuszach — do druku na zwykłej drukarce albo w małej drukarni:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Układ</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Broszura do składania (zeszyt)</b></td><td>Strony parami, tak żeby po wydrukowaniu dwustronnym i złożeniu arkuszy na pół wyszedł zeszyt. Liczba stron dopełnia się pustymi do wielokrotności 4.</td></tr><tr><td><b>Broszura ze składek</b></td><td>To samo, ale osobno dla każdej składki po <b>Składka (stron)</b> — 4, 8, 16 albo 32 (domyślnie jak w ustawieniach sekcji, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.7\">Składki</a>). Składki zszywa się albo klei razem.</td></tr><tr><td><b>2 strony na arkuszu</b>, <b>4 strony na arkuszu</b></td><td>Kolejne strony obok siebie — np. ulotki A6 po cztery na A4.</td></tr></tbody></table></div><p><b>Arkusz</b>: <b>Dopasowany do stron</b> (dwie strony A5 → arkusz 296 × 210 mm) albo <b>A4</b> / <b>A3</b> — strony stoją pośrodku i zmniejszają się, jeśli się nie mieszczą. <b>Pełzanie (mm)</b>: w grubszej broszurze środkowe kartki po złożeniu wystają; strony na nich przesuwają się o część tej wartości w stronę grzbietu (np. 0,5–1 mm przy 40 stronach).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-pdf-arkusze.png\" alt=\"Broszura: plan arkuszy w oknie eksportu\" loading=\"lazy\"><figcaption>Broszura: plan arkuszy w oknie eksportu</figcaption></figure><p>Przy <b>Do drukarni</b> arkusze mają znaki cięcia, a broszura — przerywane znaki złamu. Strony na arkuszach stoją równo do formatu, bez spadu.</p><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Broszurę na domowej drukarce łatwiej wydrukować przez <span class=\"ui\">Drukuj w domu…</span> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"22.8\">Drukuj w domu</a>).</p>"},{"id":"22.7","tytul":"PDF do czytania na ekranie","html":"<p>Zwykły plik PDF ma od razu nawigację dla czytających na ekranie:</p><ul class=\"punkty\"><li><b>zakładki</b> w bocznym panelu czytnika — sekcje projektu, a pod nimi nagłówki (style nagłówków książki, <span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"14\">Książka: spis treści, pagina, przypisy, odsyłacze, skorowidz</a>),</li><li><b>klikalny spis treści</b> — wiersz spisu prowadzi do strony,</li><li><b>odsyłacze</b> „s. 12” prowadzą do tej strony,</li><li><b>link elementu</b> — w panelu elementu, w części <b>Inne</b>, pole <b>Link w PDF (adres strony, e-mail)</b>: kliknięcie elementu w PDF otwiera adres; kod QR z adresem strony jest klikalny sam.</li></ul><p>Linki są w pliku wektorowym; zakładki — w obu rodzajach pliku. W PDF/X-4 dla drukarni nawigacji nie ma.</p>"},{"id":"22.8","tytul":"Drukuj w domu","html":"<p>Wydruk na zwykłej drukarce: <span class=\"ui\">⋯</span> → <span class=\"ui\">Drukuj w domu…</span> albo <kbd>Ctrl</kbd>+<kbd>P</kbd> w edytorze i podglądzie. Okno samo układa strony na kartkach — nie drukuj projektu z menu przeglądarki.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-druk.png\" alt=\"Okno Drukuj w domu\" loading=\"lazy\"><figcaption>Okno Drukuj w domu</figcaption></figure><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Co znaczy</th></tr></thead><tbody><tr><td><b>Co wydrukować</b></td><td><b>Zwykły wydruk</b> (strona na kartce), <b>Broszura do złożenia</b> (kartki składane na pół i zszywane w środku – kolejność stron układa się sama), <b>2</b> albo <b>4 strony na kartce</b>.</td></tr><tr><td><b>Papier</b></td><td>A4, A3 albo Letter – kartka obraca się sama.</td></tr><tr><td><b>Rozmiar stron</b></td><td><b>Rzeczywisty</b> (strony zmniejszone tylko, gdy się nie mieszczą) albo <b>Dopasuj do kartki</b>.</td></tr><tr><td><b>Strony</b></td><td>Wszystkie, od–do albo tylko bieżąca.</td></tr><tr><td><b>W odcieniach szarości</b></td><td>Wydruk czarno-biały.</td></tr><tr><td><b>Znaki cięcia i złamu</b></td><td>Przy broszurze, którą przytniesz po zszyciu.</td></tr></tbody></table></div><p>Pod ustawieniami widać, jak strony ułożą się na kartkach. <span class=\"ui\">Drukuj</span> otwiera okno drukowania z gotowym plikiem (na telefonie plik otwiera się w nowej karcie — wybierz tam <b>Udostępnij → Drukuj</b>), a <span class=\"ui\">Pobierz PDF do druku</span> zapisuje ten sam plik.</p><ol class=\"kroki\"><li>Najpierw wydrukuj jedną kartkę na próbę.</li><li>W oknie drukarki ustaw skalę <b>Rzeczywisty rozmiar / 100%</b>.</li><li>Broszurę drukuj dwustronnie, <b>obracanie po krótszej krawędzi</b>; bez druku dwustronnego — najpierw strony nieparzyste, potem włóż stos z powrotem i wydrukuj parzyste.</li><li>Złóż kartki na pół (pierwsza na wierzchu) i zszyj w zgięciu.</li></ol>"}]},
  {"nr":"23","tytul":"Kolory dodatkowe i uszlachetnienia","czesc":"Gotowa publikacja","ikona":"pdf","sekcje":[{"id":"23.1","tytul":"Kolory dodatkowe","html":"<p>Druk to nie tylko cztery farby CMYK. Makietka zna kolory dodatkowe (np. Pantone), uszlachetnienia — lakier, złocenie, tłoczenie, biały poddruk — i druk tylko czarną farbą albo czarną z jednym kolorem. Wszystko trafia do pliku PDF tak, jak oczekuje drukarnia: każda farba na osobnej płycie.</p><p>Kolor dodatkowy drukuje się osobną, gotową farbą — dokładnie w tym odcieniu, którego potrzebujesz (np. kolor logo).</p><ol class=\"kroki\"><li><span class=\"ui\">⋯</span> → <span class=\"ui\">Kolory do druku…</span> → <span class=\"ui\">Dodaj kolor dodatkowy</span>.</li><li>Wpisz <b>Nazwę</b> dokładnie jak w drukarni albo we wzorniku, np. „PANTONE 186 C”.</li><li>Wpisz <b>C</b>, <b>M</b>, <b>Y</b>, <b>K</b> — to tylko podgląd na ekranie; drukarnia użyje swojej farby.</li></ol><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolory-druku.png\" alt=\"Okno „Kolory do druku”\" loading=\"lazy\"><figcaption>Okno „Kolory do druku”</figcaption></figure><p>Kolor dodatkowy wybierasz w każdym polu koloru — wypełnienie, obrys, tekst, fragment tekstu — w części <b>Kolory dodatkowe</b>, razem z <b>Odcieniem</b> (np. 40%).</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-kolor-dodatkowy.png\" alt=\"Kolor dodatkowy w wyborze koloru\" loading=\"lazy\"><figcaption>Kolor dodatkowy w wyborze koloru</figcaption></figure><p>Zmiana CMYK koloru dodatkowego zmienia wszystkie elementy w tym kolorze. Usunięcie koloru zostawia elementy w zwykłym kolorze CMYK.</p>"},{"id":"23.2","tytul":"Uszlachetnienia","html":"<p>Uszlachetnienie ustawiasz przy elemencie, w części <b>Uszlachetnienie</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Uszlachetnienie</th><th>Co to jest</th><th>Płyta w PDF</th></tr></thead><tbody><tr><td><b>Lakier UV wybiórczy</b></td><td>Błyszczący lakier tylko w tym miejscu, np. na tytule.</td><td>Spot_UV</td></tr><tr><td><b>Złocenie (folia)</b></td><td>Metaliczna folia; <b>Kolor folii</b>: złoto, srebro albo miedź.</td><td>Foil_Gold, Foil_Silver, Foil_Copper</td></tr><tr><td><b>Tłoczenie (wypukłe)</b></td><td>Wzór wypchnięty w papierze.</td><td>Emboss</td></tr><tr><td><b>Wytłoczenie (wklęsłe)</b></td><td>Wzór wciśnięty w papier.</td><td>Debossing</td></tr><tr><td><b>Biały poddruk</b></td><td>Biała farba — na kolorowym albo przezroczystym podłożu.</td><td>White</td></tr></tbody></table></div><figure class=\"kadr\"><img src=\"img/instrukcja/k-uszlachetnienie.png\" alt=\"Uszlachetnienie w panelu elementu\" loading=\"lazy\"><figcaption>Uszlachetnienie w panelu elementu</figcaption></figure><p>Element z uszlachetnieniem drukuje się <b>tylko</b> na płycie uszlachetnienia — jego kolory nie idą do druku. Żeby mieć napis w kolorze i ze złoceniem, zaznacz napis i w <b>Dodaj kopię z uszlachetnieniem</b> wybierz złocenie: kopia stanie dokładnie nad napisem.</p><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Uszlachetnienie na bardzo drobnym tekście (poniżej 6 pt) i cienkich liniach (poniżej 0,3 mm) może się nie odwzorować. <b>Sprawdź przed drukiem</b> o tym przypomni (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>).</p>"},{"id":"23.3","tytul":"Widok uszlachetnień","html":"<p>W edytorze i podglądzie uszlachetnienie widać jako efekt: połysk lakieru, metaliczną folię, cień tłoczenia, biel na szachownicy. Menu widoku → <b>Pokaż uszlachetnienia</b> wyłącza efekt (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.6\">Prawy dolny róg i menu widoku</a>).</p>"},{"id":"23.4","tytul":"Uszlachetnienia w pliku PDF","html":"<p>W pliku wektorowym każde uszlachetnienie to osobna płyta z <b>nadrukiem</b> — nie wybija farby pod spodem. W oknie eksportu, w części <b>Zaawansowane</b>, wybierz <b>Uszlachetnienia</b>:</p><ul class=\"punkty\"><li><b>Osobne płyty w tym samym pliku PDF</b> — najczęstsze,</li><li><b>Osobny plik PDF na każde uszlachetnienie</b> — główny plik bez uszlachetnień i osobny plik każdej płyty, w jednym ZIP,</li><li><b>Pomiń uszlachetnienia</b>.</li></ul><p>Plik z obrazów stron nie ma osobnych płyt — wybierz plik wektorowy.</p>"},{"id":"23.5","tytul":"Tryb kolorów projektu","html":"<p><span class=\"ui\">⋯</span> → <span class=\"ui\">Kolory do druku…</span> → <b>Tryb kolorów projektu</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Tryb</th><th>Kiedy</th></tr></thead><tbody><tr><td><b>Pełny kolor</b></td><td>Zwykły druk CMYK (domyślnie).</td></tr><tr><td><b>Skala szarości</b></td><td>Druk jedną czarną farbą — kolory i zdjęcia idą odcieniami czerni.</td></tr><tr><td><b>Cz/b + 1 kolor</b></td><td>Czerń i jeden kolor dodatkowy, np. kalendarz z czerwonymi niedzielami. <b>Kolor dodatkowy trybu</b> wybierasz pod spodem.</td></tr></tbody></table></div><p>W wyborze koloru zostają wtedy odcienie czerni i kolor trybu. Kolory spoza trybu okno pokaże — <span class=\"ui\">Zamień na najbliższe dozwolone</span> zamieni je na czerń albo kolor trybu. To samo zrobi przycisk w <b>Sprawdź przed drukiem</b>.</p><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Rozszerzony CMYK (CMYK z dodatkowymi farbami, np. pomarańczową, zieloną i fioletową) robi drukarnia sama z Twojego pliku — nie trzeba osobnej palety.</p>"},{"id":"23.6","tytul":"Podgląd separacji","html":"<p>W podglądzie projektu <span class=\"ui\">Separacje</span> pokazuje stronę rozbitą na płyty, którymi wydrukuje ją drukarnia: <b>Cyjan</b>, <b>Magenta</b>, <b>Żółty</b>, <b>Czarny</b>, kolory dodatkowe i uszlachetnienia.</p><figure><img src=\"img/instrukcja/separacje.png\" alt=\"Podgląd separacji: kolor dodatkowy i lakier UV z nadrukiem\" loading=\"lazy\"><figcaption>Podgląd separacji: kolor dodatkowy i lakier UV z nadrukiem</figcaption></figure><ol class=\"kroki\"><li>Strzałkami nad obrazem przechodzisz między stronami.</li><li>Odznacz płytę, żeby zobaczyć stronę bez niej; zostaw jedną i zaznacz <b>Jedna płyta w szarości</b> — zobaczysz samą farbę tej płyty (czarne = 100%).</li><li><b>Pokaż nadruk uszlachetnień</b> — uszlachetnienia jako kreskowana nakładka nad farbą (drukują się z nadrukiem, nie wybijają farby pod spodem).</li><li><b>Zaznacz pokrycie farbą ponad</b> <b>Limit pokrycia (%)</b> — miejsca, gdzie suma farb przekracza limit (zwykle 300% dla papieru powlekanego), robią się czerwone. Pod spodem jest największe pokrycie na stronie.</li></ol><p><b>Przeliczanie na CMYK</b>: <b>Proste</b> — tak jak plik wektorowy w CMYK bez profilu (czerń i szarości samą czernią; nie przekracza 300%); <b>Papier powlekany (FOGRA39)</b> albo <b>Papier niepowlekany (FOGRA47)</b> — tak, jak przeliczy profil drukarni. Po przeliczeniu profilem <b>Sprawdź przed drukiem</b> wskaże też kolory elementów z pokryciem farbą powyżej 300% (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>).</p>"}]},
  {"nr":"24","tytul":"Udostępnianie linkiem","czesc":"Gotowa publikacja","ikona":"pdf","wstep":"Link do podglądu dla osób bez konta — klienta, rodziny, drukarni.","sekcje":[{"id":"24.1","tytul":"Tworzenie linku","html":"<p>Osoba z linkiem widzi strony tak jak w podglądzie; nie może niczego zmienić i nie widzi innych Twoich projektów.</p><ol class=\"kroki\"><li>W podglądzie kliknij <span class=\"ui\">Udostępnij</span>.</li><li><span class=\"ui\">Utwórz link</span> — aplikacja przygotuje obrazy wszystkich stron; przy dużym projekcie chwilę to potrwa.</li><li>Skopiuj link i wyślij go.</li></ol><div class=\"galeria\"><figure class=\"kadr\"><img src=\"img/instrukcja/k-udostepnij.png\" alt=\"Udostępnij w podglądzie\" loading=\"lazy\"><figcaption>Udostępnij w podglądzie</figcaption></figure><figure><img src=\"img/instrukcja/udostepnianie.png\" alt=\"Okno Udostępnij podgląd\" loading=\"lazy\"><figcaption>Okno Udostępnij podgląd</figcaption></figure></div><p>Projekt z linkiem ma na liście projektów plakietkę <b>Udostępniony</b> — kliknięcie otwiera to samo okno.</p>"},{"id":"24.2","tytul":"Aktualizacja","html":"<p>Link aktualizuje się sam: kilka sekund po Twoich zmianach aplikacja wysyła obrazy stron, które się zmieniły. Adres zostaje ten sam. <span class=\"ui\">Aktualizuj teraz</span> robi to od razu. Osoba, która ma link otwarty, nie musi odświeżać strony — nowe strony pojawią się same.</p><p>Obrazy stron przygotowuje aplikacja, więc link nadąża za zmianami, gdy projekt jest otwarty — w edytorze albo w podglądzie, na dowolnym urządzeniu.</p>"},{"id":"24.3","tytul":"Ochrona linku","html":"<p>Część <b>Ochrona linku</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Hasło – bez niego podglądu nie zobaczy nikt</b></td><td>Osoba z linkiem najpierw wpisuje <b>Hasło do linku</b>. Po 10 błędnych próbach link na kwadrans przestaje przyjmować hasła.</td></tr><tr><td><b>Ważny do wybranego dnia</b></td><td>Po <b>Ostatnim dniu ważności</b> link przestaje działać.</td></tr></tbody></table></div><p><span class=\"ui\">Zapisz ochronę</span> zapisuje ustawienia. Puste pole hasła przy zaznaczonym haśle zostawia dotychczasowe; odznaczenie obu pól zdejmuje ochronę.</p>"},{"id":"24.4","tytul":"Unieważnienie linku","html":"<p><span class=\"ui\">Unieważnij link</span> usuwa udostępnione strony — stary adres od razu przestaje działać. Ponowne udostępnienie daje nowy adres.</p><p class=\"ramka-instrukcji uwaga\"><b>Uwaga.</b> Link jest długi i losowy, więc nie da się go zgadnąć, ale każdy, kto go dostanie, może go przekazać dalej. Do poufnych projektów ustaw hasło.</p>"}]},
  {"nr":"25","tytul":"Współpraca","czesc":"Razem z innymi","ikona":"uzytkownik","wstep":"Wspólna praca nad projektem: zaproszenia, role i komentarze.","sekcje":[{"id":"25.1","tytul":"Zapraszanie","html":"<p>Każda osoba pracuje na swoim koncie, a zmiany widać u wszystkich na żywo. Wybierz <span class=\"ui\">⋯</span> → <span class=\"ui\">Współpraca…</span> w edytorze albo na karcie projektu.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-menu-wspolpraca.png\" alt=\"Współpraca w menu ⋯\" loading=\"lazy\"><figcaption>Współpraca w menu ⋯</figcaption></figure><p>W części <b>Zaproś osobę</b>:</p><ol class=\"kroki\"><li>W polu <b>E-mail albo nazwa użytkownika</b> wpisz adres albo nazwę — po dwóch literach pojawią się pasujące nazwy użytkowników.</li><li>Wybierz <b>Rolę</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.2\">Role</a>).</li><li>Kliknij <span class=\"ui\">Zaproś</span>.</li></ol><p>Aplikacja wysyła e-mail z linkiem do zaproszenia. Link możesz też skopiować i wysłać sam. Przy zaproszeniu po nazwie nie widzisz adresu e-mail tej osoby.</p><figure><img src=\"img/instrukcja/wspolpraca.png\" alt=\"Okno Współpraca\" loading=\"lazy\"><figcaption>Okno Współpraca</figcaption></figure>"},{"id":"25.2","tytul":"Role","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Rola</th><th>Co może</th></tr></thead><tbody><tr><td><b>może edytować</b></td><td>Zmienia strony, dane, wzorce i style; eksportuje PDF.</td></tr><tr><td><b>może oglądać</b></td><td>Otwiera projekt tylko w podglądzie.</td></tr><tr><td><b>Właściciel</b></td><td>Wszystko powyższe, a do tego zaprasza, zmienia role, odbiera dostęp, udostępnia link do podglądu i usuwa projekt.</td></tr></tbody></table></div>"},{"id":"25.3","tytul":"Przyjmowanie zaproszenia","html":"<p>Kliknij link z wiadomości. Jeśli masz konto, zaproszenie zobaczysz też w aplikacji: na liście projektów pojawi się przycisk <span class=\"ui\">Zaproszenia</span> z liczbą. Przyjęty projekt jest na Twojej liście z plakietką właściciela.</p><p>Zaproszenie przyjmuje osoba, która ma link — także z innego adresu niż ten, na który poszło. W oknie Współpraca zawsze widać, kto naprawdę jest w projekcie.</p><p>Z włączonymi powiadomieniami (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.6\">Powiadomienia</a>) dowiesz się o zaproszeniu od razu.</p>"},{"id":"25.4","tytul":"Praca na żywo","html":"<ul class=\"punkty\"><li>Zmiany łączą się element po elemencie: gdy Ty poprawiasz tytuł, a ktoś przesuwa zdjęcie, zostają obie zmiany. O ten sam element aplikacja zapyta (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"3.5\">Kilka urządzeń i cofanie</a>).</li><li>Kółka z inicjałami na pasku edytora i podglądu pokazują, kto jeszcze ma projekt otwarty; wskaż kółko, żeby zobaczyć, na której jest stronie.</li><li><span class=\"ui\">Cofnij</span> cofa tylko Twoje zmiany.</li></ul>"},{"id":"25.5","tytul":"Zarządzanie osobami","html":"<p>Właściciel w oknie Współpraca przy każdej osobie:</p><ul class=\"punkty\"><li>zmienia <b>rolę</b> na liście rozwijanej,</li><li><span class=\"ui\">Odbierz</span> — odbiera dostęp od razu; zmiany, które ta osoba już zapisała, zostają,</li><li>przy zaproszeniu, które czeka: <span class=\"ui\">Kopiuj link zaproszenia</span>, <span class=\"ui\">Wyślij e-mail z zaproszeniem ponownie</span> i <span class=\"ui\">Cofnij zaproszenie</span>.</li></ul>"},{"id":"25.6","tytul":"Opuszczanie projektu i kopia","html":"<p>Współpracownik może <span class=\"ui\">Opuść projekt</span> — w menu <span class=\"ui\">⋯</span> na karcie albo w oknie Współpraca. <span class=\"ui\">Zrób własną kopię</span> tworzy Twój własny projekt z tą samą treścią.</p>"},{"id":"25.7","tytul":"Komentarze","html":"<p>Komentarz to uwaga przypięta do miejsca na stronie albo do elementu — jak karteczka na wydruku — widoczna jako pomarańczowa pinezka z numerem. Komentować mogą wszyscy w projekcie, także z rolą <b>może oglądać</b> (w podglądzie). Komentarzy nie ma w PDF.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-komentarz-narzedzie.png\" alt=\"Narzędzie Komentarz i przycisk Komentarze z licznikiem\" loading=\"lazy\"><figcaption>Narzędzie Komentarz i przycisk Komentarze z licznikiem</figcaption></figure><p><b>Dodanie komentarza</b></p><ol class=\"kroki\"><li>Kliknij <span class=\"ui\">Komentarz</span> na pasku narzędzi (w podglądzie: <span class=\"ui\">Komentarze</span> → <span class=\"ui\">Nowy komentarz</span>).</li><li>Kliknij miejsce na stronie. Jeśli najpierw zaznaczysz element, komentarz od razu przypnie się do niego.</li><li>Wpisz treść i kliknij <span class=\"ui\">Dodaj komentarz</span> (albo Ctrl+Enter). Esc rezygnuje.</li></ol><p>Wpisz <b>@</b> i początek nazwy, żeby wspomnieć osobę z projektu — aplikacja podpowie nazwy.</p><p><b>Lista komentarzy</b></p><p><span class=\"ui\">Komentarze</span> na górnym pasku edytora i w podglądzie pokazuje liczbę nierozwiązanych wątków. Kliknięcie pinezki otwiera jej wątek.</p><figure><img src=\"img/instrukcja/komentarze.png\" alt=\"Panel Komentarze z wątkiem i odpowiedzią\" loading=\"lazy\"><figcaption>Panel Komentarze z wątkiem i odpowiedzią</figcaption></figure><ul class=\"punkty\"><li>Filtry: <b>Nierozwiązane</b>, <b>Wszystkie</b>, <b>Moje</b> (moje wątki, moje odpowiedzi i wzmianki o mnie).</li><li>W wątku są odpowiedzi, <span class=\"ui\">Odpowiedz</span> i <span class=\"ui\">Pokaż na stronie</span>.</li><li><span class=\"ui\">Rozwiąż</span> zamyka załatwiony wątek i chowa pinezkę; <span class=\"ui\">Otwórz ponownie</span> (filtr <b>Wszystkie</b>) go przywraca.</li><li>Własny komentarz poprawisz ołówkiem <span class=\"ui\">Popraw</span> (dopisek „(poprawiony)”); <kbd>Ctrl</kbd>+<kbd>Enter</kbd> zapisuje i wysyła.</li><li>Usunąć komentarz może autor albo właściciel projektu — znika u wszystkich od razu, z odpowiedziami.</li><li>Komentarz przy elemencie idzie za elementem; gdy element usuniesz, pinezka zostaje w tym miejscu. Wątek z usuniętej strony zostaje na liście z opisem „strona usunięta”.</li><li>Komentarze dodaje się na stronach, nie na wzorcach.</li></ul><p>Komentarze pojawiają się u wszystkich od razu; odpowiedź, którą piszesz, nie znika, gdy ktoś coś doda. O nowych dowiesz się też z powiadomień (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"2.6\">Powiadomienia</a>).</p><p>AI połączone kluczem też czyta komentarze, odpowiada na nie i może je rozwiązać po poprawce (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"26.1\">Co potrafi AI</a>).</p>"}]},
  {"nr":"26","tytul":"Praca z AI","czesc":"Razem z innymi","ikona":"uzytkownik","wstep":"Asystent AI może budować i zmieniać Twoje projekty razem z Tobą.","sekcje":[{"id":"26.1","tytul":"Co potrafi AI","html":"<p>Asystent AI (Claude, ChatGPT i inne) łączy się z Makietką przez <b>łącznik</b>: adres z Twoim kluczem, który dodajesz w aplikacji AI.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>AI może</th><th>AI nie może</th></tr></thead><tbody><tr><td>tworzyć i usuwać projekty (z pełnym dostępem)</td><td>zobaczyć projektów spoza klucza</td></tr><tr><td>dodawać i zmieniać strony, elementy, style i wzorce</td><td>zmienić Twojego konta ani hasła</td></tr><tr><td>wypełniać tabele danych i ustawiać serie</td><td>wyeksportować PDF — plik robisz sam</td></tr><tr><td>wgrywać, wstawiać i wymieniać zdjęcia</td><td></td></tr><tr><td>czytać komentarze, odpowiadać na nie i dodawać własne (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.7\">Komentarze</a>)</td><td></td></tr></tbody></table></div><p>Pisz do AI zwyczajnie, jak do grafika: co chcesz zrobić, w jakim formacie, ile stron, jaki nastrój. Jeśli masz projekt otwarty, zmiany pojawiają się w edytorze po chwili. Zmiany AI łączą się z Twoimi jak zmiany współpracownika (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"25.4\">Praca na żywo</a>).</p>"},{"id":"26.2","tytul":"Klucz dla AI","html":"<p>Klucz należy do konta: <span class=\"ui\">Ustawienia konta</span> → <b>Dostęp dla AI</b> → <span class=\"ui\">Zarządzaj…</span>.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-konto-ai.png\" alt=\"Dostęp dla AI w ustawieniach konta\" loading=\"lazy\"><figcaption>Dostęp dla AI w ustawieniach konta</figcaption></figure><p>Część <b>Nowy klucz</b>:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Ustawienie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Opis (dla Ciebie)</b></td><td>Np. „Claude – kalendarz”.</td></tr><tr><td><b>AI może</b></td><td><b>czytać i zmieniać</b> albo <b>tylko czytać</b>.</td></tr><tr><td><b>Ważny przez</b></td><td>1 dzień, 7 dni, 30 dni, 90 dni, rok albo bez terminu.</td></tr><tr><td><b>Wybrane projekty</b></td><td>Projekty, do których klucz daje dostęp — Twoje i udostępnione Ci.</td></tr><tr><td><b>Pełny dostęp – wszystkie projekty, także tworzenie i usuwanie</b></td><td>Także projekty, które dojdą później. Usunięcie projektu AI zawsze potwierdza nazwą.</td></tr></tbody></table></div><p><span class=\"ui\">Utwórz klucz</span> pokazuje <b>Adres łącznika</b> — widać go tylko raz, skopiuj go od razu.</p><p>Lista <b>Klucze konta</b> pokazuje zakres, ważność i ostatnie użycie każdego klucza. <span class=\"ui\">Zmień zakres</span> dodaje albo usuwa projekty albo przełącza na pełny dostęp — adres łącznika się nie zmienia. <span class=\"ui\">Odbierz</span> wyłącza klucz od razu.</p><figure><img src=\"img/instrukcja/dostep-ai.png\" alt=\"Okno Dostęp dla AI\" loading=\"lazy\"><figcaption>Okno Dostęp dla AI</figcaption></figure>"},{"id":"26.3","tytul":"Podłączenie w aplikacji AI","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Aplikacja</th><th>Jak podłączyć</th></tr></thead><tbody><tr><td><b>Claude</b> (claude.ai, aplikacja na komputer i telefon)</td><td><b>Ustawienia → Łączniki → Dodaj własny łącznik</b>, nazwa „Makietka”, wklej adres. W rozmowie włącz łącznik w menu narzędzi.</td></tr><tr><td><b>Claude Desktop</b></td><td>W oknie Dostęp dla AI: <span class=\"ui\">Pobierz rozszerzenie dla Claude Desktop</span>, kliknij pobrany plik dwa razy i wklej klucz. Rozszerzenie czyta też pliki z Twojego dysku.</td></tr><tr><td><b>ChatGPT</b></td><td><b>Ustawienia → Aplikacje → Dodaj własny serwer MCP</b>, wklej adres, uwierzytelnianie: brak.</td></tr><tr><td><b>Claude Code</b> i inne programy z MCP</td><td>Polecenie z części <b>Dla zaawansowanych</b> w oknie Dostęp dla AI.</td></tr></tbody></table></div><p>Sprawdzenie: napisz do AI „Pokaż moje projekty w Makietce”.</p><p>Najprościej skopiować polecenie „Podłącz Makietkę” i wkleić je do rozmowy — AI rozpozna, w jakiej aplikacji jesteś, i powie, co kliknąć:</p><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Polecenie „Podłącz Makietkę”</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Kopiuj</button></div><p class=\"ciche\">Wklej do rozmowy z AI – poprowadzi Cię przez podłączenie w Twojej aplikacji.</p><pre>Pomóż mi podłączyć Makietkę do Ciebie jako łącznik (serwer MCP), krok po kroku.\n\nCo to jest Makietka: aplikacja w przeglądarce (https://makietka.app) do składania publikacji do druku – kalendarzy, planerów, notesów, zeszytów, komiksów. Ma strony, wzorce, style tekstu, tabele danych, serie powielanych stron, obrazy i eksport PDF.\n\nCo wiem o łączniku Makietki:\n- To zdalny serwer MCP (transport Streamable HTTP), bez logowania OAuth. Adres: https://api.makietka.app/mcp/&lt;klucz&gt;. Klucz można też podać nagłówkiem „Authorization: Bearer sdk_…” (wtedy adres bez klucza: https://api.makietka.app/mcp).\n- Klucz tworzę sam w Makietce: Ustawienia konta → Dostęp dla AI → Zarządzaj… Wybieram: które projekty (albo pełny dostęp – wtedy AI może też tworzyć i usuwać projekty), czy AI tylko czyta, czy też zmienia, i ważność. Adres z kluczem widać tylko raz.\n- Narzędzia łącznika: lista projektów, nowy projekt i usunięcie projektu (przy pełnym dostępie), przegląd projektu, czytanie i zmiana stron, elementów, wzorców, stylów, tabel danych i serii, wgrywanie obrazów (adres https, link z Dysku Google albo Dropboxa, kod SVG, małe pliki kawałkami), wstawianie obrazów na strony, link do wgrania zdjęć przez przeglądarkę, kontrola przed drukiem.\n- Opis dla AI: https://makietka.app/ai/api.md, model danych projektu: https://makietka.app/ai/format-makietka.md.\n- Dla Claude Desktop jest też rozszerzenie https://makietka.app/ai/mcp/makietka.mcpb – działa na komputerze i czyta pliki oraz foldery z dysku.\n- Claude Code: claude mcp add --transport http makietka https://api.makietka.app/mcp/&lt;klucz&gt;\n\nTwoje zadanie:\n1. Ustal, w jakiej aplikacji teraz rozmawiamy (claude.ai w przeglądarce, aplikacja Claude na telefonie, Claude Desktop, Claude Code, ChatGPT, Cursor albo inna) i czy na moim planie da się w niej dodać własny łącznik MCP. Jeśli nie wiesz – zapytaj mnie.\n2. Poprowadź mnie po kolei, co kliknąć, żeby dodać łącznik o nazwie „Makietka” z moim adresem. Nie proś mnie o wklejenie klucza do tej rozmowy – wkleję go sam w ustawieniach.\n3. Jeśli ta aplikacja albo mój plan nie obsługuje łączników, powiedz to wprost i zaproponuj najprostszą drogę (inna aplikacja, Claude Desktop z rozszerzeniem, Claude Code).\n4. Po podłączeniu sprawdź, czy widzisz narzędzie „projekty”, i pokaż mi listę moich projektów.\nPisz prosto, po polsku, jeden krok na raz i czekaj, aż powiem, że zrobione.</pre></div><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Łączniki są zwykle w płatnych planach aplikacji AI. Na telefonie można zwykle tylko używać łączników dodanych wcześniej na komputerze.</p>"},{"id":"26.4","tytul":"Zdjęcia przez AI","html":"<ul class=\"punkty\"><li><b>ChatGPT</b> bierze zdjęcia wrzucone do rozmowy wprost.</li><li><b>Claude</b> wgrywa sam małe grafiki z rozmowy; <b>Claude Desktop z rozszerzeniem</b> — pliki i foldery z dysku.</li><li><b>Zawsze działa link do wgrania:</b> poproś AI o link — otworzy ten projekt z oknem Obrazy projektu, wrzucasz tam zdjęcia albo ZIP, a AI widzi je i działa dalej.</li><li>AI pobierze też obraz z adresu w internecie albo z linku do Dysku Google czy Dropboxa udostępnionego „każdemu, kto ma link”, i narysuje własną grafikę SVG.</li></ul><p>Zdjęcia, które stoi na stronie, AI nie usuwa — wymienia je na nowy plik w tym samym miejscu.</p>"},{"id":"26.5","tytul":"Bezpieczeństwo","html":"<p>AI dostaje co najwyżej Twoje uprawnienia: w projekcie, który możesz tylko oglądać, klucz tylko czyta, a gdy właściciel odbierze Ci dostęp, klucz traci go od razu.</p><p class=\"ramka-instrukcji uwaga\"><b>Uwaga.</b> Adres łącznika zawiera klucz — kto go ma, ma dostęp do wybranych projektów. Nie publikuj go, dawaj najkrótszą ważność, jaka wystarczy, i odbieraj klucz po skończonej pracy.</p>"}]},
  {"nr":"27","tytul":"Przykład: komiks z AI","czesc":"Razem z innymi","ikona":"uzytkownik","sekcje":[{"id":"27.1","tytul":"Od pomysłu do pliku","html":"<p>Zeszyt A5 z okładką: AI układa kadry i dymki, Ty dajesz rysunki i decydujesz.</p><ol class=\"kroki\"><li>Utwórz klucz z <b>pełnym dostępem</b> i <b>czytać i zmieniać</b> — AI utworzy nowy projekt (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"26.2\">Klucz dla AI</a>).</li><li>Skopiuj polecenie „Komiks do druku” (niżej), dopisz pomysł i wyślij. AI najpierw pokaże plan stron — popraw go, zanim zacznie.</li><li>Otwórz nowy projekt — zobaczysz, jak przybywa stron, kadrów i dymków.</li><li>Poproś AI o link do wgrania i wrzuć rysunki (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"26.4\">Zdjęcia przez AI</a>). AI wstawi je w kadry.</li><li>Popraw, co chcesz: tekst w dymkach (styl „Dymek” zmienia wszystkie naraz), kadrowanie, kolejność stron.</li><li>Okładkę zrób jako osobną sekcję z grzbietem (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.6\">Okładka z grzbietem</a>).</li><li><span class=\"ui\">Sprawdź przed drukiem</span>, potem PDF <b>Do drukarni</b> (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"21\">Sprawdź przed drukiem</a>, <a href=\"#\" data-cel=\"22\">Eksport do PDF i PNG</a>).</li></ol><div class=\"prompt-instrukcji\"><div class=\"prompt-naglowek\"><b>Polecenie „Komiks do druku”</b><button type=\"button\" class=\"przycisk\" data-kopiuj-prompt data-ikona=\"kopiuj\">Kopiuj</button></div><p class=\"ciche\">Skopiuj, dopisz pomysł na końcu i wyślij AI z podłączoną Makietką.</p><pre>Korzystając z łącznika Makietka, przygotuj ze mną komiks do druku.\n\n1. Najpierw zaproponuj plan: tytuł, liczbę stron (domyślnie 8 stron środka + okładka), na każdej stronie liczbę kadrów i co się w nich dzieje. Poczekaj, aż zatwierdzę.\n2. Potem utwórz nowy projekt „Komiks – &lt;tytuł&gt;”: format A5 (148×210 mm), spad 3 mm, marginesy 8 mm. Środek w rozkładówkach, okładka jako osobna sekcja.\n3. Na stronach ułóż kadry: prostokąty z czarnym obrysem 0,6 mm i odstępem 4 mm między kadrami, w obrębie marginesów. W kadrach dymki (elipsy albo prostokąty z zaokrągleniem, białe wypełnienie, czarny obrys) z tekstem 9 pt, wyśrodkowanym. Narrację umieść w prostokątnych ramkach u góry kadru.\n4. Zrób styl tekstu „Dymek” i „Narracja”, żebym mógł je potem zmienić naraz.\n5. Rysunków nie wymyślaj na siłę: jeśli nie możesz ich narysować, w każdym kadrze zostaw szary prostokąt z krótkim opisem sceny. Ja wgram rysunki – daj mi link do wgrania obrazów, a potem wstaw je w kadry z dopasowaniem „wypełnij”.\n6. Dodaj numery stron we wzorcu (pole {nr}) na dole, po zewnętrznej stronie.\n7. Na koniec uruchom kontrolę przed drukiem i powiedz, co poprawić.\n\nMój pomysł na komiks: &lt;opisz tutaj bohaterów, historię i nastrój&gt;</pre></div><p class=\"ramka-instrukcji wskazowka\"><b>Wskazówka.</b> Zeszyt zszywany ma liczbę stron podzielną przez 4 (8, 12, 16…). Rysunki do druku przygotuj w co najmniej 300 dpi w rozmiarze kadru.</p>"}]},
  {"nr":"28","tytul":"Telefon i tablet","czesc":"Urządzenia i pomoc","ikona":"motyw","wstep":"Jak pracować na ekranie dotykowym i jak zainstalować aplikację.","sekcje":[{"id":"28.1","tytul":"Gesty","html":"<p>Na ekranie dotykowym:</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Gest</th><th>Co robi</th></tr></thead><tbody><tr><td><b>Jeden palec</b></td><td>Zaznacza i przesuwa elementy.</td></tr><tr><td><b>Dwa palce</b></td><td>Przesuwają widok i powiększają.</td></tr><tr><td><b>Szybkie przesunięcie w bok</b></td><td>Po pustym miejscu strony, gdy cała strona mieści się na ekranie: w lewo – następna strona, w prawo – poprzednia (przy rozkładówce cały arkusz). Wolne przeciągnięcie zaznacza ramką jak zwykle.</td></tr><tr><td><b>Dwa szybkie stuknięcia</b></td><td>Jak podwójne kliknięcie: pisanie w tekście i komórce tabeli, wejście do grupy, edycja punktów.</td></tr><tr><td><b>Przytrzymanie</b></td><td>Pokazuje podpowiedź, np. opis chmurki zapisu.</td></tr></tbody></table></div><p>W podglądzie szczypanie powiększa, a w prezentacji przesunięcie w bok przewraca stronę (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"20\">Podgląd</a>).</p>"},{"id":"28.2","tytul":"Edytor na telefonie","html":"<p>Na telefonie edytor działa w pionie. Panele <b>Strony</b>, <b>Właściwości</b>, <b>Warstwy</b> i <b>Ostrzeżenia</b> otwierasz przyciskami na dole ekranu. Panel wysuwa się z dołu, a widok sam przesuwa się tak, żeby zaznaczony element był widoczny nad panelem.</p><p><b>Uchwyt</b> (kreska u góry panelu): pociągnij w górę, żeby powiększyć panel, w dół — żeby go zmniejszyć albo zamknąć. Stuknięcie w uchwyt zwija powiększony panel do zwykłej wysokości, a zwykły zamyka. Panel zamyka też ponowne stuknięcie jego przycisku.</p><p>Rzadsze narzędzia — wielokąt, rysowanie, pióro, komentarz, kopiowanie wyglądu — są pod <span class=\"ui\">⋯</span> na końcu paska wstawiania (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"4.4\">Pasek wstawiania</a>). Linijek i kadrowania ramką na telefonie nie ma: prowadnice wpiszesz liczbą (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"13.4\">Linijki i prowadnice</a>), a obraz przytniesz liczbami we właściwościach (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"8.2\">Kadrowanie</a>).</p><p>Telefon trzymany poziomo pokazuje planszę „Za mało miejsca na wysokość” — obróć go do pionu.</p><figure class=\"telefon\"><img src=\"img/instrukcja/telefon.png\" alt=\"Edytor na telefonie\" loading=\"lazy\"><figcaption>Edytor na telefonie</figcaption></figure>"},{"id":"28.3","tytul":"Okna od dołu","html":"<p>Na telefonie i tablecie okna (Dane, Wzorce, Eksport do PDF, Obrazy projektu i inne) wysuwają się od dołu ekranu. Zamiast krzyżyka mają <b>uchwyt</b> — pociągnij go w dół albo stuknij, żeby zamknąć; zamyka też stuknięcie w przyciemnione tło. Główny przycisk okna jest na dole, zawsze widoczny. Ten sam uchwyt mają listy wyboru, wybór koloru i daty, które na telefonie też wysuwają się od dołu — stuknięcie poza nimi albo w uchwyt je chowa. Małe menu (⋯, widok) rozwijają się pod przyciskiem i chowają się po stuknięciu obok.</p><figure class=\"telefon\"><img src=\"img/instrukcja/telefon-zaslonka.png\" alt=\"Okno na telefonie\" loading=\"lazy\"><figcaption>Okno na telefonie</figcaption></figure>"},{"id":"28.4","tytul":"Instalacja aplikacji","html":"<p>Zainstalowana Makietka otwiera się z ekranu głównego jak zwykła aplikacja — na całym ekranie, bez paska przeglądarki.</p><div class=\"tabela-instrukcji\"><table><thead><tr><th>Urządzenie</th><th>Jak zainstalować</th></tr></thead><tbody><tr><td><b>Android</b> (Chrome)</td><td><span class=\"ui\">Zainstaluj aplikację</span> w menu konta albo w menu przeglądarki ⋮.</td></tr><tr><td><b>iPhone i iPad</b> (Safari)</td><td><span class=\"ui\">Zainstaluj aplikację</span> pokaże kroki: <b>Udostępnij → Do ekranu początkowego</b>.</td></tr><tr><td><b>Komputer</b> (Chrome, Edge)</td><td>Ikona instalacji w pasku adresu albo <span class=\"ui\">Zainstaluj aplikację</span>. W Safari na Macu: <b>Plik → Dodaj do Docka</b>.</td></tr></tbody></table></div><p>Zainstalowana aplikacja na komputerze otwiera pliki <code>.makietka</code> dwuklikiem.</p>"},{"id":"28.5","tytul":"Pełny ekran","html":"<p><span class=\"ui\">Pełny ekran</span> (cztery narożniki) na liście projektów, w edytorze i w podglądzie chowa paski przeglądarki; <kbd>Esc</kbd> albo ten sam przycisk wraca. Na iPhonie przeglądarka nie pozwala na pełny ekran — tam daje go zainstalowanie aplikacji (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"28.4\">Instalacja aplikacji</a>).</p>"},{"id":"28.6","tytul":"Dłuższe czynności","html":"<p>Gdy coś trwa dłużej niż chwilę — np. otwieranie dużego projektu, eksport PDF, druk w domu, wgrywanie obrazów — u góry pojawia się karta z paskiem, a gdy wiadomo, ile zostało, z licznikiem, np. „17 z 48”. Eksport PDF przerwiesz przyciskiem <span class=\"ui\">Anuluj</span>. Miniatury stron dużego projektu rysują się w tle (cienki pasek w panelu Strony) — możesz w tym czasie normalnie pracować.</p><figure class=\"kadr\"><img src=\"img/instrukcja/k-postep.png\" alt=\"Karta postępu przy eksporcie PDF\" loading=\"lazy\"><figcaption>Karta postępu przy eksporcie PDF</figcaption></figure>"}]},
  {"nr":"29","tytul":"Skróty klawiszowe","czesc":"Urządzenia i pomoc","ikona":"motyw","sekcje":[{"id":"29.1","tytul":"Lista skrótów","html":"<p>Na Macu zamiast <kbd>Ctrl</kbd> naciśnij <kbd>⌘</kbd>. W edytorze tę listę pokaże klawisz <kbd>?</kbd>. W trakcie pisania tekstu działają tylko skróty z grupy „Tekst”.</p><p><kbd>Ctrl</kbd>+<kbd>K</kbd> otwiera paletę poleceń: wpisz kilka liter nazwy polecenia i naciśnij <kbd>Enter</kbd>.</p><div data-wstaw=\"skroty\"></div>"}]},
  {"nr":"30","tytul":"Słowniczek","czesc":"Urządzenia i pomoc","ikona":"motyw","sekcje":[{"id":"30.1","tytul":"Pojęcia","html":"<div class=\"tabela-instrukcji\"><table><thead><tr><th>Pojęcie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><b>Biały poddruk</b></td><td>Warstwa białej farby pod kolorami — potrzebna przy druku na przezroczystym, kolorowym albo metalizowanym podłożu.</td></tr><tr><td><b>Big, bigowanie</b></td><td>Wgniecenie w kartonie (np. okładki), po którym karton zgina się równo i nie pęka.</td></tr><tr><td><b>Blok (książki)</b></td><td>Wszystkie kartki środka książki razem, bez okładki.</td></tr><tr><td><b>Blok (serii)</b></td><td>Strona albo kilka sąsiednich stron serii, powielane razem.</td></tr><tr><td><b>Broszura</b></td><td>Kilka arkuszy złożonych na pół i zszytych w grzbiecie; strony trzeba na arkuszach odpowiednio ułożyć (impozycja).</td></tr><tr><td><b>CMYK</b></td><td>Cztery farby drukarskie: cyjan, magenta, żółty, czarny. Kolory na ekranie (RGB) drukarnia przelicza na CMYK.</td></tr><tr><td><b>Dpi</b></td><td>Liczba punktów obrazu na cal w rozmiarze druku. Zdjęcie do druku powinno mieć co najmniej 300 dpi.</td></tr><tr><td><b>Element</b></td><td>Wszystko, co stoi na stronie: tekst, kształt, linia, obraz, tabela, grupa.</td></tr><tr><td><b>Falc (złam)</b></td><td>Linia, wzdłuż której składa się arkusz (np. ulotkę na trzy); na kartonie poprzedza go big.</td></tr><tr><td><b>Format</b></td><td>Wymiary strony po przycięciu, np. A5 = 148 × 210 mm.</td></tr><tr><td><b>Gradient (przejście)</b></td><td>Płynne przejście między kolorami w wypełnieniu, także do przezroczystości.</td></tr><tr><td><b>Gramatura</b></td><td>Grubość papieru podawana jako masa metra kwadratowego (g/m²) — od niej zależy m.in. szerokość grzbietu.</td></tr><tr><td><b>Grzbiet</b></td><td>Część okładki między przodem a tyłem; jego szerokość zależy od liczby stron i papieru. W rozkładówce — miejsce zszycia.</td></tr><tr><td><b>Impozycja</b></td><td>Ułożenie stron na arkuszu do druku tak, aby po złożeniu i przycięciu były w dobrej kolejności (np. broszura).</td></tr><tr><td><b>Interlinia</b></td><td>Odległość między kolejnymi wierszami tekstu.</td></tr><tr><td><b>Justowanie</b></td><td>Wyrównanie tekstu do obu krawędzi ramki — wiersze mają równą długość.</td></tr><tr><td><b>Kadrowanie</b></td><td>Wybór części zdjęcia, która jest widoczna w ramce.</td></tr><tr><td><b>Kapitałka</b></td><td>Pasek tkaniny na górze i dole grzbietu bloku w twardej oprawie.</td></tr><tr><td><b>Kolor dodatkowy (Pantone)</b></td><td>Gotowo zmieszana farba o dokładnym odcieniu, drukowana osobno obok CMYK.</td></tr><tr><td><b>Krycie</b></td><td>Przezroczystość elementu albo koloru: 100% — w pełni widoczny, 0% — niewidoczny.</td></tr><tr><td><b>Lakier wybiórczy</b></td><td>Błyszczący lakier tylko na wybranych miejscach strony, np. na tytule.</td></tr><tr><td><b>Linia bazowa</b></td><td>Niewidoczna linia, na której „stoją” litery. Siatka linii bazowych wyrównuje wiersze w sąsiednich kolumnach i na stronach.</td></tr><tr><td><b>Łącznik</b></td><td>Adres, przez który asystent AI pracuje w Twoich projektach.</td></tr><tr><td><b>Makieta</b></td><td>Projekt publikacji strona po stronie; makieta 3D — podgląd wydrukowanej rzeczy (książki, kalendarza).</td></tr><tr><td><b>Margines</b></td><td>Pas przy brzegu strony, w którym nie stawia się tekstu.</td></tr><tr><td><b>Miękkie krawędzie</b></td><td>Brzeg zdjęcia albo kształtu płynnie przechodzący w przezroczystość.</td></tr><tr><td><b>Nadruk (overprint)</b></td><td>Farba drukowana na farbie pod spodem, bez wycinania jej — ważne przy czarnym tekście i uszlachetnieniach.</td></tr><tr><td><b>Obwoluta</b></td><td>Papierowa okładka zakładana na twardą oprawę, z dwoma skrzydełkami zawiniętymi do środka (<span class=\"zobacz\">→</span> <a href=\"#\" data-cel=\"11.11\">Sekcje specjalne: obwoluta, ulotka, kalendarze, wykrojniki, użytki</a>).</td></tr><tr><td><b>Oprawa</b></td><td>Sposób połączenia kartek: zeszytowa (zszywki), klejona (miękka okładka), twarda, na spirali.</td></tr><tr><td><b>PDF/X-4</b></td><td>Odmiana PDF dla drukarni: osadzone czcionki, zapisany profil kolorów, przezroczystości bez spłaszczania.</td></tr><tr><td><b>Perforacja</b></td><td>Linia drobnych nacięć, po której łatwo oderwać część arkusza, np. kartkę kalendarza.</td></tr><tr><td><b>Pokrycie farbą</b></td><td>Suma farb CMYK w jednym miejscu (w %). Zbyt duże (zwykle ponad 300%) sprawia, że farba nie schnie.</td></tr><tr><td><b>Pole dokumentu</b></td><td>Pole wynikające z projektu: numer strony, sekcja, data.</td></tr><tr><td><b>Pole</b></td><td>Nazwa w klamrach, np. <code>{dzien}</code>; na gotowej stronie zamienia się w wartość.</td></tr><tr><td><b>Profil kolorów (ICC)</b></td><td>Opis maszyny i papieru drukarni; przy przeliczaniu na CMYK daje kolory jak najbliższe zamierzonym.</td></tr><tr><td><b>Prowadnica</b></td><td>Linia pomocnicza na stronie do wyrównywania elementów; nie drukuje się.</td></tr><tr><td><b>Rozdzielczość</b></td><td>Zob. Dpi.</td></tr><tr><td><b>Rozkładówka</b></td><td>Lewa i prawa strona obok siebie, jak w otwartej książce.</td></tr><tr><td><b>Sekcja</b></td><td>Część publikacji z własnym formatem, marginesami i numeracją, np. okładka i środek.</td></tr><tr><td><b>Separacje</b></td><td>Osobne płyty drukarskie dla każdej farby (C, M, Y, K, kolory dodatkowe, uszlachetnienia).</td></tr><tr><td><b>Seria</b></td><td>Powielanie strony albo bloku dla kolejnych wierszy tabeli.</td></tr><tr><td><b>Składka</b></td><td>Arkusz złożony w kilka kartek — książkę szyje się ze składek po 4, 8, 16 albo 32 strony.</td></tr><tr><td><b>Skrzydełko</b></td><td>Część obwoluty albo okładki zawinięta do środka za płytę okładki.</td></tr><tr><td><b>Spad</b></td><td>Kilka milimetrów za brzegiem strony; tła i zdjęcia wychodzą aż tam, a drukarnia je odcina.</td></tr><tr><td><b>Styl</b></td><td>Zapisany wygląd tekstu, zmieniany naraz we wszystkich tekstach.</td></tr><tr><td><b>Tabela danych</b></td><td>Arkusz w projekcie, z którego biorą się pola i serie — nie mylić z tabelą na stronie.</td></tr><tr><td><b>Tłoczenie</b></td><td>Wypukły albo wklęsły wzór wyciśnięty w papierze.</td></tr><tr><td><b>Uszlachetnienie</b></td><td>Dodatkowe wykończenie druku: lakier, złocenie (folia), tłoczenie, biały poddruk.</td></tr><tr><td><b>Użytek</b></td><td>Jeden egzemplarz małej rzeczy (wizytówki, naklejki) na arkuszu drukarskim – na jednym arkuszu mieści się ich wiele.</td></tr><tr><td><b>Wdowa i sierota</b></td><td>Pojedynczy wiersz akapitu, który został sam na końcu albo na początku kolumny lub strony.</td></tr><tr><td><b>Wektor</b></td><td>Rysunek opisany kształtami, a nie pikselami — ostry w każdym powiększeniu (teksty, kształty, PDF wektorowy).</td></tr><tr><td><b>Wiersz pomijany</b></td><td>Wiersz <code>[pomiń]</code>: zajmuje miejsce w bloku, ale jego strona nie powstaje.</td></tr><tr><td><b>Wyklejka</b></td><td>Kartka łącząca blok książki z twardą okładką, przyklejona do wnętrza okładki.</td></tr><tr><td><b>Wykrojnik</b></td><td>Kształt, po którym drukarnia wycina i biguje arkusz (koperta, pudełko, naklejka); w PDF osobny kolor CutContour.</td></tr><tr><td><b>Wzorzec</b></td><td>Wspólne elementy wielu stron: tło, stopka, numer strony.</td></tr><tr><td><b>Złocenie (folia)</b></td><td>Błyszcząca folia (złota, srebrna, kolorowa) przenoszona na papier w wybranych miejscach.</td></tr><tr><td><b>Znaki cięcia</b></td><td>Kreski w pliku PDF, które pokazują drukarni, gdzie ciąć.</td></tr><tr><td><b>Żywa pagina</b></td><td>Tekst u góry albo dołu strony powtarzany na wielu stronach, np. tytuł rozdziału.</td></tr></tbody></table></div>"}]},
];
